// Malayalam meanings, written with tools/builders/ml-meanings/apply-lib.py.
import type { MeaningPack } from '../../types';

export const mlLib12: MeaningPack = {
  lang: 'ml',
  texts: {
    "sundarakanda-35": {
      "verses": {
        "0.0": "വാനരശ്രേഷ്ഠൻ പറഞ്ഞ ആ രാമകഥ കേട്ട വൈദേഹി മധുരമായ ശബ്ദത്തിൽ ഈ ദയാപൂർവ്വമായ വാക്കുകൾ പറഞ്ഞു:",
        "0.1": "\"നീ രാമനെ എങ്ങനെ കണ്ടു? ലക്ഷ്മണനെ നിനക്ക് എങ്ങനെ അറിയാം? വാനരന്മാരും മനുഷ്യരും എങ്ങനെ ഒന്നിച്ചു?",
        "0.2": "\"വാനരാ, എനിക്ക് ദുഃഖം അടക്കാനാവാതെ വരാതിരിക്കാൻ രാമന്റെയും ലക്ഷ്മണന്റെയും ലക്ഷണങ്ങൾ വീണ്ടും പറയൂ.",
        "0.3": "\"അവന്റെ ശരീരപ്രകൃതി എങ്ങനെയാണ്, രൂപം എങ്ങനെയാണ്? തുടകളും കൈകളും എങ്ങനെയുള്ളവയാണ്? ലക്ഷ്മണനെക്കുറിച്ചും പറയൂ.\"",
        "0.4": "വൈദേഹി ഇങ്ങനെ ചോദിച്ചപ്പോൾ, വായുപുത്രനായ ഹനുമാൻ രാമനെ യഥാർത്ഥ രൂപത്തിൽ വർണ്ണിച്ചുതുടങ്ങി.",
        "0.5": "\"നീ അറിഞ്ഞിരിക്കെത്തന്നെ, താമരക്കണ്ണുള്ളവളേ, നിന്റെ ഭർത്താവിന്റെയും ലക്ഷ്മണന്റെയും ശരീരലക്ഷണങ്ങൾ എന്നോട് ചോദിക്കുന്നു; അത് നിനക്ക് എത്ര ഭാഗ്യം.",
        "0.6": "\"വിശാലനേത്രയായവളേ, ഞാൻ നിരീക്ഷിച്ചതുപോലെ രാമന്റെയും ലക്ഷ്മണന്റെയും ലക്ഷണങ്ങൾ എന്നിൽനിന്ന് കേൾക്കൂ.",
        "0.7": "\"രാമന് താമരദളങ്ങൾപോലുള്ള കണ്ണുകളും പൂർണ്ണചന്ദ്രനെപ്പോലുള്ള മുഖവുമുണ്ട്; ജനകപുത്രീ, ജന്മനാ സൗന്ദര്യവും മര്യാദയും അവനിലുണ്ട്.",
        "0.8": "\"തേജസ്സിൽ സൂര്യനെപ്പോലെയും ക്ഷമയിൽ ഭൂമിയെപ്പോലെയും ജ്ഞാനത്തിൽ ബൃഹസ്പതിക്കു തുല്യനും കീർത്തിയിൽ ഇന്ദ്രനെപ്പോലെയുമാണ് അവൻ.",
        "0.9": "\"ജീവലോകത്തിന്റെയും തന്റെ ജനങ്ങളുടെയും സംരക്ഷകനായ അവൻ, സ്വന്തം നടപ്പിന്റെയും ധർമ്മത്തിന്റെയും കാവൽക്കാരനും ശത്രുക്കളെ ദഹിപ്പിക്കുന്നവനുമാണ്.",
        "0.10": "\"സുന്ദരീ, രാമൻ ലോകത്തിന്റെയും നാല് വർണ്ണങ്ങളുടെയും സംരക്ഷകനാണ്; ലോകമര്യാദകൾ അവൻ സ്ഥാപിക്കുകയും മറ്റുള്ളവരെക്കൊണ്ട് പാലിപ്പിക്കുകയും ചെയ്യുന്നു.",
        "0.11": "\"തേജസ്വിയും മഹാബഹുമാനിതനും ബ്രഹ്മചര്യവ്രതത്തിൽ ഉറച്ചവനുമായ അവന് നന്മയ്ക്ക് പ്രതിഫലം നൽകാനും കർമ്മങ്ങൾ എങ്ങനെ നടത്തണമെന്നും അറിയാം.",
        "0.12": "\"രാജനീതിയിൽ പരിശീലനം നേടിയവനും ബ്രാഹ്മണരെ സേവിക്കുന്നവനും ജ്ഞാനസമ്പന്നനും നല്ല സ്വഭാവമുള്ളവനും വിനയശീലനും ശത്രുക്കളെ ദഹിപ്പിക്കുന്നവനുമാണ്.",
        "0.13": "\"യജുർവേദത്തിൽ പരിശീലനം നേടിയ അവൻ വേദജ്ഞരാൽ മഹാബഹുമാനിതനാണ്; ധനുർവിദ്യയിലും വേദങ്ങളിലും വേദാംഗങ്ങളിലും അവൻ നിപുണനാണ്.",
        "0.14": "\"വിശാലമായ തോളുകളും ബലമുള്ള കൈകളും ശംഖുപോലുള്ള കഴുത്തും മനോഹരമായ മുഖവും, നന്നായി മറഞ്ഞ കോളർബോണുകളും, സുന്ദരവും ചുവപ്പുകലർന്ന കണ്ണുകളുമുള്ളവൻ; മനുഷ്യർക്കിടയിൽ അവൻ രാമൻ എന്നറിയപ്പെടുന്നു.",
        "0.15": "\"അവന്റെ ശബ്ദം ചെണ്ടപോലെ മുഴങ്ങുന്നു; നിറം മിനുസമുള്ളതാണ്; അവൻ ഗാംഭീര്യമുള്ളവനും ശരീരാവയവങ്ങൾ സമമായവനും കറുത്ത നിറമുള്ളവനുമാണ്.",
        "0.16": "\"ശരീരത്തിലെ മൂന്ന് ഭാഗങ്ങളിൽ ഉറപ്പുള്ളവനും മൂന്നിൽ നീളമുള്ളവനും മൂന്നിൽ സമമായവനും മൂന്നിൽ ഉയർന്നവനും മൂന്നിൽ ചെമ്പുനിറമുള്ളവനും മൂന്നിൽ മിനുസമുള്ളവനും എപ്പോഴും മൂന്നിൽ ആഴമുള്ളവനുമാണ്.",
        "0.17": "\"അവന് മൂന്ന് മടക്കുകളുണ്ട്; മൂന്നിടത്ത് വളഞ്ഞവനാണ്; നാലിടത്ത് ചെറുതാണ്; തലയിൽ മൂന്ന് ചുഴികളുണ്ട്. തള്ളവിരലിൽ നാല് രേഖകളും നെറ്റിയിൽ നാല് രേഖകളും; ഉയരം നാല് മുഴം; നാല് ഭാഗങ്ങളും സമമാണ്.",
        "0.18": "\"അവന്റെ അവയവങ്ങളിൽ പതിന്നാലു ജോഡികൾ സമമാണ്; നാല് മുന്നോട്ടുന്തിയ പല്ലുകളും നാലുതരം നടത്തവുമുണ്ട്; വലിയ ചുണ്ടും താടിയെല്ലും മൂക്കും; അഞ്ച് ഭാഗങ്ങളിൽ മിനുസമുള്ളവനും എട്ട് ഭാഗങ്ങൾ നീളമുള്ളവനുമാണ്.",
        "0.19": "\"രാഘവന് താമരപോലുള്ള പത്തും വലിയ പത്തും ഭാഗങ്ങളുണ്ട്; തേജസ്സും കീർത്തിയും യശസ്സും എന്നീ മൂന്നിനാൽ അവൻ വ്യാപിച്ചിരിക്കുന്നു; രണ്ട് വെള്ള ഭാഗങ്ങളുണ്ട്; ആറിൽ ഉയർന്നും ഒമ്പതിൽ മെലിഞ്ഞുമിരിക്കുന്നു; മൂന്നുകൊണ്ട് എല്ലാം വ്യാപിക്കുന്നു.",
        "0.20": "\"സത്യത്തിലും ധർമ്മത്തിലും ഉറച്ചവനും തേജസ്വിയും ജനങ്ങളെ ഒരുമിപ്പിക്കാനും അനുഗ്രഹിക്കാനും ആഗ്രഹിക്കുന്നവനുമാണ്. ഉചിതമായ സ്ഥലവും സമയവും അവനറിയാം; ലോകത്തോടാകെ ദയയോടെ സംസാരിക്കുന്നു.",
        "0.21": "\"അവന്റെ അർദ്ധസഹോദരനായ സൗമിത്രി അതിരില്ലാത്ത തേജസ്സുള്ളവനാണ്; ഭക്തിയിലും രൂപത്തിലും ഗുണങ്ങളിലും അവനെപ്പോലെ തന്നെയാണ്.",
        "0.22": "\"അവൻ സ്വർണ്ണനിറമുള്ളവനും തേജസ്വിയുമാണ്; പ്രസിദ്ധനായ രാമൻ കറുത്തവനാണ്. നിന്നെ കാണുന്നത് ഉത്സവമാകുന്ന ആ രണ്ട് മനുഷ്യസിംഹങ്ങൾ,",
        "0.23": "\"ഭൂമിമുഴുവൻ തിരഞ്ഞ് ഞങ്ങളെ കണ്ടുമുട്ടി; നിന്നെമാത്രം അന്വേഷിച്ച് ഭൂമിയിൽ അലഞ്ഞവർ,",
        "0.24": "\"ഋശ്യമൂകത്തിന്റെ അടിയിൽ, അനേകം മരങ്ങൾ നിറഞ്ഞ സ്ഥലത്ത്, ജ്യേഷ്ഠനാൽ രാജ്യഭ്രഷ്ടനാക്കപ്പെട്ട വാനരരാജാവിനെ കണ്ടു.",
        "0.25": "\"കാണാൻ മനോഹരനായ സുഗ്രീവൻ, സഹോദരനെക്കുറിച്ചുള്ള ഭയത്താൽ പീഡിതനായി അവിടെ ഇരിക്കുന്നു. വാക്കുപാലിക്കുന്ന ആ വാനരരാജാവ് സുഗ്രീവനെ ഞങ്ങൾ സേവിക്കുന്നു.",
        "0.26": "\"ജ്യേഷ്ഠനാൽ രാജ്യത്തുനിന്ന് പുറത്താക്കപ്പെട്ട് അദ്ദേഹത്തിന്റെ പരിചാരകരായി. അപ്പോൾ മരവുരി ധരിച്ച് കൈകളിൽ മികച്ച വില്ലുകളുമായി ആ രണ്ടുപേർ,",
        "0.27": "\"ഋശ്യമൂകപർവതത്തിലെ മനോഹരമായ ഒരിടത്ത് എത്തി. വില്ലേന്തിയ ആ രണ്ട് മനുഷ്യസിംഹങ്ങളെ കണ്ട വാനരശ്രേഷ്ഠൻ,",
        "0.28": "\"ഭയത്താൽ പരിഭ്രാന്തനായി ആ പർവതശിഖരത്തിലേക്ക് ചാടിക്കയറി. അപ്പോൾ ശിഖരത്തിൽ നിന്ന വാനരരാജാവ്,",
        "0.29": "\"എന്നെ അവരുടെ അടുത്തേക്ക് വേഗം അയച്ചു. സുഗ്രീവന്റെ വാക്കനുസരിച്ച് ഞാൻ ആ രണ്ട് മനുഷ്യശ്രേഷ്ഠന്മാരെ സമീപിച്ചു.",
        "0.30": "\"സൗന്ദര്യവും ശുഭലക്ഷണങ്ങളുമുള്ള അവർ കൈകൂപ്പി നിന്നു. കാര്യത്തിന്റെ സത്യം എന്നിൽനിന്ന് അറിഞ്ഞ് അവർ സ്നേഹത്താൽ നിറഞ്ഞു.",
        "0.31": "\"ആ രണ്ട് മനുഷ്യശ്രേഷ്ഠന്മാരെ എന്റെ പുറത്തേറ്റി ഞാൻ ആ സ്ഥലത്തെത്തിച്ചു; മഹാത്മാവായ സുഗ്രീവന് മുറപ്രകാരം അവരെ പരിചയപ്പെടുത്തി.",
        "0.32": "\"അവർ തമ്മിലുള്ള സംഭാഷണത്തിൽനിന്ന് വലിയ സ്നേഹമുണ്ടായി. അവിടെ പ്രസിദ്ധരായ ആ രണ്ടുപേർ, വാനരരാജാവും മനുഷ്യരാജാവും,",
        "0.33": "\"മുൻപ് സംഭവിച്ചതു പറഞ്ഞ് പരസ്പരം ആശ്വസിപ്പിച്ചു. പിന്നെ ലക്ഷ്മണന്റെ ജ്യേഷ്ഠൻ സുഗ്രീവനെ ആശ്വസിപ്പിച്ചു.",
        "0.34": "\"മഹാബലശാലിയായ സഹോദരൻ വാലിയാൽ ഒരു സ്ത്രീക്കുവേണ്ടി രാജ്യത്തുനിന്ന് പുറത്താക്കപ്പെട്ടവൻ. അനന്തമായ കർമ്മങ്ങളുള്ള രാമന് നിന്നെ നഷ്ടപ്പെട്ടതിൽ ഉണ്ടായ ദുഃഖം,",
        "0.35": "\"ലക്ഷ്മണൻ വാനരരാജാവായ സുഗ്രീവനോട് പറഞ്ഞു. ലക്ഷ്മണൻ പറഞ്ഞ വാക്കുകൾ കേട്ട വാനരരാജാവ്,",
        "0.36": "\"ഗ്രഹണം ബാധിച്ച സൂര്യനെപ്പോലെ തേജസ്സറ്റുപോയി. പിന്നെ രാക്ഷസൻ കൊണ്ടുപോകുമ്പോൾ നിന്റെ ശരീരത്തിൽ തിളങ്ങിയിരുന്ന ആഭരണങ്ങൾ,",
        "0.37": "\"നിലത്ത് വീണുകിടന്ന ആഭരണക്കൂട്ടങ്ങൾ ഇവയെല്ലാം വാനരസേനാനായകന്മാർ രാമന്റെ അടുത്തെത്തിച്ചു.",
        "0.38": "\"നീ എവിടെ പോയെന്ന് അവർക്കറിയില്ലെങ്കിലും സന്തോഷത്തോടെ അവ കാണിച്ചു. രാമന് നൽകിയ ആ ആഭരണങ്ങൾ ഞാനാണ് ശേഖരിച്ചത്;",
        "0.39": "\"കിലുങ്ങിക്കൊണ്ട് വീണ് ചിതറിപ്പോയവ. അദ്ദേഹത്തിന് ബോധം നഷ്ടപ്പെട്ടപ്പോൾ, ആ മനോഹര വസ്തുക്കൾ പലവിധത്തിൽ മടിയിൽ വെച്ച്,",
        "0.40": "\"ആ ദേവതുല്യനായ പ്രഭു വിലപിച്ചു; അവയെ നോക്കി കരഞ്ഞും ആവർത്തിച്ച് ബോധം മറഞ്ഞും,",
        "0.41": "\"അവർ ദശരഥപുത്രന്റെ മനസ്സിൽ ദുഃഖാഗ്നി ജ്വലിപ്പിച്ചു.",
        "0.42": "\"ദുഃഖം ബാധിച്ച ആ മഹാത്മാവ് വളരെനേരം നിലത്തുകിടന്നു; ഞാനും പലവിധ വാക്കുകളാൽ അദ്ദേഹത്തെ വീണ്ടും കഷ്ടപ്പെട്ട് എഴുന്നേൽപ്പിച്ചു.",
        "0.43": "\"ആ വിലപ്പെട്ട ആഭരണങ്ങൾ നോക്കിയും ആവർത്തിച്ച് കാണിച്ചും, ലക്ഷ്മണനോടൊപ്പം രാഘവൻ അവ സുഗ്രീവന്റെ സംരക്ഷണയിൽ ഏൽപ്പിച്ചു.",
        "0.44": "\"കുലീനയായ സ്ത്രീയേ, നിന്നെ കാണാതെ രാഘവൻ വലിയ തീജ്വാലയുള്ള അഗ്നിപർവതംപോലെ നിരന്തരം ഉരുകുന്നു.",
        "0.45": "\"നിനക്കുവേണ്ടി ഉറക്കമില്ലായ്മയും ദുഃഖവും ഉത്കണ്ഠയും മഹാത്മാവായ രാഘവനെ പീഡിപ്പിക്കുന്നു; തീയ് തീപ്പുരയെ ചൂടാക്കുന്നതുപോലെ.",
        "0.46": "\"നിന്നെ കാണാത്തതിലുള്ള ദുഃഖത്താൽ രാഘവൻ ഇളകിപ്പോകുന്നു; വലിയ ഭൂകമ്പത്താൽ മഹാപർവതം ഇളകുന്നതുപോലെ.",
        "0.47": "\"മനോഹരമായ വനങ്ങളിലും പുഴകളിലും വെള്ളച്ചാട്ടങ്ങളിലും അലഞ്ഞുനടന്നിട്ടും, രാജകുമാരീ, നിന്നെ കാണാത്തതിനാൽ അദ്ദേഹത്തിന് ഒരു സന്തോഷവും കിട്ടുന്നില്ല.",
        "0.48": "\"മനുഷ്യസിംഹനായ രാഘവൻ, ജനകപുത്രീ, തന്റെ മിത്രങ്ങളോടും ബന്ധുക്കളോടുംകൂടി രാവണനെ വധിച്ച് ഉടൻ നിന്നെ തിരിച്ചുപിടിക്കും.",
        "0.49": "\"പിന്നെ രാമനും സുഗ്രീവനും ഒന്നിച്ച് ഒരു കരാറുണ്ടാക്കി: വാലിയെ വധിക്കാനും നിന്നെ അന്വേഷിക്കാനും.",
        "0.50": "\"പിന്നെ ആ രണ്ട് വീരരാജകുമാരന്മാർ കിഷ്കിന്ധയിലേക്ക് പോയി; യുദ്ധത്തിൽ വാനരരാജാവായ വാലി വീഴ്ത്തപ്പെട്ടു.",
        "0.51": "\"വാലിയെ യുദ്ധത്തിൽ വേഗത്തിൽ വധിച്ച രാമൻ, കരടികളുടെയും വാനരന്മാരുടെയും എല്ലാ സൈന്യങ്ങൾക്കും സുഗ്രീവനെ നാഥനാക്കി.",
        "0.52": "\"ഇങ്ങനെയാണ് രാമനും സുഗ്രീവനും തമ്മിലുള്ള സഖ്യം ഉണ്ടായത്, രാജ്ഞീ. അവരുടെ ദൂതനായി വന്ന എന്നെ ഹനുമാനായി അറിയുക.",
        "0.53": "\"രാജ്യം തിരിച്ചുപിടിച്ച സുഗ്രീവൻ, തന്റെ മഹാവാനരന്മാരെ വിളിച്ചുകൂട്ടി; നിനക്കുവേണ്ടി ശക്തരായവരെ പത്തുദിക്കുകളിലേക്കും അയച്ചു.",
        "0.54": "\"വാനരരാജാവായ സുഗ്രീവന്റെ കല്പനപ്രകാരം ആ ശക്തരായവർ പർവതരാജാക്കന്മാരെപ്പോലെ എല്ലാ ദിക്കുകളിലേക്കും ഭൂമിയിലൂടെ പുറപ്പെട്ടു.",
        "0.55": "\"പിന്നെ സുഗ്രീവന്റെ കല്പനയെക്കുറിച്ചുള്ള ഉത്കണ്ഠയോടെ, ഞങ്ങളും മറ്റ് വാനരന്മാരും ഭൂമിമുഴുവൻ തിരഞ്ഞ് അലയുകയാണ്.",
        "0.56": "\"വാനരന്മാരിലെ ശ്രേഷ്ഠനും വാലിയുടെ മഹാബലശാലിയായ പുത്രനുമായ തേജസ്വിയായ അംഗദൻ സൈന്യത്തിന്റെ മൂന്നിലൊന്നിനാൽ ചുറ്റപ്പെട്ട് പുറപ്പെട്ടു.",
        "0.57": "\"പർവതങ്ങളിൽ ശ്രേഷ്ഠനായ വിന്ധ്യത്തിൽ ഞങ്ങൾ വഴിതെറ്റി; ദുഃഖം നിറഞ്ഞ് ഞങ്ങൾ പല രാവുകളും പകലുകളും കഴിച്ചുകൂട്ടി.",
        "0.58": "\"ദൗത്യത്തെക്കുറിച്ച് നിരാശരായി, സമയപരിധി കഴിഞ്ഞതിനാലും വാനരരാജാവിനെ ഭയന്നും ഞങ്ങൾ ജീവൻ ഉപേക്ഷിക്കാൻ തയ്യാറായി.",
        "0.59": "\"പർവതകോട്ടകളിലും പുഴകളിലും വെള്ളച്ചാട്ടങ്ങളിലും തിരഞ്ഞിട്ടും, രാജ്ഞീ, നിന്റെ ഒരു അടയാളവും കണ്ടെത്താനായില്ല; ഞങ്ങൾ ജീവൻ ഉപേക്ഷിക്കാൻ തീരുമാനിച്ചു.",
        "0.60": "\"അപ്പോൾ ആ പർവതശിഖരത്തിൽ ഞങ്ങൾ മരണംവരെ ഉപവസിക്കാനായി ഇരുന്നു. ആ ഉപവാസത്തിലിരിക്കുന്ന എല്ലാ പ്രധാന വാനരന്മാരെയും കണ്ടപ്പോൾ,",
        "0.61": "\"ദുഃഖസമുദ്രത്തിൽ ആഴ്ന്ന അംഗദൻ, വൈദേഹീ, നിന്റെ നഷ്ടത്തെക്കുറിച്ചും വാലിയുടെ വധത്തെക്കുറിച്ചും വിലപിച്ചു.",
        "0.62": "\"ഞങ്ങളുടെ മരണംവരെയുള്ള ഉപവാസത്തെക്കുറിച്ചും ജടായുവിന്റെ മരണത്തെക്കുറിച്ചും വിലപിച്ചു. യജമാനന്റെ കല്പനയോർത്ത് നിരാശരായി ഞങ്ങൾ മരിക്കാൻ ആഗ്രഹിക്കുമ്പോൾ,",
        "0.63": "\"ഞങ്ങളുടെ കാര്യത്തിനെന്നപോലെ ഒരു വലിയ ശക്തനായ പക്ഷി വന്നു; കഴുകന്മാരുടെ രാജാവിന്റെ സഹോദരനും, സമ്പാതി എന്ന കഴുകൻ രാജാവുമായിരുന്നു അത്.",
        "0.64": "\"സഹോദരന്റെ കൊലപാതകം കേട്ട് കോപത്തോടെ അവൻ പറഞ്ഞു: 'ആരാണ് എന്റെ അനുജനെ കൊന്നത്? എവിടെയാണ് അവനെ വീഴ്ത്തിയത്?",
        "0.65": "\"'വാനരശ്രേഷ്ഠാ, നിന്നിൽനിന്ന് അത് കേൾക്കാൻ ഞാൻ ആഗ്രഹിക്കുന്നു.' ജനസ്ഥാനത്ത് നടന്ന ആ മഹാകൊലപാതകത്തെക്കുറിച്ച് അംഗദൻ അവനോട് പറഞ്ഞു;",
        "0.66": "\"നിനക്കുവേണ്ടി ഭയങ്കരനായ രാക്ഷസൻ ചെയ്തത്, സംഭവിച്ചതുപോലെതന്നെ. ജടായുവിന്റെ മരണം കേട്ട് അരുണന്റെ പുത്രൻ ദുഃഖിച്ചു.",
        "0.67": "\"മനോഹരിയായ സ്ത്രീയേ, നീ രാവണന്റെ ഭവനത്തിലാണ് ജീവിക്കുന്നതെന്ന് അവൻ ഞങ്ങളോട് പറഞ്ഞു. ഞങ്ങളുടെ സന്തോഷം വർദ്ധിപ്പിച്ച സമ്പാതിയുടെ ആ വാക്കുകൾ കേട്ട്,",
        "0.68": "\"ഞങ്ങളെല്ലാവരും അംഗദന്റെ നേതൃത്വത്തിൽ പുറപ്പെട്ടു. വിന്ധ്യത്തിൽനിന്ന് ഉയർന്ന് സമുദ്രത്തിന്റെ അങ്ങേക്കരയിൽ എത്തി.",
        "0.69": "\"നിന്നെ കാണാൻ ആഗ്രഹിച്ച്, സന്തോഷത്തോടെയും ശക്തിയോടെയും അംഗദന്റെ നേതൃത്വത്തിലുള്ള വാനരന്മാരെല്ലാം തീരത്തിന്റെ അറ്റത്ത് എത്തി.",
        "0.70": "\"നിന്നെ കാണാൻ ആഗ്രഹിച്ചവർ വീണ്ടും ഭയങ്കരമായ ആകുലതയിൽ വീണു. അപ്പോൾ സമുദ്രത്തിന് മുന്നിൽ നിരാശരായ വാനരസൈന്യത്തെ ഞാൻ കണ്ടു.",
        "0.71": "\"ഞാൻ എന്റെ കഠിനഭയം കുടഞ്ഞുകളഞ്ഞ് നൂറു യോജന ചാടി. രാക്ഷസന്മാർ നിറഞ്ഞ ലങ്കയിൽ രാത്രിയിൽ ഞാൻ പ്രവേശിച്ചു.",
        "0.72": "\"ഞാൻ രാവണനെ കണ്ടു; ദുഃഖത്താൽ പീഡിതയായ നിന്നെയും കണ്ടു. കളങ്കമില്ലാത്തവളേ, ഇതെല്ലാം സംഭവിച്ചതുപോലെതന്നെ ഞാൻ നിന്നോട് പറഞ്ഞു.",
        "0.73": "\"രാജ്ഞീ, എന്നോട് സംസാരിക്കൂ; ഞാൻ ദശരഥപുത്രന്റെ ദൂതനാണ്. നിനക്കുവേണ്ടി ഇവിടെ വന്ന എന്നെ, രാമന്റെ ദൗത്യത്തിനയച്ച ആളായി അറിയുക.",
        "0.74": "\"വായുപുത്രനായ സുഗ്രീവന്റെ മന്ത്രിയാണ് ഞാൻ. ആയുധധാരികളിൽ ഉത്തമനായ നിന്റെ കാകുത്സ്ഥൻ സുഖമായിരിക്കുന്നു.",
        "0.75": "\"ശുഭലക്ഷണങ്ങളുള്ള ലക്ഷ്മണൻ ജ്യേഷ്ഠനെ സേവിക്കുന്നതിൽ അർപ്പിതനാണ്; രാജ്ഞീ, നിന്റെ മഹാബലശാലിയായ ഭർത്താവിന്റെ ക്ഷേമത്തിൽ അവൻ ശ്രദ്ധിക്കുന്നു.",
        "0.76": "\"സുഗ്രീവന്റെ വാക്കനുസരിച്ച് ഞാൻ മാത്രമാണ് ഇവിടെ വന്നത്. സഹായമില്ലാതെ ഒറ്റയ്ക്ക് സഞ്ചരിക്കുന്ന, ഇഷ്ടാനുസരണം ഏതു രൂപവും സ്വീകരിക്കാൻ കഴിവുള്ള ഞാൻ,",
        "0.77": "\"നിന്നിലേക്കുള്ള വഴി തേടി ഈ ദക്ഷിണദിക്ക് മുഴുവൻ സഞ്ചരിച്ചു. നിന്റെ നഷ്ടത്തിൽ വിലപിക്കുന്ന വാനരസൈന്യങ്ങളുടെ ദുഃഖം ഭാഗ്യവശാൽ ഞാൻ നീക്കും,",
        "0.78": "\"നിന്നെ കണ്ടെത്തിയെന്ന വാർത്തയാൽ. സമുദ്രം ചാടിക്കടന്ന എന്റെ ഈ യാത്ര ഭാഗ്യവശാൽ വൃഥാവിലായില്ല.",
        "0.79": "\"നിന്നെ കണ്ടെത്തി എന്ന ഈ മഹത്വം ഞാൻ നേടും, രാജ്ഞീ; മഹാബലശാലിയായ രാഘവൻ ഉടൻ നിന്റെ അടുത്തെത്തും,",
        "0.80": "\"രാക്ഷസരാജാവായ രാവണനെ മക്കളോടും ബന്ധുക്കളോടുംകൂടി വധിച്ചശേഷം. മാല്യവാൻ എന്നൊരു പർവതമുണ്ട്, വൈദേഹീ; പർവതങ്ങളിൽ ശ്രേഷ്ഠൻ.",
        "0.81": "\"അവിടെനിന്ന് കേസരിയെന്ന വാനരൻ ഗോകർണപർവതത്തിലേക്ക് പോയി; ദിവ്യമുനിമാരുടെ നിർദ്ദേശപ്രകാരം ആ മഹാവാനരനായ എന്റെ പിതാവ് സമുദ്രതീരത്തുവെച്ച് ശംബസാദനനെ വധിച്ചു.",
        "0.82": "\"ആ വാനരന്റെ ഭാര്യയിൽ വായുദേവനാൽ ഞാൻ ജനിച്ചു, മൈഥിലീ; എന്റെ സ്വന്തം പ്രവൃത്തികളാൽ ലോകത്ത് ഞാൻ ഹനുമാൻ എന്നറിയപ്പെടുന്നു.",
        "0.83": "\"നിന്റെ വിശ്വാസം നേടാനായി, വൈദേഹീ, നിന്റെ ഭർത്താവിന്റെ ഗുണങ്ങൾ ഞാൻ വിവരിച്ചു. അധികം വൈകാതെ, രാജ്ഞീ, രാഘവൻ നിശ്ചയമായും നിന്നെ ഇവിടെനിന്ന് കൊണ്ടുപോകും.\"",
        "0.84": "ഈ യുക്തികളാലും അടയാളങ്ങളാലും ആശ്വസിപ്പിക്കപ്പെട്ട സീത, ദുഃഖത്താൽ ക്ഷീണിച്ചവളായിരുന്നെങ്കിലും, അദ്ദേഹത്തെ ദൂതനായി തിരിച്ചറിഞ്ഞു.",
        "0.85": "ജാനകിക്ക് അതിരില്ലാത്ത സന്തോഷമുണ്ടായി; ആനന്ദത്തിൽ വളഞ്ഞ കൺപീലികളുള്ള കണ്ണുകളിൽനിന്ന് സന്തോഷാശ്രുക്കൾ പൊഴിച്ചു.",
        "0.86": "ചുവന്നും വെളുത്തും നീണ്ട കണ്ണുകളുള്ള ആ വിശാലനേത്രയുടെ മനോഹരമായ മുഖം, രാഹുവിൽനിന്ന് മോചിതനായ ചന്ദ്രനെപ്പോലെ തിളങ്ങി.",
        "0.87": "ഇനി അവൾ അദ്ദേഹം ഹനുമാൻ എന്ന വാനരനാണെന്നും മറ്റൊരാളല്ലെന്നും ഉറച്ചു വിശ്വസിച്ചു. പിന്നെ ഹനുമാൻ ആ മനോഹരിയായ സ്ത്രീയോട് കൂടുതൽ സംസാരിച്ചു:",
        "0.88": "\"ഇതെല്ലാം ഞാൻ പറഞ്ഞു; മൈഥിലീ, സമാധാനിക്കൂ. ഞാൻ എന്ത് ചെയ്യണം? നിനക്ക് എന്ത് ഇഷ്ടമാണ്? ഞാൻ തിരികെ പോകാം.\"",
        "0.89": "\"മഹർഷിമാരുടെ നിർദ്ദേശപ്രകാരം ആ വാനരവീരൻ യുദ്ധത്തിൽ അസുരൻ ശംബസാദനനെ വധിച്ചപ്പോൾ, അതിനു തുല്യശക്തിയുള്ള വാനരനായി ഞാൻ വായുദേവനിൽനിന്ന് ജനിച്ചു, മൈഥിലീ.\"",
        "0.90": "ഇങ്ങനെ ആദികാവ്യമായ, ശ്രീമദ് രാമായണത്തിലെ വാല്മീകി രചിച്ച സുന്ദരകാണ്ഡത്തിലെ മുപ്പത്തിയഞ്ചാം സർഗ്ഗം സമാപിച്ചു."
      },
      "summary": "സീതയെ പരീക്ഷിക്കാനായി അവൾ രാമന്റെ രൂപത്തെക്കുറിച്ച് ചോദിക്കുന്നു; ഹനുമാൻ രാമന്റെയും ലക്ഷ്മണന്റെയും ശരീരലക്ഷണങ്ങളും ഗുണങ്ങളും വിവരിക്കുന്നു. അവർ സുഗ്രീവനെ കണ്ടുമുട്ടിയതും താൻ ആരാണെന്നതും അദ്ദേഹം പറയുന്നു. സീത അദ്ദേഹത്തിൽ വിശ്വസിച്ചുതുടങ്ങുന്നു."
    },
    "sundarakanda-36": {
      "verses": {
        "0.0": "സീതയുടെ വിശ്വാസം നേടാനായി, തേജസ്വിയായ വായുപുത്രൻ ഹനുമാൻ വീണ്ടും വിനയത്തോടെ വാക്കുകൾ പറഞ്ഞു:",
        "0.1": "\"ഭാഗ്യവതിയായ സ്ത്രീയേ, ഞാൻ ജ്ഞാനിയായ രാമന്റെ ദൂതനായ ഒരു വാനരനാണ്. രാജ്ഞീ, രാമന്റെ പേര് കൊത്തിയ ഈ മോതിരം കാണൂ.",
        "0.2": "\"ആ മഹാത്മാവ് നൽകിയതാണിത്; നിന്റെ വിശ്വാസം നേടാനായി കൊണ്ടുവന്നതാണ്. ആശ്വസിക്കൂ, നിനക്ക് ഐശ്വര്യമുണ്ടാകട്ടെ; നിന്റെ ദുഃഖത്തിന്റെ ഫലം ഇപ്പോൾ അവസാനിച്ചിരിക്കുന്നു.\"",
        "0.3": "ഭർത്താവിന്റെ കൈയിലെ ആഭരണം വാങ്ങി നോക്കിയപ്പോൾ, ഭർത്താവുതന്നെ വന്നതുപോലെ ജാനകി സന്തോഷിച്ചു.",
        "0.4": "ചുവന്നും വെളുത്തും നീണ്ട കണ്ണുകളുള്ള അവളുടെ മനോഹരമായ മുഖം, രാഹുവിൽനിന്ന് മോചിതനായ ചന്ദ്രനെപ്പോലെ സന്തോഷത്താൽ തിളങ്ങി.",
        "0.5": "ഭർത്താവിന്റെ സന്ദേശത്താൽ ആഹ്ലാദിച്ചും സംതൃപ്തയായും ആ വിനീതയായ യുവതി, വാനരശ്രേഷ്ഠനെ ബഹുമാനിച്ച് പ്രശംസിച്ചു.",
        "0.6": "\"നീ ധീരനും കഴിവുള്ളവനും ബുദ്ധിമാനുമാണ്, വാനരശ്രേഷ്ഠാ; രാക്ഷസന്മാരുടെ ഈ വാസസ്ഥലത്ത് നീ ഒറ്റയ്ക്ക് കടന്നുചെന്നതുകൊണ്ട്.",
        "0.7": "\"നൂറു യോജന വീതിയുള്ള, സമുദ്രജീവികളുടെ വാസസ്ഥലമായ സമുദ്രം, നീ ചാടിക്കടന്നപ്പോൾ പശുവിന്റെ കുളമ്പടിപോലെ ചെറുതാക്കി; ധീരതയിൽ നീ പ്രശംസയ്ക്ക് അർഹനാണ്.",
        "0.8": "\"രാവണനെപ്പോലും ഭയമോ പരിഭ്രമമോ ഇല്ലാത്തതിനാൽ, വാനരശ്രേഷ്ഠാ, ഞാൻ നിന്നെ സാധാരണ വാനരനായി കാണുന്നില്ല.",
        "0.9": "\"രാമൻ നിന്നെ അയച്ചതാണെങ്കിൽ, വാനരശ്രേഷ്ഠാ, നിനക്ക് എന്നോട് സംസാരിക്കാൻ യോഗ്യതയുണ്ട്; ആത്മജ്ഞാനിയാണല്ലോ അവൻ.",
        "0.10": "\"അജയ്യനായ രാമൻ, ആരെയും പരീക്ഷിക്കാതെ, അവന്റെ പരാക്രമം അറിയാതെ അയക്കുകയില്ല; പ്രത്യേകിച്ച് എന്റെ അടുത്തേക്ക്.",
        "0.11": "\"ഭാഗ്യവശാൽ ധർമ്മിഷ്ഠനും വാക്കുപാലിക്കുന്നവനുമായ രാമൻ സുഖമായിരിക്കുന്നു; സുമിത്രയുടെ സന്തോഷം വർദ്ധിപ്പിക്കുന്ന തേജസ്വിയായ ലക്ഷ്മണനും സുഖമായിരിക്കുന്നു.",
        "0.12": "\"കാകുത്സ്ഥൻ സുഖമായിരുന്നെങ്കിൽ, യുഗാന്ത്യത്തിൽ ഉയരുന്ന അഗ്നിപോലെ കോപത്തോടെ കടൽ ചുറ്റിയ ഭൂമിയെ അവൻ ദഹിപ്പിക്കാത്തതെന്തുകൊണ്ട്?",
        "0.13": "\"അല്ലെങ്കിൽ, ആ രണ്ടുപേർക്ക് ദേവന്മാരെപ്പോലും കീഴടക്കാൻ കഴിയും; എന്റെ ദുഃഖങ്ങൾ ഇതുവരെ അവസാനിച്ചിട്ടില്ലെന്നാണ് ഞാൻ കരുതുന്നത്.",
        "0.14": "\"രാമൻ ദുഃഖിതനല്ലെന്ന് ഞാൻ ആശിക്കുന്നു; അവൻ പീഡിതനല്ലെന്ന് ഞാൻ ആശിക്കുന്നു. ആ പുരുഷശ്രേഷ്ഠൻ ചെയ്യേണ്ടത് അടുത്തതായി ചെയ്യുന്നുണ്ടോ?",
        "0.15": "\"അവൻ നിരാശനോ പരിഭ്രാന്തനോ അല്ലെന്നും, തന്റെ കാര്യങ്ങളിൽ ആശയക്കുഴപ്പത്തിലല്ലെന്നും ഞാൻ ആശിക്കുന്നു. രാജപുത്രൻ പുരുഷോചിതമായ പരിശ്രമം നടത്തുന്നുണ്ടോ?",
        "0.16": "\"ശത്രുക്കളെ ദഹിപ്പിക്കുന്ന, വിജയം ആഗ്രഹിക്കുന്ന, മിത്രങ്ങളോട് ദയയുള്ളവൻ, മിത്രങ്ങളോടും ശത്രുക്കളോടും രണ്ടും മൂന്നും തരത്തിലുള്ള രാജനീതി ഉപായങ്ങൾ പ്രയോഗിക്കുന്നുണ്ടോ?",
        "0.17": "\"അവൻ മിത്രങ്ങളെ നേടുന്നുണ്ടോ; സന്ധിക്കായി ശത്രുക്കൾ അവനെ സമീപിക്കുന്നുണ്ടോ? നല്ല മിത്രങ്ങൾ അവനുണ്ടോ; അവരാൽ അവൻ ബഹുമാനിക്കപ്പെടുന്നുണ്ടോ?",
        "0.18": "\"രാജകുമാരൻ ദേവന്മാരുടെ അനുഗ്രഹത്തിനായി പ്രാർത്ഥിക്കുന്നുണ്ടോ? മനുഷ്യപരിശ്രമത്തിലും വിധിയിലും അവൻ ആശ്രയിക്കുന്നുണ്ടോ?",
        "0.19": "\"ഞാൻ അകന്നിരിക്കുന്നതുകൊണ്ട് രാഘവന് എന്നോടുള്ള സ്നേഹം നഷ്ടപ്പെട്ടിട്ടില്ലേ? ഈ ആപത്തിൽനിന്ന് രാഘവൻ എന്നെ മോചിപ്പിക്കുമോ?",
        "0.20": "\"എപ്പോഴും ആശ്വാസം ലഭിച്ചിരുന്നവനും ഒരിക്കലും കഷ്ടപ്പാട് അനുഭവിക്കാത്തവനുമായ രാമൻ ഈ വലിയ ദുഃഖത്തിൽ മുങ്ങിപ്പോകുന്നില്ലെന്ന് ഞാൻ ആശിക്കുന്നു?",
        "0.21": "\"കൗസല്യയുടെയും സുമിത്രയുടെയും ഭരതന്റെയും ക്ഷേമവാർത്ത അവൻ പതിവായി കേൾക്കുന്നുണ്ടോ?",
        "0.22": "\"ബഹുമാന്യനായ രാഘവൻ എന്നെ ഓർത്ത് ദുഃഖിക്കുന്നുണ്ടോ? രാമന്റെ മനസ്സ് മറ്റെവിടെയെങ്കിലും തിരിഞ്ഞിട്ടില്ലേ? അവൻ എന്നെ രക്ഷിക്കുമോ?",
        "0.23": "\"സഹോദരനെ സ്നേഹിക്കുന്ന ഭരതൻ, എനിക്കുവേണ്ടി മന്ത്രിമാരാൽ സംരക്ഷിക്കപ്പെട്ട ഭയങ്കരമായ അക്ഷൗഹിണി സേനയെ അയയ്ക്കുമോ?",
        "0.24": "\"പല്ലും നഖവുമായി ആയുധമേന്തിയ വീരന്മാരായ വാനരന്മാരാൽ ചുറ്റപ്പെട്ട്, തേജസ്വിയായ വാനരരാജാവ് സുഗ്രീവൻ എനിക്കുവേണ്ടി വരുമോ?",
        "0.25": "\"സുമിത്രയുടെ സന്തോഷം വർദ്ധിപ്പിക്കുന്ന, ആയുധവിദ്യയിൽ നിപുണനായ വീരനായ ലക്ഷ്മണൻ, അമ്പുകളുടെ വലയം കൊണ്ട് രാക്ഷസന്മാരെ ചിതറിക്കുമോ?",
        "0.26": "\"ഭയങ്കരമായ ആയുധംകൊണ്ട് രാമൻ യുദ്ധത്തിൽ സുഹൃത്തുക്കളോടൊപ്പം രാവണനെ വധിക്കുന്നത് ഞാൻ ഉടൻ കാണുമോ?",
        "0.27": "\"സ്വർണ്ണനിറവും താമരപോലെ സുഗന്ധവുമുള്ള അവന്റെ മുഖം, വെള്ളം വറ്റുമ്പോൾ വെയിലേറ്റ് വാടുന്ന താമരപോലെ, ഞാനില്ലാത്തതിനാൽ ദുഃഖത്താൽ വാടിപ്പോകുന്നില്ലെന്ന് ഞാൻ ആശിക്കുന്നു?",
        "0.28": "\"ധർമ്മത്തിന്റെ പേരിൽ സ്വന്തം രാജ്യം ഉപേക്ഷിച്ച്, ഭയമോ ദുഃഖമോ ഇല്ലാതെ എന്നെ കാട്ടിലേക്ക് കാൽനടയായി നയിച്ചവൻ, ഹൃദയത്തിൽ ധൈര്യം സൂക്ഷിക്കുന്നുണ്ടോ?",
        "0.29": "\"അമ്മയോ അച്ഛനോ മറ്റാരെങ്കിലുമോ അവന് എന്നെക്കാൾ പ്രിയപ്പെട്ടവരല്ല; അവന്റെ സ്നേഹത്തിൽ എനിക്കൊപ്പമുള്ളവരുമില്ല. ദൂതനേ, പ്രിയതമന്റെ വാർത്ത കേൾക്കുന്നിടത്തോളം കാലം മാത്രം ജീവിക്കാനാണ് എന്റെ ആഗ്രഹം.\"",
        "0.30": "ആ വാനരശ്രേഷ്ഠനോട് അർത്ഥഗർഭവും മധുരമായ ആശയമുള്ളതുമായ ഈ വാക്കുകൾ പറഞ്ഞശേഷം, രാമനെക്കുറിച്ചുള്ള അവന്റെ മനോഹരമായ വാക്കുകൾ വീണ്ടും കേൾക്കാൻ ആഗ്രഹിച്ച് മനോഹരിയായ രാജ്ഞി മൗനം പാലിച്ചു.",
        "0.31": "സീതയുടെ വാക്കുകൾ കേട്ട ഭയങ്കര പരാക്രമിയായ വായുപുത്രൻ, കൈകൂപ്പി തലയിൽവെച്ച് ഈ മറുപടി പറഞ്ഞു:",
        "0.32": "\"താമരക്കണ്ണനായ രാമന് നീ ഇവിടെയുണ്ടെന്ന് അറിയില്ല; അതുകൊണ്ടാണ് ഇന്ദ്രൻ ശചിയെ തിരിച്ചുപിടിച്ചതുപോലെ അവൻ നിന്നെ വേഗം തിരിച്ചുകൊണ്ടുപോകാത്തത്.",
        "0.33": "\"എന്റെ വാക്കുകൾ കേട്ട ഉടൻ രാഘവൻ, വാനരരും കരടികളുമടങ്ങിയ വലിയ സൈന്യവുമായി വേഗത്തിൽ വരും.",
        "0.34": "\"ഇളകാത്ത സമുദ്രത്തെ അമ്പുകളുടെ പ്രവാഹംകൊണ്ട് തടഞ്ഞ്, കാകുത്സ്ഥൻ ലങ്കാനഗരത്തെ രാക്ഷസന്മാരില്ലാത്തതാക്കും.",
        "0.35": "\"മരണംതന്നെയോ ദേവന്മാരോ മഹാന്മാരായ അസുരന്മാരോ രാമന്റെ വഴിയിൽ നിന്നാലും, അവനെയും അവൻ വധിക്കും.",
        "0.36": "\"കുലീനയായ സ്ത്രീയേ, നിന്നെ കാണാത്തതിൽനിന്നുള്ള ദുഃഖം നിറഞ്ഞ രാമന് സിംഹം ആക്രമിച്ച ആനയെപ്പോലെ സമാധാനമില്ല.",
        "0.37": "\"രാജ്ഞീ, മന്ദരപർവതത്തിലും വേരുകളിലും കായ്കനികളിലും, മലയപർവതത്തിലും വിന്ധ്യനിലും, മേരുവിലും ദർദുരത്തിലും ഞാൻ നിന്നോട് സത്യം ചെയ്യുന്നു.",
        "0.38": "\"നീ രാമന്റെ മുഖം കാണും; മനോഹരമായ കണ്ണുകളും ബിംബഫലംപോലെ ചുവന്ന ചുണ്ടുകളും സുന്ദരമായ കമ്മലുകളുമുള്ള ആ മുഖം, ഉദിച്ചുയർന്ന പൂർണ്ണചന്ദ്രനെപ്പോലെ.",
        "0.39": "\"വൈദേഹീ, ഉടൻ നീ പ്രസ്രവണപർവതത്തിൽ രാമനെ കാണും; ആനകളുടെ രാജാവിന്റെ പുറത്ത് ഇന്ദ്രനെപ്പോലെ ഇരിക്കുന്ന അവനെ.",
        "0.40": "\"രാഘവൻ മാംസം കഴിക്കുന്നില്ല, തേനും എടുക്കുന്നില്ല; ദിവസവും ദിവസത്തിന്റെ അഞ്ചിലൊന്ന് ഭാഗത്ത് ക്രമപ്രകാരം തയ്യാറാക്കിയ കാട്ടുഭക്ഷണം മാത്രം കഴിക്കുന്നു.",
        "0.41": "\"മനസ്സ് മുഴുവൻ നിന്നിലേക്ക് പോയ രാഘവൻ, ശരീരത്തിൽനിന്ന് ഈച്ചകളെയോ കൊതുകുകളെയോ പ്രാണികളെയോ ഇഴജന്തുക്കളെയോ ഓടിക്കുന്നതുപോലുമില്ല.",
        "0.42": "\"രാമൻ എപ്പോഴും ചിന്താമഗ്നനാണ്; എപ്പോഴും ദുഃഖത്തിലാണ്; സ്നേഹത്താൽ നിറഞ്ഞ്, മറ്റൊന്നും ചിന്തിക്കുന്നില്ല.",
        "0.43": "\"രാമൻ എപ്പോഴും ഉറക്കമില്ലാത്തവനാണ്; ആ പുരുഷശ്രേഷ്ഠൻ ഉറങ്ങിയാൽത്തന്നെ, 'സീത' എന്ന മധുരവാക്ക് ഉച്ചരിച്ചുകൊണ്ട് ഉണരുന്നു.",
        "0.44": "\"സ്ത്രീയുടെ ഹൃദയത്തെ ആനന്ദിപ്പിക്കുന്ന ഒരു പഴമോ പൂവോ മറ്റെന്തെങ്കിലുമോ കണ്ടാൽ, 'ഹാ, പ്രിയതമേ!' എന്ന് ആവർത്തിച്ച് നെടുവീർപ്പിട്ട് നിന്നോട് സംസാരിക്കുന്നു.",
        "0.45": "\"രാജ്ഞീ, മഹാത്മാവായ ആ രാജകുമാരൻ നിരന്തരം ദുഃഖിച്ച്, 'സീതേ!' എന്ന് നിന്നെ വിളിച്ചുകൊണ്ട്, വ്രതത്തിൽ ഉറച്ചുനിന്ന്, നിന്നെ തിരിച്ചുപിടിക്കാൻ മാത്രം പരിശ്രമിക്കുന്നു.\"",
        "0.46": "രാമന്റെ സ്തുതിയാൽ ദുഃഖം അകന്നുവെങ്കിലും, രാമന്റെ ദുഃഖം പങ്കിട്ടുകൊണ്ട്, ചന്ദ്രനിൽ ഇപ്പോഴും മേഘത്തിന്റെ അംശമുള്ള ശരത്കാലരാത്രിപോലെയായി വിദേഹരാജപുത്രി.",
        "0.47": "ഇങ്ങനെ ആദികാവ്യമായ, ശ്രീമദ് രാമായണത്തിലെ വാല്മീകി രചിച്ച സുന്ദരകാണ്ഡത്തിലെ മുപ്പത്താറാം സർഗ്ഗം സമാപിച്ചു."
      },
      "summary": "ഹനുമാൻ സീതയ്ക്ക് രാമന്റെ മുദ്രമോതിരം നൽകുന്നു; രാമനെ നേരിൽ കണ്ടതുപോലെ അവൾ സന്തോഷിക്കുന്നു. രാമന്റെ വിവരങ്ങളും, തന്നെ രക്ഷിക്കാൻ അവൻ എപ്പോൾ വരുമെന്നും അവൾ ആകുലതയോടെ ചോദിക്കുന്നു."
    },
    "sundarakanda-37": {
      "verses": {
        "0.0": "ആ വാക്കുകൾ കേട്ട്, പൂർണ്ണചന്ദ്രസമാനമായ മുഖമുള്ള സീത, ധർമ്മത്തിനും വിവേകത്തിനും യോജിച്ച ഈ വാക്കുകൾ ഹനുമാനോട് പറഞ്ഞു:",
        "0.1": "\"വാനരാ, വിഷം കലർന്ന അമൃതാണ് നീ പറഞ്ഞത്: രാമൻ മറ്റൊന്നും ചിന്തിക്കുന്നില്ലെന്നും അവൻ ദുഃഖത്താൽ വെന്തുരുകുകയാണെന്നും.",
        "0.2": "\"വലിയ സമ്പത്തിലായാലും ഭയങ്കരമായ ആപത്തിലായാലും, വിധി ഒരു മനുഷ്യനെ കയറിൽ കെട്ടിയതുപോലെ വലിച്ചുകൊണ്ടുപോകുന്നു.",
        "0.3": "\"വാനരശ്രേഷ്ഠാ, വിധിയെ ജീവികൾക്ക് തടുക്കാനാവില്ല; സൗമിത്രിയും രാമനും ഞാനും ദുരിതങ്ങളാൽ എങ്ങനെ പകച്ചുപോയെന്ന് നോക്കൂ.",
        "0.4": "\"തോണി തകർന്ന ശേഷം കടലിൽ തളർന്നു നീന്തുന്നവനെപ്പോലെ, ഈ ദുഃഖസമുദ്രത്തിന്റെ അക്കരെ രാഘവൻ എങ്ങനെ എത്തും?",
        "0.5": "\"എന്റെ ഭർത്താവ് രാക്ഷസന്മാരെ വധിച്ച്, രാവണനെ നശിപ്പിച്ച്, ലങ്ക ശൂന്യമാക്കിയശേഷം എന്നെ എപ്പോൾ കാണും?",
        "0.6": "\"അവനോട് വേഗം വരാൻ പറയൂ; ഈ വർഷത്തെ കാലാവധി തീരുന്നതുവരെ മാത്രമേ എന്റെ ജീവൻ നിലനിൽക്കൂ.",
        "0.7": "\"ഇത് പത്താം മാസമാണ്; ക്രൂരനായ രാവണൻ എനിക്കായി നിശ്ചയിച്ച കാലാവധിയിൽ, വാനരാ, രണ്ട് മാസം ശേഷിക്കുന്നു.",
        "0.8": "\"അദ്ദേഹത്തിന്റെ സഹോദരൻ വിഭീഷണൻ എന്നെ തിരികെ നൽകാൻ ആവർത്തിച്ച് അപേക്ഷിച്ചു; പക്ഷേ അവൻ അതിന് മനസ്സുവെക്കുന്നില്ല.",
        "0.9": "\"എന്നെ തിരികെ നൽകുന്നത് രാവണന് ഇഷ്ടമല്ല; കാലന്റെ പിടിയിലായതിനാൽ യുദ്ധത്തിൽ മരണം രാവണനെ വേട്ടയാടുകയാണ്.",
        "0.10": "\"വാനരാ, വിഭീഷണന്റെ മൂത്ത മകളായ കാല എന്ന അവൾതന്നെ, അമ്മയുടെ നിർദ്ദേശപ്രകാരം ഇത് എന്നോട് പറഞ്ഞു.",
        "0.11": "\"രാക്ഷസരിൽ ജ്ഞാനിയും പണ്ഡിതനുമായ അവിന്ധ്യൻ എന്ന പ്രധാനി, ഉറച്ച മനസ്സും നല്ല ഗുണങ്ങളുമുള്ള വൃദ്ധൻ, രാവണന്റെ വലിയ ബഹുമാനം നേടിയവൻ,",
        "0.12": "\"രാക്ഷസന്മാരുടെമേൽ രാമനിൽനിന്നുള്ള നാശം വരുന്നുവെന്ന് മുന്നറിയിപ്പ് നൽകി; പക്ഷേ ആ ദുഷ്ടൻ അവന്റെ ഹിതകരമായ വാക്കുകൾ കേൾക്കുന്നില്ല.",
        "0.13": "\"വാനരശ്രേഷ്ഠാ, എന്റെ മനസ്സ് ശുദ്ധമായതുകൊണ്ടും അദ്ദേഹത്തിന് ഏറെ ഗുണങ്ങളുള്ളതുകൊണ്ടും, എന്റെ ഭർത്താവ് ഉടൻ എന്നെ തിരിച്ചുപിടിക്കുമെന്ന് ഞാൻ ആശിക്കുന്നു.",
        "0.14": "\"ഉത്സാഹം, പുരുഷത്വം, ബലം, കാരുണ്യം, കൃതജ്ഞത, വീര്യം, ഗാംഭീര്യം ഇവയെല്ലാം രാഘവനിലുണ്ട്, വാനരാ.",
        "0.15": "\"ജനസ്ഥാനത്തിൽ സഹോദരന്റെ സഹായമില്ലാതെ പതിനാലായിരം രാക്ഷസന്മാരെ കൊന്നവൻ, അവന്റെ മുന്നിൽ ഏത് ശത്രുവാണ് വിറയ്ക്കാത്തത്?",
        "0.16": "\"ദുരിതങ്ങൾക്ക് ആ പുരുഷശ്രേഷ്ഠനെ ഇളക്കാനാവില്ല; ഇന്ദ്രന്റെ ശക്തി പുലോമജ അറിയുന്നതുപോലെ അവന്റെ ശക്തി ഞാനറിയുന്നു.",
        "0.17": "\"വാനരാ, അമ്പുകളുടെ രശ്മികളുള്ള ധീരനായ സൂര്യനാണ് രാമൻ; അവൻ രാക്ഷസശത്രുവായ ജലത്തെ വറ്റിക്കും.\"",
        "0.18": "രാമനെക്കുറിച്ചുള്ള ദുഃഖത്താൽ ക്ഷീണിച്ച്, കണ്ണീർ നിറഞ്ഞ മുഖത്തോടെ അവൾ ഇങ്ങനെ പറഞ്ഞപ്പോൾ, വാനരനായ ഹനുമാൻ അവളോട് പറഞ്ഞു:",
        "0.19": "\"എന്റെ വാക്കുകൾ കേട്ട ഉടൻ രാഘവൻ, വാനരരും കരടികളും നിറഞ്ഞ വലിയ സൈന്യവുമായി വേഗത്തിൽ വരും.",
        "0.20": "\"അല്ലെങ്കിൽ, ഈ ദിവസംതന്നെ, ഈ ദുഃഖത്തിൽനിന്നും രാക്ഷസന്മാരുള്ള ഈ സ്ഥലത്തുനിന്നും ഞാൻ നിന്നെ മോചിപ്പിക്കാം. കുറ്റമറ്റവളേ, എന്റെ പുറത്തേറുക.",
        "0.21": "\"നിന്നെ പുറത്തേറ്റി ഞാൻ സമുദ്രം കടക്കും; രാവണനോടൊപ്പം ലങ്കയെപ്പോലും വഹിക്കാനുള്ള ശക്തി എനിക്കുണ്ട്.",
        "0.22": "\"മൈഥിലീ, ഇന്ന് ഞാൻ നിന്നെ പ്രസ്രവണപർവതത്തിൽ രാഘവന്റെ അടുത്തെത്തിക്കും; അഗ്നി യാഗത്തിലൊഴിക്കുന്ന ഹവിസ്സ് ഇന്ദ്രന് എത്തിക്കുന്നതുപോലെ.",
        "0.23": "\"വൈദേഹീ, ഈ ദിവസംതന്നെ ലക്ഷ്മണനോടൊപ്പമുള്ള രാഘവനെ നീ കാണും; ദൈത്യന്മാരെ വധിക്കാൻ ഉറച്ച വിഷ്ണുവിനെപ്പോലെ.",
        "0.24": "\"നിന്നെ കാണാനുള്ള ആഗ്രഹത്താൽ നിറഞ്ഞ, തപോവനത്തിലുള്ള ആ മഹാൻ, പർവതരാജാവിന്റെ ശിരസ്സിൽ ഇന്ദ്രനെപ്പോലെ ഇരിക്കുന്നവൻ.",
        "0.25": "\"രാജ്ഞീ, എന്റെ പുറത്തേറുക; മനോഹരീ, സംശയിക്കേണ്ട. രോഹിണി ചന്ദ്രനെ ചേരുന്നതുപോലെ നീ രാമനോട് ഒന്നുചേരുക.",
        "0.26": "\"'രോഹിണിയെപ്പോലെ നീ ചന്ദ്രനോട് ചേരും' എന്ന് പ്രഖ്യാപിക്കുന്നതുപോലെ, എന്റെ പുറത്തേറി ആകാശത്തിലൂടെ മഹാസമുദ്രം കടക്കുക.",
        "0.27": "\"സ്ത്രീയേ, ഇവിടെനിന്ന് നിന്നെ വഹിച്ചുകൊണ്ട് ഞാൻ പുറപ്പെടുമ്പോൾ, ലങ്കയിലെ ഒരു നിവാസിക്കും എന്റെ വഴിയെ പിന്തുടരാനാവില്ല.",
        "0.28": "\"ഞാൻ ഇവിടെ വന്നതുപോലെതന്നെ, നിന്നെ ആകാശത്തേക്ക് ഉയർത്തി ഞാൻ തീർച്ചയായും പോകും; നോക്കൂ, വൈദേഹീ.\"",
        "0.29": "വാനരശ്രേഷ്ഠന്റെ ഈ അത്ഭുതവാക്കുകൾ കേട്ട മൈഥിലി, ഓരോ അവയവത്തിലും സന്തോഷവും അത്ഭുതവും നിറഞ്ഞ്, ഹനുമാനോട് പറഞ്ഞു:",
        "0.30": "\"ഹനുമാൻ, ഇത്രയും ദൂരം എന്നെ എങ്ങനെ വഹിക്കാനാണ് നീ ഉദ്ദേശിക്കുന്നത്? വാനരസംഘങ്ങളുടെ നേതാവേ, ഇത് നിന്റെ വാനരസ്വഭാവം മാത്രമാണെന്ന് ഞാൻ കരുതുന്നു.",
        "0.31": "\"ഇത്ര ചെറിയ ശരീരംകൊണ്ട് എന്നെ ഇവിടെനിന്ന് മനുഷ്യരാജാവായ എന്റെ ഭർത്താവിന്റെ അടുത്തേക്ക് കൊണ്ടുപോകാൻ നീ ആഗ്രഹിക്കുന്നത് എങ്ങനെ, വാനരശ്രേഷ്ഠാ?\"",
        "0.32": "സീതയുടെ വാക്കുകൾ കേട്ട തേജസ്വിയായ വായുപുത്രൻ ഹനുമാൻ, അത് തന്നോടുള്ള പുതിയ അവഹേളനമായി കരുതി.",
        "0.33": "\"കറുത്ത കണ്ണുകളുള്ള സ്ത്രീക്ക് എന്റെ ബലവും ശക്തിയും അറിയില്ല. അതിനാൽ ഇഷ്ടാനുസരണം ഞാൻ സ്വീകരിക്കാവുന്ന രൂപം വൈദേഹി കാണട്ടെ.\"",
        "0.34": "ഇങ്ങനെ ചിന്തിച്ച്, വാനരശ്രേഷ്ഠനും ശത്രുക്കളെ നശിപ്പിക്കുന്നവനുമായ ഹനുമാൻ സീതയ്ക്ക് തന്റെ യഥാർത്ഥ രൂപം കാണിച്ചുകൊടുത്തു.",
        "0.35": "ആ ബുദ്ധിമാനായ വാനരശ്രേഷ്ഠൻ മരത്തിൽനിന്ന് താഴേക്ക് ചാടി; സീതയുടെ വിശ്വാസം നേടാനായി പിന്നെ വളരാൻ തുടങ്ങി.",
        "0.36": "മേരുവിനെപ്പോലെയോ മന്ദരത്തെപ്പോലെയോ, ജ്വലിക്കുന്ന തീപോലെ തിളങ്ങിക്കൊണ്ട്, ആ വാനരശ്രേഷ്ഠൻ സീതയുടെ മുന്നിൽ നിന്നു.",
        "0.37": "പർവതംപോലെ ചുവന്ന മുഖവും ഭയങ്കര രൂപവും, ഇടിമിന്നൽപോലുള്ള പല്ലുകളും നഖങ്ങളുമുള്ള ആ മഹാവാനരൻ വൈദേഹിയോട് ഇങ്ങനെ പറഞ്ഞു:",
        "0.38": "\"പർവതങ്ങളും വനങ്ങളും, ഗോപുരങ്ങളും കോട്ടമതിലുകളും പ്രവേശനകവാടങ്ങളുമുള്ള ഈ ലങ്കയെ, അതിന്റെ നാഥനോടൊപ്പം എടുത്തുകൊണ്ടുപോകാനുള്ള ശക്തി എനിക്കുണ്ട്.",
        "0.39": "\"അതുകൊണ്ട് തീരുമാനമെടുക്കൂ; ഇനി സംശയം മതി, രാജ്ഞീ. വൈദേഹീ, രാഘവനെയും ലക്ഷ്മണനെയും ദുഃഖത്തിൽനിന്ന് മോചിപ്പിക്കൂ.\"",
        "0.40": "പർവതംപോലെയുള്ള അവനെ കണ്ട ജനകപുത്രി, താമരദളംപോലെ വിശാലമായ കണ്ണുകളോടെ, വായുദേവന്റെ പുത്രനോട് പറഞ്ഞു:",
        "0.41": "\"മഹാവാനരാ, നിന്റെ ബലവും ശക്തിയും എനിക്കറിയാം; കാറ്റിന്റേതുപോലുള്ള വേഗവും അഗ്നിയുടേതുപോലുള്ള അത്ഭുതകരമായ തേജസ്സും ഞാൻ അറിയുന്നു.",
        "0.42": "\"അളക്കാനാവാത്ത ഈ സമുദ്രത്തിനപ്പുറമുള്ള ഈ നാട്ടിൽ, വാനരസംഘനേതാവേ, സാധാരണ ജീവിക്ക് എങ്ങനെ വരാനാകും?",
        "0.43": "\"യാത്ര ചെയ്യാനും എന്നെയും വഹിക്കാനുമുള്ള നിന്റെ ശക്തി ഞാനറിയുന്നു. എങ്കിലും കാര്യങ്ങൾ വേഗത്തിലല്ല, ശ്രദ്ധയോടെ തൂക്കിനോക്കണം, അങ്ങനെയാണ് ലക്ഷ്യം വിജയിക്കുക.",
        "0.44": "\"പക്ഷേ, വാനരശ്രേഷ്ഠാ, നിന്നോടൊപ്പം പോകുന്നത് എനിക്ക് ഉചിതമല്ല; കാറ്റിനോട് മത്സരിക്കുന്ന നിന്റെ വേഗം എന്നെ ബോധരഹിതയാക്കിയേക്കാം.",
        "0.45": "\"സമുദ്രത്തിനു മീതെ ആകാശത്ത് ഉയർന്നുനിൽക്കുമ്പോൾ, നീ വലിയ വേഗത്തിൽ പോകുമ്പോൾ നിന്റെ പുറത്തുനിന്ന് ഞാൻ വീണുപോയേക്കാം.",
        "0.46": "\"തിമിംഗലങ്ങളും മുതലകളും മത്സ്യങ്ങളും നിറഞ്ഞ സമുദ്രത്തിൽ വീണാൽ, നിസ്സഹായയായി അതിലെ ജീവികൾക്ക് ഞാൻ നല്ലൊരു ഭക്ഷണമായിത്തീരും.",
        "0.47": "\"ശത്രുക്കളെ നശിപ്പിക്കുന്നവനേ, സംരക്ഷിക്കാൻ ഒരു സ്ത്രീയുള്ളപ്പോൾ നിന്നെ അപകടത്തിൽ ആക്കും എന്നതിനാൽ ഞാൻ നിന്നോടൊപ്പം പോകാനും കഴിയില്ല.",
        "0.48": "\"എന്നെ കൊണ്ടുപോകുന്നത് കണ്ടാൽ, ദുഷ്ടനായ രാവണന്റെ കല്പനപ്രകാരം ഭയങ്കര പരാക്രമികളായ രാക്ഷസന്മാർ നമ്മെ പിന്തുടരും.",
        "0.49": "\"കുന്തവും ഗദയുമേന്തിയ ആ വീരന്മാരാൽ ചുറ്റപ്പെട്ട്, വീരാ, ഞാൻ ഭാരമായി നിന്റെ മേൽ ഉണ്ടാകുമ്പോൾ നീ അപകടത്തിലാകും.",
        "0.50": "\"ആകാശത്ത് ആയുധധാരികളായ ഒരുപാട് രാക്ഷസന്മാർ ഉണ്ടാകും; നീയാകട്ടെ ആയുധമില്ലാത്തവനും. എന്നെ സംരക്ഷിച്ചുകൊണ്ട് നീ എങ്ങനെ പൊരുതും?",
        "0.51": "\"ക്രൂരകർമ്മികളായ ആ രാക്ഷസന്മാരോട് നീ യുദ്ധം ചെയ്യുമ്പോൾ, വാനരശ്രേഷ്ഠാ, ഭയംകൊണ്ട് ഞാൻ നിന്റെ പുറത്തുനിന്ന് വീണുപോയേക്കാം.",
        "0.52": "\"അല്ലെങ്കിൽ ഭയങ്കരരും വലിയവരും ശക്തരുമായ ആ രാക്ഷസന്മാർ യുദ്ധത്തിൽ ഏതെങ്കിലും വിധത്തിൽ നിന്നെ തോൽപ്പിച്ചേക്കാം, വാനരശ്രേഷ്ഠാ.",
        "0.53": "\"അല്ലെങ്കിൽ യുദ്ധം ചെയ്യുമ്പോൾ നീ തിരിയുമ്പോൾ ഞാൻ വീണുപോയേക്കാം; വീഴുമ്പോൾ ദുഷ്ടരായ രാക്ഷസന്മാർ എന്നെ പിടിച്ചു കൊണ്ടുപോകും.",
        "0.54": "\"അല്ലെങ്കിൽ അവർ നിന്റെ കൈകളിൽനിന്ന് എന്നെ പിടിച്ചെടുക്കുകയോ കൊല്ലുകയോ ചെയ്തേക്കാം; യുദ്ധത്തിൽ ജയവും തോൽവിയും അനിശ്ചിതമാണല്ലോ.",
        "0.55": "\"അല്ലെങ്കിൽ രാക്ഷസന്മാരുടെ ഭീഷണിയാൽ ഭയന്ന് ഞാൻ മരിച്ചേക്കാം; അപ്പോൾ വാനരശ്രേഷ്ഠാ, നിന്റെ പ്രയത്നം പൂർണ്ണമായും വ്യർത്ഥമാകും.",
        "0.56": "\"നിനക്കും എല്ലാ രാക്ഷസന്മാരെയും കൊല്ലാനുള്ള ശക്തിയുണ്ടെന്നത് ശരി; പക്ഷേ രാക്ഷസന്മാരെ നീ കൊന്നാൽ, രാഘവന്റെ കീർത്തി കുറയും.",
        "0.57": "\"അല്ലെങ്കിൽ, വാനരന്മാർക്കോ രാഘവനോ ഒരിക്കലും കണ്ടെത്താനാകാത്ത ഏതെങ്കിലും രഹസ്യസ്ഥലത്ത് രാക്ഷസന്മാർ എന്നെ ഒളിപ്പിച്ചേക്കാം.",
        "0.58": "\"അപ്പോൾ എനിക്കുവേണ്ടിയുള്ള നിന്റെ ഈ ദൗത്യം വ്യർത്ഥമാകും. എന്നാൽ രാമൻ നിന്നോടൊപ്പം ഇവിടെ വരുന്നതിൽ വലിയ പുണ്യമുണ്ട്.",
        "0.59": "\"അതിരില്ലാത്ത ശക്തിയുള്ള രാഘവന്റെയും സഹോദരന്മാരുടെയും, കരുത്തുള്ള ബാഹുക്കളുള്ളവനേ, നിന്റെ രാജകുടുംബത്തിന്റെയും ജീവൻ എന്നിലാണ് ആശ്രയിച്ചിരിക്കുന്നത്.",
        "0.60": "\"എന്നെക്കുറിച്ചുള്ള നിരാശയാൽ, ദുഃഖവും വേദനയും കൊണ്ട് ക്ഷീണിച്ച ആ രണ്ടുപേരും കരടികളും വാനരന്മാരുമെല്ലാമായി ജീവൻ ഉപേക്ഷിക്കും.",
        "0.61": "\"അതിനുപുറമേ, ഭർത്താവിനോടുള്ള എന്റെ ഭക്തിയെ മാനിച്ച്, വാനരശ്രേഷ്ഠാ, രാമനല്ലാത്ത ആരുടെയും ശരീരം ഞാൻ മനഃപൂർവ്വം സ്പർശിക്കില്ല.",
        "0.62": "\"രാവണന്റെ ശരീരവുമായി ബലമായി ഞാൻ സമ്പർക്കത്തിൽ വന്നത്, അസഹായയും സംരക്ഷകനില്ലാത്തവളും നിസ്സഹായയുമായ ഞാൻ എന്തുചെയ്യാനാണ്?",
        "0.63": "\"പത്ത് തലയുള്ള രാവണനെ ഇവിടെ രാക്ഷസന്മാരോടൊപ്പം വധിച്ച് രാമൻ ഇവിടെനിന്ന് എന്നെ കൊണ്ടുപോകുന്നതാകും അവന് യോജിച്ചത്.",
        "0.64": "\"യുദ്ധത്തിൽ ശത്രുക്കളെ തകർക്കുന്ന ആ മഹാത്മാവിന്റെ പരാക്രമങ്ങൾ ഞാൻ കേട്ടിട്ടുണ്ട്, കണ്ടിട്ടുമുണ്ട്; യുദ്ധത്തിൽ രാമന് തുല്യരായി ദേവന്മാരോ ഗന്ധർവന്മാരോ നാഗന്മാരോ രാക്ഷസന്മാരോ ഇല്ല.",
        "0.65": "\"യുദ്ധത്തിൽ ഇന്ദ്രനു തുല്യവീര്യനായ, അത്ഭുതവില്ലുള്ള ആ മഹാനായ രാഘവനെ ലക്ഷ്മണനോടൊപ്പം കണ്ടാൽ, കാറ്റിനാൽ ഊതപ്പെട്ട തീപോലെ ജ്വലിക്കുന്ന അവനെ ആർക്ക് നേരിടാനാകും?",
        "0.66": "\"വാനരശ്രേഷ്ഠാ, യുദ്ധത്തിൽ, ദിക്കുകളിലെ മദിച്ച ആനപോലെ ഉറച്ചുനിൽക്കുന്ന, ശത്രുക്കളെ നശിപ്പിക്കുന്ന രാഘവനെയും ലക്ഷ്മണനെയും, യുഗാന്ത്യസൂര്യനെപ്പോലെ അമ്പുകൾ ജ്വലിപ്പിക്കുന്നവരെയും ആർക്ക് നേരിടാനാകും?",
        "0.67": "\"അതുകൊണ്ട്, വാനരശ്രേഷ്ഠാ, എന്റെ പ്രിയനായ രാമനെയും ലക്ഷ്മണനെയും സേനാനായകന്മാരെയും വേഗം ഇവിടെ കൊണ്ടുവരൂ; വീരനായ വാനരാ, രാമനെക്കുറിച്ചുള്ള ദുഃഖത്താൽ ദീർഘകാലം ക്ഷീണിച്ച എന്നെ സന്തോഷിപ്പിക്കൂ.\"",
        "0.68": "ഇങ്ങനെ ആദികാവ്യമായ, ശ്രീമദ് രാമായണത്തിലെ വാല്മീകി രചിച്ച സുന്ദരകാണ്ഡത്തിലെ മുപ്പത്തേഴാം സർഗ്ഗം സമാപിച്ചു."
      },
      "summary": "സീതയെ ഉടൻ രാമന്റെ അടുത്തേക്ക് പുറത്തേറ്റി കൊണ്ടുപോകാമെന്ന് ഹനുമാൻ വാഗ്ദാനം ചെയ്യുന്നു; അവൾ അദ്ദേഹത്തിന്റെ ശക്തിയിൽ സംശയിച്ചപ്പോൾ തന്റെ വിശാലരൂപം കാണിക്കുന്നു. മറ്റൊരു പുരുഷനെ മനഃപൂർവം സ്പർശിക്കില്ലെന്നും രാമൻതന്നെ തന്നെ തിരിച്ചുപിടിക്കണമെന്നും പറഞ്ഞ് സീത അത് നിരസിക്കുന്നു."
    },
    "sundarakanda-38": {
      "verses": {
        "0.0": "ആ വാക്കുകളിൽ സന്തോഷിച്ച്, സംസാരത്തിൽ സമർത്ഥനായ ആ വാനരശ്രേഷ്ഠൻ അവ കേട്ടശേഷം സീതയോട് പറഞ്ഞു:",
        "0.1": "\"മനോഹരമുഖീ, നീ പറഞ്ഞത് ഏറ്റവും ഉചിതമാണ്; സ്ത്രീസ്വഭാവത്തിനും പതിവ്രതകളായ ഭാര്യമാരുടെ വിനയത്തിനും യോജിച്ചതാണത്.",
        "0.2": "\"നൂറു യോജന വീതിയുള്ള സമുദ്രം എന്റെ പുറത്തേറി കടക്കാൻ നിനക്ക് കഴിയില്ല; നീ ഒരു സ്ത്രീയാണല്ലോ.",
        "0.3": "\"രണ്ടാമത്തെ കാരണമായി വിനീതയായ ജാനകി പറഞ്ഞത് — രാമനല്ലാതെ മറ്റാരെയും സ്പർശിക്കരുതെന്ന് —",
        "0.4": "\"അത് നിനക്ക് യോജിച്ചതാണ്, രാജ്ഞീ, ആ മഹാത്മാവിന്റെ ഭാര്യയേ; നീയല്ലാതെ മറ്റാരാണ് ഇങ്ങനെ സംസാരിക്കുക?",
        "0.5": "\"നീ ചെയ്തതെല്ലാം, രാജ്ഞീ, എന്റെ മുന്നിൽ പറഞ്ഞതെല്ലാം, ഒന്നും ഒഴിവാക്കാതെ കാകുത്സ്ഥൻ കേൾക്കും.",
        "0.6": "\"പല കാരണങ്ങളാൽ, രാജ്ഞീ, രാമനെ സന്തോഷിപ്പിക്കാൻ ആഗ്രഹിച്ചാണ്, സ്നേഹത്താൽ നനഞ്ഞ ഹൃദയത്തോടെ ഞാൻ ഇത് നിർദ്ദേശിച്ചത്.",
        "0.7": "\"ലങ്കയിൽ പ്രവേശിക്കാൻ പ്രയാസമായതുകൊണ്ടും, മഹാസമുദ്രം കടക്കാൻ പ്രയാസമായതുകൊണ്ടും, എന്റെ തന്നെ കഴിവുകൊണ്ടും ഞാൻ ഇത് നിർദ്ദേശിച്ചു.",
        "0.8": "\"ഈ ദിവസംതന്നെ രഘുവംശജരുടെ സന്തോഷവുമായി നിന്നെ ഒന്നിപ്പിക്കാൻ ഞാൻ ആഗ്രഹിച്ചു; ആഴമേറിയ സ്നേഹത്താലും ഭക്തിയാലും ഞാൻ പറഞ്ഞതാണ്, മറ്റൊന്നുമല്ല.",
        "0.9": "\"എന്നോടൊപ്പം പോകാൻ നിനക്ക് ഇഷ്ടമില്ലെങ്കിൽ, കുറ്റമറ്റവളേ, രാഘവന് തിരിച്ചറിയാവുന്ന ഒരു അടയാളം തരൂ.\"",
        "0.10": "ഹനുമാൻ ഇങ്ങനെ പറഞ്ഞപ്പോൾ, ദേവകന്യകയെപ്പോലെ സീത, കണ്ണീരിൽ മുങ്ങിയ വാക്കുകളാൽ മൃദുവായി പറഞ്ഞു:",
        "0.11": "\"എന്റെ പ്രിയതമനോട് ഈ ഉത്തമമായ അടയാളം പറയൂ: ചിത്രകൂടപർവതത്തിന്റെ അടിയിൽ, അതിന്റെ വടക്കുകിഴക്കേ ഭാഗത്ത്,",
        "0.12": "\"വേരുകളും കായ്കനികളും വെള്ളവും സമൃദ്ധമായ ഒരു തപോവനത്തിൽ ഞാൻ താമസിക്കുമ്പോൾ, സിദ്ധന്മാർ സഞ്ചരിക്കുന്ന ആ പ്രദേശത്ത്, മന്ദാകിനിയിൽനിന്ന് അധികം അകലെയല്ലാതെ,",
        "0.13": "\"അനേകം പൂക്കളാൽ സുഗന്ധമുള്ള അതിന്റെ തോട്ടങ്ങളിൽ കളിച്ചതിനുശേഷം, വെള്ളത്തിൽ നനഞ്ഞ നീ എന്റെ മടിയിൽ വന്നിരുന്നു.",
        "0.14": "\"അപ്പോൾ മാംസത്തിനായി ആർത്തിയുള്ള ഒരു കാക്ക എന്നെ കൊത്തിക്കൊണ്ടിരുന്നു; ഞാൻ ഒരു മണ്ണുകട്ട എടുത്ത് കാക്കയെ ഓടിക്കാൻ ശ്രമിച്ചു.",
        "0.15": "\"ആ കാക്ക എന്നെ മുറിവേൽപ്പിച്ച് അവിടെത്തന്നെ ഒളിച്ചു; ഭക്ഷണം ആഗ്രഹിക്കുന്ന ബലികൾ ഭക്ഷിക്കുന്നവൻ മാംസം വിട്ടുപോയില്ല.",
        "0.16": "\"പക്ഷിയോട് കോപിച്ച് ഞാൻ അരഞ്ഞാണം വലിച്ചുകയറ്റുമ്പോൾ, വസ്ത്രം ഊർന്നുപോകുന്നത് നീ കണ്ടു.",
        "0.17": "\"നീ എന്നെ നോക്കി ചിരിച്ചു; ഞാൻ കോപിച്ചും ലജ്ജിച്ചും; ആഹാരാർത്ഥിയായ കാക്കയാൽ മുറിവേറ്റ ഞാൻ നിന്റെ അടുത്തേക്ക് വന്നു.",
        "0.18": "\"പിന്നെ ക്ഷീണിതയായ ഞാൻ, നീ ഇരുന്നപ്പോൾ നിന്റെ മടിയിൽ ഇരുന്നു; കോപിച്ചവളെപ്പോലെ തോന്നിയ എന്നെ നീ സന്തോഷത്തോടെ ആശ്വസിപ്പിച്ചു.",
        "0.19": "\"കണ്ണീർ നിറഞ്ഞ മുഖവുമായി, കണ്ണുകൾ മൃദുവായി തുടച്ചുകൊണ്ടിരുന്ന എന്നെ, കാക്ക പ്രകോപിപ്പിച്ചതിനാൽ, പ്രഭുവായ നീ കണ്ടു.",
        "0.20": "\"ക്ഷീണം കാരണം രാഘവന്റെ മടിയിൽ ഞാൻ ഏറെനേരം ഉറങ്ങി; പിന്നീട് ഭരതന്റെ ജ്യേഷ്ഠൻ എന്റെ മടിയിൽ ഉറങ്ങി.",
        "0.21": "\"പിന്നീട് ആ കാക്ക വീണ്ടും അവിടെ വന്നു; ഉറക്കമുണർന്ന് ഞാൻ രാഘവന്റെ മടിയിൽനിന്ന് എഴുന്നേറ്റപ്പോൾ, കാക്ക പെട്ടെന്ന് ചാടിവന്ന് എന്റെ മാറിനിടയിൽ കൊത്തിക്കീറി.",
        "0.22": "\"വീണ്ടും വീണ്ടും അത് പറന്നുയർന്ന് എന്നെ കഠിനമായി കീറി. അപ്പോൾ വീണ രക്തത്തുള്ളികളാൽ നനഞ്ഞ് രാമൻ ഉണർന്നു.",
        "0.23": "\"നെഞ്ചിൽ മുറിവേറ്റ എന്നെ കണ്ട്, വിഷസർപ്പത്തെപ്പോലെ കോപിച്ച് ചീറിക്കൊണ്ട് ആ ബലശാലി പറഞ്ഞു:",
        "0.24": "\"'ആനയുടെ തുമ്പിക്കൈപോലുള്ള തുടകളുള്ളവളേ, ആരാണ് നിന്റെ മാറിനിടയിൽ മുറിവേൽപ്പിച്ചത്? കോപിച്ച അഞ്ചുതലയുള്ള സർപ്പത്തോട് കളിക്കുന്നതാരാണ്?'",
        "0.25": "\"ചുറ്റും നോക്കിയപ്പോൾ, മൂർച്ചയുള്ള നഖങ്ങളിൽ രക്തവുമായി, എന്റെ നേരെ മുഖമായി ഇരിക്കുന്ന ആ കാക്കയെ അദ്ദേഹം കണ്ടു.",
        "0.26": "\"ആ കാക്ക പക്ഷികളിൽ ശ്രേഷ്ഠനായിരുന്നു; വാസ്തവത്തിൽ അത് ഇന്ദ്രപുത്രനായിരുന്നു; കാറ്റുപോലെ വേഗത്തിൽ അത് വേഗം ഭൂമിയിലേക്ക് താഴ്ന്നുപോയി.",
        "0.27": "\"അപ്പോൾ ജ്ഞാനികളിൽ ശ്രേഷ്ഠനായ ആ ബലശാലി, കോപത്താൽ കണ്ണുകൾ ഉരുട്ടി, ആ കാക്കയ്ക്കെതിരെ ക്രൂരമായ ഒരു തീരുമാനമെടുത്തു.",
        "0.28": "\"തന്റെ പായയിൽനിന്ന് ഒരു ദർഭപ്പുല്ലിന്റെ തണ്ടെടുത്ത് അദ്ദേഹം ബ്രഹ്മാസ്ത്രം അതിൽ ആവാഹിച്ചു; പക്ഷിക്കുനേരെ തിരിച്ചു, അത് പ്രളയാഗ്നിപോലെ ജ്വലിച്ചു.",
        "0.29": "\"ആ ജ്വലിക്കുന്ന പുല്ല് അദ്ദേഹം കാക്കയ്ക്കുനേരെ എറിഞ്ഞു; ആ പുല്ല് ആകാശത്തിലൂടെ കാക്കയെ പിന്തുടർന്നു.",
        "0.30": "\"പിന്തുടരപ്പെട്ട കാക്ക പല ദിശകളിലേക്കും പറന്നു; സംരക്ഷണം തേടി ആ ലോകമാകെ അലഞ്ഞു.",
        "0.31": "\"പിതാവിനാലും എല്ലാ മഹർഷിമാരാലും ഉപേക്ഷിക്കപ്പെട്ട് മൂന്നു ലോകവും ചുറ്റി, അത് ഒടുവിൽ ഒറ്റയ്ക്ക് അദ്ദേഹത്തിന്റെ അടുത്ത് അഭയം തേടി വന്നു.",
        "0.32": "\"അഭയം നൽകുന്ന കാകുത്സ്ഥൻ, മരണത്തിന് അർഹമായിരുന്നിട്ടും, അഭയം തേടി നിലത്തുവീണപ്പോൾ അനുകമ്പയോടെ അതിനെ സംരക്ഷിച്ചു.",
        "0.33": "\"ക്ഷീണിതനും വിളറിയവനും വീണുപോകുന്നവനുമായ അതിനോട് അദ്ദേഹം പറഞ്ഞു: 'ബ്രഹ്മാസ്ത്രം നിഷ്ഫലമാക്കാനാവില്ല; ഇനി എന്തുചെയ്യണമെന്ന് പറയൂ.'",
        "0.34": "\"അപ്പോൾ ആയുധം കാക്കയുടെ വലതു കണ്ണ് നശിപ്പിച്ചു; വലതു കണ്ണ് നൽകിയതിനാൽ അത് മരണത്തിൽനിന്ന് രക്ഷപ്പെട്ടു.",
        "0.35": "\"രാമനെയും ദശരഥമഹാരാജാവിനെയും വണങ്ങി, ആ വീരനാൽ യാത്രയയക്കപ്പെട്ട് അത് സ്വന്തം വാസസ്ഥലത്തേക്ക് തിരിച്ചുപോയി.",
        "0.36": "\"എന്റെ നിമിത്തം, ഒരു സാധാരണ കാക്കയ്ക്കുനേരെപ്പോലും നീ ബ്രഹ്മാസ്ത്രം പ്രയോഗിച്ചു; പിന്നെ, ഭൂമിപതേ, എന്നെ നിന്നിൽനിന്ന് കൊണ്ടുപോയവനെ എന്തിന് നീ സഹിക്കുന്നു?",
        "0.37": "\"പുരുഷോത്തമാ, വലിയ ഉത്സാഹത്തോടെ എന്നോട് കരുണ കാണിക്കൂ; എന്റെ നാഥാ, നീ എനിക്ക് സംരക്ഷകനായിരിക്കെ, എനിക്ക് ആരുമില്ലെന്ന് തോന്നുന്നു.",
        "0.38": "\"കരുണയാണ് ഏറ്റവും ഉന്നതമായ ധർമ്മം; അത് ഞാൻ നിന്നിൽനിന്ന് മാത്രമാണ് കേട്ടത്. നീ മഹാവീര്യമുള്ളവനും മഹാ ഉത്സാഹമുള്ളവനും മഹാബലശാലിയുമാണെന്ന് ഞാൻ അറിയുന്നു.",
        "0.39": "\"അതിരില്ലാത്തവനും, ഇളകാത്തവനും, ആഴത്തിൽ സമുദ്രംപോലെയുള്ളവനും, സമുദ്രംചുറ്റിയ ഭൂമിയുടെ നാഥനും, ഇന്ദ്രനു തുല്യനുമാണ് നീ.",
        "0.40": "\"ആയുധമറിയുന്നവരിൽ ഏറ്റവും മികച്ചവനും കരുത്തും സ്ഥൈര്യവുമുള്ളവനുമായ നീ, രാഘവാ, രാക്ഷസന്മാർക്കെതിരെ നിന്റെ ആയുധങ്ങൾ എന്തുകൊണ്ട് ഉപയോഗിക്കുന്നില്ല?\"",
        "0.41": "\"രാമന്റെ ആക്രമണം യുദ്ധത്തിൽ നാഗന്മാർക്കും ഗന്ധർവന്മാർക്കും, ദേവന്മാർക്കും മരുത്ഗണങ്ങൾക്കും നേരിടാനാവില്ല.",
        "0.42": "\"ആ മഹാൻ എന്നെക്കുറിച്ച് എന്തെങ്കിലും ചിന്തിക്കുന്നുവെങ്കിൽ, മൂർച്ചയുള്ള അമ്പുകളാൽ രാക്ഷസന്മാരെ എന്തുകൊണ്ട് നശിപ്പിക്കുന്നില്ല?",
        "0.43": "\"അല്ലെങ്കിൽ, ശത്രുക്കളെ തകർക്കുന്ന, ശക്തനായ വീരൻ ലക്ഷ്മണൻ, ജ്യേഷ്ഠന്റെ കല്പന സ്വീകരിച്ച് എന്നെ രക്ഷിക്കാത്തതെന്തുകൊണ്ട്?",
        "0.44": "\"വായുവിനും ഇന്ദ്രനും തുല്യമായ തേജസ്സുള്ള ആ രണ്ട് മനുഷ്യസിംഹങ്ങൾ, ദേവന്മാർക്കുപോലും കീഴടക്കാനാവാത്തവരാണെങ്കിൽ, അവർ എന്നെ അവഗണിക്കുന്നതെന്തുകൊണ്ട്?",
        "0.45": "\"സംശയമില്ല, എന്നിൽനിന്ന് വലിയ തെറ്റ് സംഭവിച്ചിരിക്കണം; ശത്രുക്കളെ ദഹിപ്പിക്കുന്ന ആ രണ്ടുപേർക്ക് കഴിവുണ്ടായിട്ടും എന്നെ ശ്രദ്ധിക്കുന്നില്ലല്ലോ.\"",
        "0.46": "കണ്ണീരോടെ പറഞ്ഞ വൈദേഹിയുടെ ദയനീയമായ വാക്കുകൾ കേട്ട്, തേജസ്വിയായ വാനരസംഘനേതാവ് ഹനുമാൻ പറഞ്ഞു:",
        "0.47": "\"രാജ്ഞീ, സത്യം മുൻനിർത്തി ഞാൻ നിന്നോട് സത്യം ചെയ്യുന്നു: നിന്നെക്കുറിച്ചുള്ള ദുഃഖത്താൽ രാമൻ എല്ലാത്തിൽനിന്നും മുഖം തിരിച്ചിരിക്കുന്നു; ദുഃഖത്താൽ തളർന്ന രാമനോടൊപ്പം ലക്ഷ്മണനും വേദനയിലാണ്.",
        "0.48": "\"ഏതെങ്കിലും വിധത്തിൽ നിന്നെ കണ്ടെത്തിയിരിക്കുന്നു; ഇത് ദുഃഖിക്കേണ്ട സമയമല്ല. ഒരു നിമിഷത്തിനകം നിന്റെ ദുഃഖങ്ങളുടെ അവസാനം നീ കാണും, സുന്ദരീ.",
        "0.49": "\"നിന്നെ കാണാൻ ആഗ്രഹിക്കുന്ന ആ രണ്ട് മനുഷ്യസിംഹങ്ങളായ മഹാരാജകുമാരന്മാർ, ലോകങ്ങളെ ചാരമാക്കും.",
        "0.50": "\"യുദ്ധത്തിൽ ക്രൂരനായ രാവണനെ ബന്ധുക്കളോടൊപ്പം വധിച്ച്, വലിയ കണ്ണുകളുള്ളവളേ, രാഘവൻ നിന്നെ സ്വന്തം നഗരത്തിലേക്ക് തിരികെ കൊണ്ടുപോകും.",
        "0.51": "\"രാഘവനോടും, മഹാബലശാലിയായ ലക്ഷ്മണനോടും, തേജസ്വിയായ സുഗ്രീവനോടും, കൂടിയിരിക്കുന്ന വാനരന്മാരോടും എന്ത് പറയണമെന്ന് എന്നോട് പറയൂ.\"",
        "0.52": "ഇത്രയും പറഞ്ഞപ്പോൾ സീത വീണ്ടും പറഞ്ഞു: \"ഉദാരമനസ്കയായ കൗസല്യ പ്രസവിച്ചവൻ, ലോകനാഥൻ —",
        "0.53": "\"അവനോട് എന്റെ പേരിൽ ക്ഷേമം അന്വേഷിച്ച്, അവന്റെ മുന്നിൽ തല നമസ്കരിക്കൂ. മാലകളും എല്ലാ ആഭരണങ്ങളും, പ്രിയരും സുന്ദരരുമായ സ്ത്രീകളെയും ഉപേക്ഷിച്ചവൻ,",
        "0.54": "\"വിശാലമായ ഭൂമിയിൽപ്പോലും നേടാൻ പ്രയാസമുള്ള രാജ്യാധികാരവും ഉപേക്ഷിച്ച്, അച്ഛനെയും അമ്മയെയും ബഹുമാനിച്ച് പ്രീതിപ്പെടുത്തിയശേഷം,",
        "0.55": "\"രാമനെ അനുഗമിച്ച് വനവാസത്തിന് പോയവൻ — ആരുടെ മൂലം സുമിത്രയ്ക്ക് ഉത്തമപുത്രനുണ്ടായോ അവൻ; ഉന്നതമായ സുഖസൗകര്യങ്ങൾ ഉപേക്ഷിച്ച് സ്വന്തം ഇഷ്ടപ്രകാരം",
        "0.56": "\"കാട്ടിൽ സഹോദരനെ കാത്ത്, കാകുത്സ്ഥനെ അനുഗമിക്കുന്ന ധർമ്മിഷ്ഠൻ — സിംഹത്തോൾ പോലെ വിശാലമായ തോളുള്ള, ബലമുള്ള ബാഹുക്കളുള്ള, ഉന്നതമനസ്കനും കാണാൻ മനോഹരനുമായവൻ.",
        "0.57": "\"രാമനോട് പിതാവിനെപ്പോലെയും എന്നോട് അമ്മയെപ്പോലെയും പെരുമാറുന്നവൻ — ഞാൻ കൊണ്ടുപോകപ്പെട്ടപ്പോൾ ആ വീരനായ ലക്ഷ്മണൻ അറിഞ്ഞിരുന്നില്ല.",
        "0.58": "\"മുതിർന്നവരെ സേവിക്കുന്ന, മഹത്വമുള്ള, കഴിവുള്ള, അധികം സംസാരിക്കാത്ത, രാജകുമാരന്മാരിൽ ഏറ്റവും ഉത്തമനും പ്രിയനുമായവൻ, എന്റെ അച്ഛൻ-അമ്മായിയപ്പനെപ്പോലെ.",
        "0.59": "\"ലക്ഷ്മണൻ, രാമന്റെ സഹോദരൻ; എപ്പോഴും എനിക്കുപോലും പ്രിയപ്പെട്ടവൻ; ആ വീരൻ തനിക്കു നൽകുന്ന ഏത് ഭാരവും വഹിക്കുന്നു.",
        "0.60": "\"ആരെ കാണുമ്പോൾ രാഘവൻ തന്റെ ദിവംഗതനായ മഹാനായ പിതാവിനെ ഓർക്കുന്നില്ലയോ — അവന്റെ ക്ഷേമം എന്റെ വാക്കുകളിലൂടെ എനിക്കുവേണ്ടി അന്വേഷിക്കൂ.",
        "0.61": "\"ലക്ഷ്മണൻ എപ്പോഴും സൗമ്യനും ശുദ്ധനും കഴിവുള്ളവനും രാമന് പ്രിയപ്പെട്ടവനുമാണ്; വാനരശ്രേഷ്ഠാ, എന്റെ ദുഃഖങ്ങൾ അവസാനിപ്പിക്കത്തക്കവിധം പ്രവർത്തിക്കൂ.",
        "0.62": "\"വാനരനേതാവേ, ഈ ദൗത്യം പൂർത്തിയാക്കുന്നതിൽ നീയാണ് അധികാരി; നിന്റെ പ്രയത്നത്താൽ രാഘവൻ എനിക്കുവേണ്ടി ഉത്സാഹിക്കട്ടെ.",
        "0.63": "\"എന്റെ നാഥനായ വീരൻ രാമനോട് ഇത് വീണ്ടും വീണ്ടും പറയൂ: 'ദശരഥപുത്രാ, ഞാൻ ഒരു മാസം ജീവൻ നിലനിർത്തും.",
        "0.64": "\"'ഒരു മാസത്തിനപ്പുറം ഞാൻ ജീവിക്കില്ല; ഇത് സത്യമായി ഞാൻ പറയുന്നു. വീരാ, ദുഷ്ടനായ രാവണൻ വഞ്ചനയാൽ ബന്ധിച്ച എന്നെ നീ രക്ഷിക്കണം; കൗശികിയെ പാതാളത്തിൽനിന്ന് രക്ഷിച്ചതുപോലെ.'\"",
        "0.65": "അപ്പോൾ തന്റെ വസ്ത്രത്തിൽനിന്ന് മനോഹരമായ ദിവ്യ ചൂഡാമണി അഴിച്ചെടുത്ത് സീത ഹനുമാന് നൽകി, \"ഇത് രാഘവന് നൽകണം\" എന്ന് പറഞ്ഞു.",
        "0.66": "ആ അതുല്യ രത്നം സ്വീകരിച്ച വീരൻ അത് വിരലിൽ അണിഞ്ഞു; കാരണം അത് അദ്ദേഹത്തിന്റെ കൈയിൽ കയറുമായിരുന്നില്ല.",
        "0.67": "ആ രത്നം സ്വീകരിച്ച്, സീതയെ അഭിവാദ്യം ചെയ്ത്, വാനരശ്രേഷ്ഠൻ അവളെ പ്രദക്ഷിണം ചെയ്ത്, ആദരപൂർവ്വം വണങ്ങി മാറിനിന്നു.",
        "0.68": "സീതയെ കണ്ടതിലെ വലിയ സന്തോഷത്താൽ, ഹൃദയത്തിൽ അദ്ദേഹം രാമനെയും ശുഭലക്ഷണനായ ലക്ഷ്മണനെയും ധ്യാനിച്ചു.",
        "0.69": "ജനകരാജപുത്രി തന്റെ ശക്തിയാൽ ധരിച്ചിരുന്ന ആ വിലയേറിയ രത്നം സ്വീകരിച്ച്, കാറ്റിൽനിന്ന് മോചിതമായ മഹാപർവതംപോലെ, സന്തോഷമുള്ള ഹൃദയത്തോടെ അദ്ദേഹം മടങ്ങാൻ ഒരുങ്ങി.",
        "0.70": "ഇങ്ങനെ ആദികാവ്യമായ, ശ്രീമദ് രാമായണത്തിലെ വാല്മീകി രചിച്ച സുന്ദരകാണ്ഡത്തിലെ മുപ്പത്തിയെട്ടാം സർഗ്ഗം സമാപിച്ചു."
      },
      "summary": "രാമന് അടയാളമായി, ചിത്രകൂടത്തിൽവെച്ച് തന്നെ ആക്രമിച്ച കാക്കയെ രാമൻ ശിക്ഷിച്ച സംഭവം സീത ഓർമ്മിക്കുന്നു. അവൾ അടിയന്തരമായ ഒരു സന്ദേശം അയയ്ക്കുകയും ഹനുമാന് ചൂഡാമണി നൽകുകയും ചെയ്യുന്നു."
    },
    "sundarakanda-39": {
      "verses": {
        "0.0": "ചൂഡാമണി നൽകിയശേഷം സീത ഹനുമാനോട് പറഞ്ഞു: \"ഈ അടയാളം രാമന് നന്നായി അറിയാവുന്നതാണ്.",
        "0.1": "\"ഈ രത്നം കണ്ടാൽ, വീരനായ രാമൻ മൂന്നുപേരെ ഓർക്കും: എന്റെ അമ്മയെയും എന്നെയും ദശരഥമഹാരാജാവിനെയും.",
        "0.2": "\"വാനരശ്രേഷ്ഠാ, ഈ ദൗത്യത്തിലുള്ള ഉത്സാഹത്താൽ വീണ്ടും പ്രേരിതനായി, ഇനി എന്തുചെയ്യണമെന്ന് ആലോചിക്കൂ.",
        "0.3": "\"വാനരശ്രേഷ്ഠാ, ഈ ദൗത്യം നിർവഹിക്കുന്നതിൽ നീ അധികാരിയാണ്; എന്റെ ദുഃഖത്തിന് അറുതി വരുത്താൻ എന്ത് പരിശ്രമം വേണമെന്ന് ചിന്തിക്കൂ.",
        "0.4": "\"ഹനുമാൻ, പരിശ്രമിച്ച് എന്റെ ദുഃഖം അവസാനിപ്പിക്കൂ.\" 'അങ്ങനെയാകട്ടെ' എന്ന് വാക്കുനൽകി, ഭയങ്കര പരാക്രമിയായ വായുപുത്രൻ,",
        "0.5": "വൈദേഹിക്ക് തല നമസ്കരിച്ച് പുറപ്പെടാൻ ഒരുങ്ങി. വായുപുത്രനായ വാനരൻ പുറപ്പെടുന്നുവെന്ന് അറിഞ്ഞ രാജ്ഞി,",
        "0.6": "മൈഥിലി കണ്ണീർ നിറഞ്ഞ സ്വരത്തിൽ പറഞ്ഞു: \"ഹനുമാൻ, രാമനും ലക്ഷ്മണനും ഒരുമിച്ച് എന്റെ ആശംസകൾ നൽകൂ.",
        "0.7": "\"മന്ത്രിമാരോടുകൂടിയ സുഗ്രീവനും, വാനരശ്രേഷ്ഠരായ എല്ലാ മുതിർന്നവർക്കും ധർമ്മാനുസരണം എന്റെ വന്ദനം അറിയിക്കൂ.",
        "0.8": "\"എന്നെ ചുറ്റിയിരിക്കുന്ന ഈ ദുഃഖപ്രവാഹത്തിൽനിന്ന് ബലശാലിയായ രാഘവൻ എന്നെ രക്ഷിക്കുന്ന വിധത്തിൽ നീ ക്രമീകരിക്കണം.",
        "0.9": "\"തേജസ്വിയായ രാമൻ ഞാൻ ഇപ്പോഴും ജീവനോടെയുണ്ടെന്ന് കണ്ടെത്തുന്ന വിധത്തിൽ സംസാരിക്കൂ; നിന്റെ വാക്കുകളാൽ പുണ്യം നേടൂ.",
        "0.10": "\"ഞാൻ പറഞ്ഞ വാക്കുകൾ കേട്ടാൽ, എപ്പോഴും ഉത്സാഹം നിറഞ്ഞ ദശരഥപുത്രന്റെ പുരുഷത്വം എന്നെ തിരിച്ചുപിടിക്കാൻ വർദ്ധിക്കും.",
        "0.11": "\"എന്റെ സന്ദേശം വഹിക്കുന്ന വാക്കുകൾ നിന്നിൽനിന്ന് കേട്ടാൽത്തന്നെ, വീരനായ രാഘവൻ വീര്യത്തിൽ മനസ്സുറപ്പിക്കും.\"",
        "0.12": "സീതയുടെ ആ വാക്കുകൾ കേട്ട്, വായുപുത്രനായ ഹനുമാൻ കൈകൂപ്പി തലയിൽവെച്ച് ഈ മറുപടി പറഞ്ഞു:",
        "0.13": "\"കാകുത്സ്ഥൻ വാനരശ്രേഷ്ഠന്മാരും കരടികളുമായി ഉടൻ വരും; യുദ്ധത്തിൽ ശത്രുക്കളെ കീഴടക്കി നിന്റെ ദുഃഖം അകറ്റും.",
        "0.14": "\"അമ്പുകൾ വർഷിച്ച് അവന്റെ മുന്നിൽ നിൽക്കാൻ ധൈര്യപ്പെടുന്ന ഒരു മനുഷ്യരിലും അസുരന്മാരിലും ദേവന്മാരിലും ഒരാളെയും ഞാൻ കാണുന്നില്ല.",
        "0.15": "\"സൂര്യനെപ്പോലും, പർജന്യനെപ്പോലും, വിവസ്വാന്റെ പുത്രനായ യമനെപ്പോലും യുദ്ധത്തിൽ നേരിടാൻ അവന് കഴിയും; പ്രത്യേകിച്ച് നിനക്കുവേണ്ടി.",
        "0.16": "\"സമുദ്രംവരെയുള്ള ഭൂമിമുഴുവൻ കീഴടക്കാൻ അവന് കഴിയും; ജനകപുത്രീ, രാമന്റെ വിജയം നിനക്കുവേണ്ടിയായിരിക്കും.\"",
        "0.17": "നന്നായി പറഞ്ഞതും പൂർണ്ണമായി സത്യമായതുമായ അവന്റെ വാക്കുകൾ കേട്ട് ജാനകി അവനെ വളരെ ബഹുമാനിച്ച് ഇങ്ങനെ പറഞ്ഞു:",
        "0.18": "പുറപ്പെടാനൊരുങ്ങിയ അവനെ വീണ്ടുംവീണ്ടും നോക്കി, സ്നേഹത്താൽ, ഭർത്താവിനോടുള്ള സ്നേഹം നിറഞ്ഞ വാക്കുകൾ അവനെ ബഹുമാനിച്ചുകൊണ്ട് സീത പറഞ്ഞു:",
        "0.19": "\"വീരാ, ശത്രുക്കളെ അമർത്തുന്നവനേ, നിനക്ക് ശരിയെന്ന് തോന്നുന്നെങ്കിൽ ഒരു ദിവസം ഏതെങ്കിലും മറഞ്ഞ സ്ഥലത്ത് താമസിക്കൂ; വിശ്രമിച്ചശേഷം നാളെ പോകാം.",
        "0.20": "\"ഭാഗ്യദോഷിയായ എനിക്ക്, വാനരാ, നിന്റെ സാന്നിധ്യം ഈ വലിയ ദുഃഖത്തിൽനിന്ന് ഒരു നിമിഷമെങ്കിലും മോചനം നൽകും.",
        "0.21": "\"വാനരശ്രേഷ്ഠാ, നീ പോയാൽ, നീ തിരിച്ചുവരുന്നതുവരെ എന്റെ ജീവനെക്കുറിച്ചുപോലും സംശയമുണ്ടാകും; അതിൽ സംശയമില്ല.",
        "0.22": "\"നിന്നെ കാണാത്തതിലെ ദുഃഖം എന്നെ വീണ്ടും പീഡിപ്പിക്കും, വാനരാ; ദുഃഖത്തിനുമേൽ ദുഃഖം ഏറ്റുവാങ്ങി തളർന്ന എന്നെ അത് ദഹിപ്പിക്കുന്നതുപോലെ.",
        "0.23": "\"വീരാ, വാനരരാജാവേ, നിന്റെ സഖ്യകക്ഷികളായ വാനരന്മാരെയും കരടികളെയും കുറിച്ച് ഈ വലിയ സംശയം എന്റെ മുന്നിൽ നിൽക്കുന്നു:",
        "0.24": "\"ആ വാനരസൈന്യങ്ങളും കരടികളും, അല്ലെങ്കിൽ ആ ഉത്തമപുരുഷന്റെ രണ്ടു പുത്രന്മാരും, കടക്കാനാവാത്ത ഈ മഹാസമുദ്രം എങ്ങനെ കടക്കും?",
        "0.25": "\"ഇവിടെനിന്ന് സമുദ്രം ചാടിക്കടക്കാൻ ശക്തിയുള്ളവർ മൂന്ന് പേർ മാത്രമാണ്: വിനതയുടെ പുത്രനായ ഗരുഡൻ, നീ, പിന്നെ വായുദേവൻ.",
        "0.26": "\"അതിനാൽ, വീരാ, നേടാൻ പ്രയാസമുള്ള ഈ ദൗത്യത്തിൽ നീ എന്ത് പരിഹാരമാണ് കാണുന്നത്? പ്രവർത്തിക്കേണ്ടത് എങ്ങനെയെന്ന് അറിയുന്നവരിൽ നീ ഏറ്റവും ഉത്തമനല്ലോ.",
        "0.27": "\"ശത്രുവീരന്മാരെ വധിക്കുന്നവനേ, ഈ ദൗത്യം പൂർത്തിയാക്കാൻ നീ ഒരാൾ മതി എന്നത് ശരിയാണ്; അതിന്റെ ഫലം നിനക്ക് കീർത്തി നൽകും.",
        "0.28": "\"എന്നാൽ രാഘവൻ തന്റെ മുഴുവൻ സൈന്യവുമായി രാവണനെ യുദ്ധത്തിൽ ജയിച്ച്, വിജയിയായി എന്നെ സ്വന്തം നഗരത്തിലേക്ക് കൊണ്ടുപോയാൽ അതാണ് അവന് യോജിച്ചത്.",
        "0.29": "\"ശത്രുസൈന്യങ്ങളെ തകർക്കുന്ന കാകുത്സ്ഥൻ തന്റെ സേനകൊണ്ട് ലങ്ക നിറച്ച് എന്നെ കൊണ്ടുപോയാൽ അതാണ് അവന് യോജിച്ചത്.",
        "0.30": "\"യുദ്ധത്തിൽ വീരനായ ആ മഹാത്മാവിന്റെ വീര്യത്തിന് യോജിക്കുന്ന വിധത്തിൽ അത് സാധ്യമാക്കൂ.\"",
        "0.31": "ആ അർത്ഥഗർഭവും വിനീതവും നന്നായി യുക്തിയുള്ളതുമായ വാക്കുകൾ കേട്ട്, ഹനുമാൻ അവസാന മറുപടി നൽകി:",
        "0.32": "\"രാജ്ഞീ, വാനരകരടിസൈന്യങ്ങളുടെ നാഥനായ സുഗ്രീവൻ, ചാട്ടക്കാരിൽ ഉത്തമനും വാക്കുപാലിക്കുന്നവനുമാണ്; നിന്റെ കാര്യത്തിൽ അവൻ ഉറച്ച തീരുമാനമെടുത്തിരിക്കുന്നു.",
        "0.33": "\"കോടിക്കണക്കിന് വാനരന്മാരാൽ ചുറ്റപ്പെട്ട്, വൈദേഹീ, ആ രാക്ഷസനാശകൻ ഉടൻ വരും.",
        "0.34": "\"അവന്റെ കല്പനയിൽ വീര്യം നിറഞ്ഞവരും ഉറച്ചവരും വളരെ ശക്തരുമായ വാനരന്മാരുണ്ട്; ചിന്തപോലെ വേഗത്തിൽ നീങ്ങുന്നവർ.",
        "0.35": "\"അവരുടെ ചലനം മുകളിലോ താഴെയോ വശങ്ങളിലോ തടസ്സപ്പെടുന്നില്ല; അതിരില്ലാത്ത ഊർജ്ജമുള്ള അവർ മഹത്തായ കാര്യങ്ങളിൽ ഒരിക്കലും പതറുന്നില്ല.",
        "0.36": "\"കാറ്റിന്റെ വഴിയിലൂടെ സഞ്ചരിക്കുന്ന ഉത്സാഹികളായ അവർ, സമുദ്രങ്ങളും പർവതങ്ങളുമടങ്ങിയ ഭൂമിയെ പലതവണ ചുറ്റിയിട്ടുണ്ട്.",
        "0.37": "\"അവിടെ എന്നെക്കാൾ മികച്ചവരും എനിക്ക് തുല്യരുമായ വനവാസികളുണ്ട്; സുഗ്രീവന്റെ കൂട്ടത്തിൽ ആരും എന്നെക്കാൾ താഴ്ന്നവരല്ല.",
        "0.38": "\"ഞാൻ ഇവിടെ വന്നിരിക്കെ, ആ ശക്തന്മാർ എത്രയധികം! ശ്രേഷ്ഠന്മാരെ ദൂതിനയക്കാറില്ല; മറ്റുള്ളവരെയാണ് അയക്കുന്നത്.",
        "0.39": "\"അതുകൊണ്ട് രാജ്ഞീ, ദുഃഖം മതി; നിന്റെ ശോകം അകന്നുപോകട്ടെ. വാനരസേനാനായകന്മാർ ഒറ്റച്ചാട്ടത്തിൽ ലങ്കയിലെത്തും.",
        "0.40": "\"ഉദിച്ചുയർന്ന ചന്ദ്രനെയും സൂര്യനെയും പോലെ എന്റെ പുറത്തിരിക്കുന്ന ആ രണ്ട് മനുഷ്യസിംഹങ്ങൾ വലിയ സൈന്യങ്ങളുമായി നിന്റെ അടുത്തെത്തും.",
        "0.41": "\"മനുഷ്യശ്രേഷ്ഠന്മാരായ ആ രണ്ട് വീരന്മാർ, രാമനും ലക്ഷ്മണനും ഒരുമിച്ച് ലങ്കാനഗരത്തിലെത്തി തങ്ങളുടെ അമ്പുകൾകൊണ്ട് അതിനെ നശിപ്പിക്കും.",
        "0.42": "\"അനുചരന്മാരോടൊപ്പം രാവണനെ വധിച്ച്, രഘുവംശത്തിന്റെ ആനന്ദമായ രാഘവൻ, സുന്ദരീ, നിന്നെ കൂട്ടിക്കൊണ്ട് സ്വന്തം നഗരത്തിലേക്ക് മടങ്ങും.",
        "0.43": "\"അതിനാൽ ധൈര്യമായിരിക്കൂ, നിനക്ക് ഐശ്വര്യമുണ്ടാകട്ടെ; ശരിയായ സമയത്തിനായി കാത്തിരിക്കൂ. താമസിയാതെ അഗ്നിപോലെ ജ്വലിക്കുന്ന രാമനെ നീ കാണും.",
        "0.44": "\"രാക്ഷസരാജാവ് പുത്രന്മാരോടും മന്ത്രിമാരോടും ബന്ധുക്കളോടുമൊപ്പം വധിക്കപ്പെടുമ്പോൾ, ചന്ദ്രനോടൊപ്പം രോഹിണിയെപ്പോലെ നീ രാമനോട് ഒന്നുചേരും.",
        "0.45": "\"മൈഥിലീ രാജ്ഞീ, ഉടൻ നിന്റെ ദുഃഖത്തിന്റെ അക്കര നീ കാണും; രാമന്റെ ശക്തിയാൽ വധിക്കപ്പെട്ട രാവണനെയും നീ കാണും.",
        "0.46": "ഇങ്ങനെ വൈദേഹിയെ ആശ്വസിപ്പിച്ച്, പോകാൻ തീരുമാനിച്ച ഹനുമാൻ, വായുപുത്രൻ, വീണ്ടും വൈദേഹിയോട് പറഞ്ഞു:",
        "0.47": "\"ശത്രുക്കളെ വധിക്കുന്ന, സ്വയം നിയന്ത്രിക്കുന്ന രാഘവനെയും, വില്ലുമേന്തിയ ലക്ഷ്മണനെയും ലങ്കയുടെ കവാടത്തിൽ എത്തിയതായി താമസിയാതെ നീ കാണും.",
        "0.48": "\"നഖങ്ങളും പല്ലുമുള്ള വീരന്മാരായ വാനരന്മാരെ, സിംഹങ്ങളെയും കടുവകളെയും പോലെ വീര്യമുള്ള, ഗജശ്രേഷ്ഠന്മാരെപ്പോലെയുള്ളവരെ താമസിയാതെ ഇവിടെ ഒന്നിച്ചുകൂടിയതായി നീ കാണും.",
        "0.49": "\"കുലീനയായ സ്ത്രീയേ, ലങ്കയിലെ മലയം പർവതത്തിന്റെ ചെരിവുകളിൽ, പർവതങ്ങളെയും മേഘങ്ങളെയും പോലെ ഗർജ്ജിക്കുന്ന വാനരനേതാക്കളുടെ അനേകം സൈന്യങ്ങളെ നീ കാണും.",
        "0.50": "\"പ്രണയത്തിന്റെ ഭയങ്കരമായ അമ്പ് അകത്തളങ്ങളിൽ തറച്ച രാമന് സിംഹം ആക്രമിച്ച ആനയെപ്പോലെ സമാധാനമില്ല.",
        "0.51": "\"രാജ്ഞീ, ദുഃഖത്താൽ കരയരുത്; ഹൃദയത്തിൽ ഭയം വേണ്ട. ഭർത്താവ് ഇന്ദ്രനോടൊപ്പം ശചി ചേരുന്നതുപോലെ, സുന്ദരീ, നീ നിന്റെ ഭർത്താവിനോട് ഒന്നുചേരും.",
        "0.52": "\"രാമനെക്കാൾ വലിയവനായി ആരുണ്ട്? സൗമിത്രിക്ക് തുല്യനായി ആരുണ്ട്? അഗ്നിയും വായുവുംപോലെയുള്ള ആ രണ്ടു സഹോദരന്മാരാണ് നിന്റെ അഭയം.",
        "0.53": "\"രാക്ഷസസംഘങ്ങൾ വസിക്കുന്ന ഈ അതിഭീകരമായ സ്ഥലത്ത് നീ ദീർഘകാലം ജീവിക്കില്ല, രാജ്ഞീ. നിന്റെ പ്രിയന്റെ വരവ് അധികം വൈകില്ല; ഞാൻ അവനെ കാണുന്നതുവരെ മാത്രം ക്ഷമിക്കൂ.\"",
        "0.54": "ഇങ്ങനെ ആദികാവ്യമായ, ശ്രീമദ് രാമായണത്തിലെ വാല്മീകി രചിച്ച സുന്ദരകാണ്ഡത്തിലെ മുപ്പത്തൊമ്പതാം സർഗ്ഗം സമാപിച്ചു."
      },
      "summary": "സീത ഈ സമുദ്രം എങ്ങനെ സൈന്യത്തിന് കടക്കാനാകുമെന്ന് ചോദിക്കുന്നു; ഒരു ദിവസം താമസിക്കാൻ ഹനുമാനോട് അപേക്ഷിക്കുന്നു. സുഗ്രീവന്റെ ശക്തരായ വാനരന്മാരും രാമനും ലക്ഷ്മണനും ഉടൻ വന്ന് ലങ്ക നശിപ്പിക്കുമെന്ന് ഹനുമാൻ ഉറപ്പു നൽകുന്നു."
    },
    "sundarakanda-40": {
      "verses": {
        "0.0": "മഹാത്മാവായ വായുപുത്രന്റെ വാക്കുകൾ കേട്ട്, ദേവകന്യകയെപ്പോലെയുള്ള സീത, തനിക്ക് ഗുണകരമായ വാക്കുകൾ പറഞ്ഞു:",
        "0.1": "\"ശുഭവാർത്ത കൊണ്ടുവരുന്ന നിന്നെ കാണുമ്പോൾ ഞാൻ സന്തോഷിക്കുന്നു, വാനരാ; മഴ ലഭിക്കുമ്പോൾ പകുതി വളർന്ന വിളകളുള്ള ഭൂമിപോലെ.",
        "0.2": "\"എന്നോട് കരുണ കാണിക്കൂ; എന്റെ ആഗ്രഹം സാധിച്ച്, ദുഃഖത്താൽ ക്ഷീണിച്ച ഈ അവയവങ്ങളാൽ ആ മനുഷ്യസിംഹനെ സ്പർശിക്കാൻ കഴിയുംവിധം പ്രവർത്തിക്കൂ.\"",
        "0.3": "\"വാനരശ്രേഷ്ഠാ, കാക്കയ്ക്കുനേരെ കോപത്തോടെ എറിഞ്ഞ, അതിന്റെ ഒരു കണ്ണ് നശിപ്പിച്ച ദർഭപ്പുല്ലിന്റെ തണ്ട് എന്നതാണ് ഈ അടയാളം; ഇത് രാമന് നൽകൂ.\"",
        "0.4": "\"'എന്റെ നെറ്റിയിലെ പൊട്ട് മായ്ക്കപ്പെട്ടപ്പോൾ, നീ എന്റെ കവിളിന്റെ വശത്ത് മനഃശിലകൊണ്ട് ചുവന്ന അടയാളം വരച്ചു' — ഇത് നീ തീർച്ചയായും ഓർമ്മിക്കണം.",
        "0.5": "\"'മഹേന്ദ്രനും വരുണനും തുല്യനായ വീര്യമുള്ളവനേ, സീത കൊണ്ടുപോകപ്പെട്ട് രാക്ഷസന്മാർക്കിടയിൽ കഴിയുന്നത് നിനക്ക് എങ്ങനെ സഹിക്കാനാകുന്നു?'\"",
        "0.6": "\"'ഈ ദിവ്യമായ ചൂഡാമണി ഞാൻ ശ്രദ്ധയോടെ സൂക്ഷിച്ചു; എന്റെ ദുരിതത്തിൽ അത് നോക്കി, കുറ്റമറ്റവനേ, നിന്നെ കാണുന്നതുപോലെ ഞാൻ സന്തോഷിച്ചു.'\"",
        "0.7": "\"'സമുദ്രത്തിൽനിന്ന് ഉയർന്ന ഈ മഹത്തായ രത്നം ഇപ്പോൾ നിനക്ക് തിരികെ അയയ്ക്കുന്നു; ഇതിനുശേഷം ദുഃഖത്താൽ ദഹിച്ച് എനിക്ക് ജീവിക്കാനാവില്ല.'\"",
        "0.8": "\"'നിനക്കുവേണ്ടി സഹിക്കാനാവാത്ത ദുഃഖങ്ങളും, ഹൃദയം തകർക്കുന്ന വാക്കുകളും, രാക്ഷസന്മാർക്കിടയിലെ ജീവിതവും ഞാൻ സഹിക്കുന്നു.'\"",
        "0.9": "\"'ശത്രുക്കളെ നശിപ്പിക്കുന്നവനേ, ഒരു മാസം ഞാൻ എന്നെ ജീവനോടെ നിലനിർത്തും; ആ മാസത്തിനപ്പുറം, രാജകുമാരാ, നിന്നില്ലാതെ ഞാൻ ജീവിക്കില്ല.'\"",
        "0.10": "\"'ഈ രാക്ഷസരാജാവ് ഭയങ്കരനാണ്; എന്റെ നേരെയുള്ള അവന്റെ നോട്ടം ദയയില്ലാത്തതാണ്; നീ താമസിക്കുന്നുവെന്ന് കേട്ടാൽ ഒരു നിമിഷംപോലും എനിക്ക് ജീവിക്കാനാവില്ല.'\"",
        "0.11": "കണ്ണീരോടെ പറഞ്ഞ വൈദേഹിയുടെ ദയനീയമായ വാക്കുകൾ കേട്ട്, അതിതേജസ്വിയായ വായുപുത്രൻ ഹനുമാൻ പറഞ്ഞു:",
        "0.12": "\"ദേവീ, സത്യം മുൻനിർത്തി ഞാൻ നിന്നോട് സത്യം ചെയ്യുന്നു: നിന്നെക്കുറിച്ചുള്ള ദുഃഖത്താൽ രാമൻ എല്ലാത്തിൽനിന്നും മുഖം തിരിച്ചിരിക്കുന്നു; ദുഃഖത്താൽ മുങ്ങിയ രാമനോടൊപ്പം ലക്ഷ്മണനും വേദനിക്കുന്നു.\"",
        "0.13": "\"ഏതെങ്കിലും വിധത്തിൽ നിന്നെ കണ്ടെത്തിയിരിക്കുന്നു; ഇത് വിലപിക്കേണ്ട സമയമല്ല. ഒരു മണിക്കൂറിനകം, സുന്ദരീ, നിന്റെ ദുഃഖങ്ങളുടെ അവസാനം നീ കാണും.\"",
        "0.14": "\"നിന്നെ കാണാനുള്ള പ്രതീക്ഷയാൽ പ്രേരിതരായ ആ രണ്ട് കുറ്റമറ്റ രാജകുമാരന്മാർ, മനുഷ്യസിംഹങ്ങൾ, ലങ്കയെ ചാരമാക്കും.\"",
        "0.15": "\"യുദ്ധത്തിൽ രാക്ഷസനായ രാവണനെ ബന്ധുക്കളോടൊപ്പം വധിച്ച്, രണ്ട് രാഘവന്മാരും വലിയ കണ്ണുകളുള്ള നിന്നെ നിന്റെ സ്വന്തം നഗരത്തിലേക്ക് തിരികെ കൊണ്ടുപോകും.\"",
        "0.16": "\"എന്നാൽ, കുറ്റമറ്റവളേ, രാമൻ തിരിച്ചറിയുകയും അദ്ദേഹത്തെ സന്തോഷിപ്പിക്കുകയും ചെയ്യുന്ന മറ്റൊരു അടയാളം നീ നൽകണം.\"",
        "0.17": "അവൾ പറഞ്ഞു: \"ഏറ്റവും മികച്ച അടയാളം ഞാൻ ഇതിനകം നൽകിയിട്ടുണ്ട്. എന്റെ ഈ ആഭരണം ശ്രദ്ധയോടെ നോക്കുമ്പോൾ രാമൻ",
        "0.18": "\"നിന്റെ വാക്കുകൾ തീർച്ചയായും വിശ്വസിക്കും, വീരനായ ഹനുമാനേ.\" ആ ഉത്തമരത്നം സ്വീകരിച്ച്, തേജസ്വിയായ വാനരശ്രേഷ്ഠൻ",
        "0.19": "ദേവിയെ തല നമസ്കരിച്ച് പുറപ്പെടാൻ ഒരുങ്ങി. ചാടാൻ ആവേശം കാണിക്കുന്ന വാനരസംഘനേതാവിനെ കണ്ട്,",
        "0.20": "വളർന്ന ശരീരവും വേഗവും നിറഞ്ഞ അവനെ നോക്കി, കണ്ണീരിൽ മുഖം നനഞ്ഞ ജനകപുത്രി, ദുഃഖിതയായി, വിങ്ങലോടെ പറഞ്ഞു:",
        "0.21": "\"ഹനുമാനേ, സിംഹസമാനരായ സഹോദരന്മാരായ രാമന്റെയും ലക്ഷ്മണന്റെയും, സുഗ്രീവന്റെയും മന്ത്രിമാരുടെയും, എല്ലാവരുടെയും ക്ഷേമം അന്വേഷിക്കൂ.\"",
        "0.22": "\"ദുഃഖത്തിന്റെ ഈ പ്രവാഹത്തിൽനിന്ന് ബലശാലിയായ രാഘവൻ എന്നെ രക്ഷിക്കുന്ന വിധത്തിൽ നീ ക്രമീകരിക്കണം.\"",
        "0.23": "\"നീ രാമനെ കണ്ടെത്തുമ്പോൾ, എന്റെ ഈ കടുത്ത ദുഃഖത്തിന്റെ പ്രവാഹവും ഈ രാക്ഷസന്മാരുടെ ഭീഷണിയും അവനോട് പറയൂ. വീരനായ വാനരാ, നിന്റെ യാത്ര ശുഭകരമാകട്ടെ.\"",
        "0.24": "രാജകുമാരി എല്ലാം പറഞ്ഞുകേട്ട വാനരൻ, തന്റെ ദൗത്യം പൂർത്തിയാക്കി, ഹൃദയം സന്തോഷിച്ച്, ദൗത്യത്തിൽ ചെറിയ ഭാഗം മാത്രം ശേഷിക്കുന്നത് കണ്ട്, ചിന്തയോടെ വടക്കോട്ട് തിരിഞ്ഞു.",
        "0.25": "ഇങ്ങനെ ആദികാവ്യമായ, ശ്രീമദ് രാമായണത്തിലെ വാല്മീകി രചിച്ച സുന്ദരകാണ്ഡത്തിലെ നാല്പതാം സർഗ്ഗം സമാപിച്ചു."
      },
      "summary": "സീത രാമനുള്ള അവസാന സന്ദേശം നൽകുന്നു; രഹസ്യമായ ഒരു അടയാളം ഓർമ്മിപ്പിക്കുകയും അവനെ അനുഗ്രഹിക്കുകയും ചെയ്യുന്നു. ഹനുമാൻ യാത്രപറഞ്ഞ് വടക്കോട്ട് തിരിയുന്നു."
    },
    "sundarakanda-41": {
      "verses": {
        "0.0": "പോകാനൊരുങ്ങിയപ്പോൾ അവളുടെ പ്രശംസാവാക്കുകളാൽ ആദരിക്കപ്പെട്ട വാനരൻ ആ സ്ഥലത്തുനിന്ന് മാറി ചിന്തിച്ചു:",
        "0.1": "\"ഈ ദൗത്യത്തിൽ ഇനി കുറച്ചുമാത്രമേ ശേഷിക്കുന്നുള്ളൂ: ഈ കറുത്ത കണ്ണുകളുള്ള സ്ത്രീയെ കണ്ടുകഴിഞ്ഞു. ആദ്യത്തെ മൂന്ന് ഉപായങ്ങളും ഒഴിവാക്കിയാൽ, നാലാമത്തേത് മാത്രമേ ഇവിടെ ബാധകമാകുന്നതായി കാണുന്നുള്ളൂ.",
        "0.2": "\"രാക്ഷസന്മാരോട് സാമം ഫലിക്കില്ല; ഇതിനകം സമ്പന്നരായവരോട് ദാനം ഉപയോഗമില്ല; ശക്തിയിൽ അഹങ്കരിക്കുന്നവരെ ഭേദത്താൽ കീഴടക്കാനാവില്ല. ഇവിടെ എനിക്ക് വീര്യം മാത്രമേ പ്രയോജനപ്പെടൂ.",
        "0.3": "\"വീര്യമില്ലാതെ ഈ കാര്യത്തിൽ ഉറപ്പുണ്ടാകില്ല; രാക്ഷസന്മാർ യുദ്ധത്തിൽ തങ്ങളുടെ പ്രധാന വീരന്മാരെ നഷ്ടപ്പെടുത്തിയാൽ, അവർ ഇന്ന് എങ്ങനെയെങ്കിലും അയഞ്ഞേക്കാം.",
        "0.4": "\"പ്രധാനകാര്യം പൂർത്തിയാകുമ്പോൾ, ആദ്യത്തേത് കേടുവരുത്താതെ മറ്റനേകം കാര്യങ്ങൾ ചെയ്യുന്നവനാണ് ദൗത്യം നിർവഹിക്കാൻ യോഗ്യൻ.",
        "0.5": "\"ചെറിയ ഒരു കാര്യത്തിനുപോലും ഒരൊറ്റ ഉപായം മതിയാകില്ല; ഒരു ലക്ഷ്യം പല വിധത്തിൽ മനസ്സിലാക്കുന്നവന് മാത്രമേ അത് നേടാനാകൂ.",
        "0.6": "\"ഇവിടെവെച്ചുതന്നെ ശത്രുവിന്റെയും നമ്മുടെയും ശക്തിയിലെ വ്യത്യാസം വ്യക്തമായി മനസ്സിലാക്കി, ഇന്ന് വാനരരാജാവിന്റെ വാസസ്ഥലത്തേക്ക് പോയാൽ, എന്റെ യജമാനന്റെ കല്പന പൂർണ്ണമായി നിറവേറ്റപ്പെടും.",
        "0.7": "\"അങ്ങനെയെങ്കിൽ ഇന്ന് രാക്ഷസന്മാരുമായുള്ള യുദ്ധം എളുപ്പത്തിൽ എങ്ങനെ സംഭവിക്കും? പത്തുതലയുള്ള രാവണൻ തന്റെ സമ്പൂർണ്ണ സൈന്യത്തിനെതിരെ എന്നെ യുദ്ധത്തിൽ നിർത്തുമോ?",
        "0.8": "\"അപ്പോൾ മന്ത്രിമാരോടും സൈന്യത്തോടും അനുചരന്മാരോടുംകൂടി പത്തുതലയുള്ള രാവണനെ യുദ്ധത്തിൽ നേരിടുകയും, അവന്റെ ഹൃദയത്തിലെ ഉദ്ദേശ്യവും ശക്തിയും എളുപ്പത്തിൽ അളക്കുകയും ചെയ്ത ശേഷം, ഞാൻ ഇവിടെനിന്ന് മടങ്ങും.",
        "0.9": "\"ക്രൂരന്റെ ഈ ഉദ്യാനം നന്ദനംപോലെ മനോഹരമാണ്; കണ്ണിനും മനസ്സിനും ആനന്ദം നൽകുന്ന, പലതരം മരങ്ങളും വള്ളിച്ചെടികളും നിറഞ്ഞത്.",
        "0.10": "\"ഉണങ്ങിയ കാടിനെ തീ ദഹിപ്പിക്കുന്നതുപോലെ ഞാനിതിനെ നശിപ്പിക്കും; ഇത് തകർന്നാൽ രാവണൻ കോപിക്കും.",
        "0.11": "\"അപ്പോൾ രാക്ഷസരാജാവ് കുതിരകളും മഹാരഥങ്ങളും ആനകളുമായി വലിയ സൈന്യത്തെ കൊണ്ടുവരും; ത്രിശൂലം, ഇരുമ്പുദണ്ഡം, കുന്തം എന്നിവയേന്തി; വലിയ യുദ്ധം ഉണ്ടാകും.",
        "0.12": "\"തകർക്കാനാവാത്ത വീര്യമുള്ള ഞാൻ ആ ഭയങ്കരരായ രാക്ഷസന്മാരെ യുദ്ധത്തിൽ നേരിട്ട്, രാവണൻ അയച്ച ആ സൈന്യത്തെ നശിപ്പിച്ചശേഷം, സന്തോഷത്തോടെ വാനരരാജാവിന്റെ വാസസ്ഥലത്തേക്ക് പോകും.\"",
        "0.13": "അപ്പോൾ കാറ്റുപോലെ കോപിച്ച, ഭയങ്കര പരാക്രമിയായ വായുപുത്രൻ തന്റെ തുടകളുടെ മഹാശക്തിയാൽ മരങ്ങൾ വലിച്ചെറിയാൻ തുടങ്ങി.",
        "0.14": "പിന്നെ വീരനായ ഹനുമാൻ, ആവേശഭരിതരായ പക്ഷികളുടെ കരച്ചിലാൽ മുഴങ്ങുന്നതും അനേകം മരങ്ങളും വള്ളിച്ചെടികളും നിറഞ്ഞതുമായ ആ ഉല്ലാസോദ്യാനം തകർത്തു.",
        "0.15": "മരങ്ങൾ പിഴുതെറിയപ്പെട്ട്, കുളങ്ങൾ തകർന്ന്, കുന്നുകൾ പൊടിയാക്കപ്പെട്ട്, ആ ഉദ്യാനം വൃത്തികെട്ട കാഴ്ചയായി മാറി.",
        "0.16": "അനേകം പക്ഷികളുടെ കരച്ചിലോടെ, കുളങ്ങൾ ചിതറിയും ചെമ്പുനിറമുള്ള തളിരുകൾ വാടിയും, മരങ്ങളും വള്ളികളും തൂങ്ങിയും,",
        "0.17": "ആ ഉദ്യാനം പിന്നെ തിളങ്ങിയില്ല; കാട്ടുതീ ബാധിച്ചതുപോലെ തോന്നി. ആവരണങ്ങൾ അലങ്കോലപ്പെട്ട വള്ളിച്ചെടികൾ ഭ്രാന്തരായ സ്ത്രീകളെപ്പോലെ കാണപ്പെട്ടു.",
        "0.18": "വള്ളിപ്പന്തലുകളും ചിത്രമണ്ഡപങ്ങളും തകർന്നും, ഇരപിടിയന്മാരായ മൃഗങ്ങളും മാനുകളും പക്ഷികളും ദുരിതത്തിൽ നിലവിളിച്ചും, കല്ലുകൊണ്ടുള്ള വീടുകളും മറ്റു കെട്ടിടങ്ങളും തകർന്നും, ആ മഹോദ്യാനം സൗന്ദര്യം മുഴുവൻ നഷ്ടപ്പെട്ടു.",
        "0.19": "വിറയ്ക്കുന്ന അശോകവള്ളികൾ വിരിച്ചിരുന്ന രാവണന്റെ ഉദ്യാനഭൂമി, വാനരന്റെ ശക്തിയാൽ ദുഃഖത്തിന്റെ വള്ളികൾ പടർന്ന ഭൂമിയായി മാറി.",
        "0.20": "ഇങ്ങനെ ഭൂമിപതിയായ ശക്തനായ രാജാവിന്റെ മനസ്സിനെ വലിയ തോതിൽ വേദനിപ്പിച്ച ആ മഹാവാനരൻ, തേജസ്സിൽ ജ്വലിച്ച്, അനേകം ശക്തരായ ശത്രുക്കളോട് ഒറ്റയ്ക്ക് പൊരുതാൻ ആഗ്രഹിച്ച്, കവാടത്തിൽ നിലയുറപ്പിച്ചു.",
        "0.21": "ഇങ്ങനെ ആദികാവ്യമായ, ശ്രീമദ് രാമായണത്തിലെ വാല്മീകി രചിച്ച സുന്ദരകാണ്ഡത്തിലെ നാല്പത്തൊന്നാം സർഗ്ഗം സമാപിച്ചു."
      },
      "summary": "രാക്ഷസരാജാവിന്റെ ശക്തി അളക്കാനായി മടങ്ങുന്നതിന് മുൻപ് രാവണനെ പ്രകോപിപ്പിക്കാൻ ഹനുമാൻ തീരുമാനിക്കുന്നു. അദ്ദേഹം മരങ്ങൾ പിഴുതെറിഞ്ഞ് മനോഹരമായ ഉദ്യാനം നശിപ്പിക്കുന്നു; സീത താമസിക്കുന്ന മരം മാത്രം ഒഴിവാക്കുന്നു."
    },
    "sundarakanda-42": {
      "verses": {
        "0.0": "അപ്പോൾ പക്ഷികളുടെ കരച്ചിലും മരങ്ങൾ ഒടിയുന്ന ശബ്ദവും കേട്ട് ലങ്കയിലെ എല്ലാ നിവാസികളും ഭയത്തിലും ആശയക്കുഴപ്പത്തിലും അകപ്പെട്ടു.",
        "0.1": "മൃഗങ്ങളും പക്ഷികളും ഭയന്ന് ഓടി നിലവിളിച്ചു; രാക്ഷസന്മാർക്ക് ക്രൂരമായ ദുശ്ശകുനങ്ങൾ കണ്ടു.",
        "0.2": "അപ്പോൾ ഉറക്കം നഷ്ടപ്പെട്ട്, വികൃതമുഖികളായ രാക്ഷസിമാർ ഉദ്യാനം തകർന്നതും ആ വീരനായ മഹാവാനരനെയും കണ്ടു.",
        "0.3": "അവരെ കണ്ട ബലശാലിയും മഹാമനസ്കനുമായ അദ്ദേഹം, രാക്ഷസിമാരിൽ ഭീതി വിതയ്ക്കുന്ന വലിയ രൂപം സ്വീകരിച്ചു.",
        "0.4": "അപ്പോൾ പർവതംപോലെ വലിയതും ശക്തവുമായ ആ വാനരനെ കണ്ട രാക്ഷസിമാർ ജനകപുത്രിയോട് ചോദിച്ചു:",
        "0.5": "\"ആരാണവൻ? അവൻ ആരുടേതാണ്? എവിടെനിന്നാണ് വന്നത്, എന്തിനാണ് ഇവിടെ വന്നത്? അവൻ നിന്നോട് സംസാരിച്ചിരുന്നത് എങ്ങനെയാണ്?",
        "0.6": "\"പറയൂ, വലിയ കണ്ണുകളുള്ളവളേ; ഭയപ്പെടേണ്ട, ഭാഗ്യവതീ. അവൻ നിന്നോട് എന്തു സംസാരിച്ചു, കറുത്ത കണ്ണുകളുള്ളവളേ?\"",
        "0.7": "അപ്പോൾ ഓരോ അവയവത്തിലും സുന്ദരിയായ പുണ്യവതിയായ സീത പറഞ്ഞു: \"ഇഷ്ടമുള്ള രൂപം സ്വീകരിക്കാൻ കഴിയുന്ന രാക്ഷസന്മാരെക്കുറിച്ച് ഞാനെന്തറിയാൻ?",
        "0.8": "\"അവൻ ആരാണെന്നും അവൻ എന്ത് ചെയ്യുമെന്നും നിങ്ങൾതന്നെ അറിയണം; പാമ്പിന്റെ വഴി പാമ്പുതന്നെയാണല്ലോ അറിയുന്നത്, സംശയമില്ല.\"",
        "0.9": "\"ഞാനും ഭയന്നിരിക്കുന്നു; അവൻ ആരാണെന്ന് എനിക്ക് ഒട്ടും അറിയില്ല; ഇഷ്ടമുള്ള രൂപത്തിൽ വന്ന ഒരു രാക്ഷസനാണെന്നാണ് ഞാൻ കരുതുന്നത്.\"",
        "0.10": "വൈദേഹിയുടെ വാക്കുകൾ കേട്ട രാക്ഷസിമാർ തിടുക്കത്തിൽ ചിതറിപ്പോയി; ചിലർ അവിടെത്തന്നെ നിന്നു, ചിലർ രാവണനെ അറിയിക്കാൻ പോയി.",
        "0.11": "രാവണന്റെ മുന്നിലെത്തിയ വികൃതമുഖികളായ രാക്ഷസിമാർ, ഭയങ്കരനും വെറുപ്പുളവാക്കുന്നവനുമായ വാനരനെക്കുറിച്ച് അവനോട് പറഞ്ഞു.",
        "0.12": "\"രാജാവേ, അശോകവനത്തിന്റെ മധ്യത്തിൽ ഭയങ്കര ശരീരവും അതിരില്ലാത്ത വീര്യവുമുള്ള ഒരു വാനരൻ നിൽക്കുന്നു; അവൻ സീതയോട് സംസാരിച്ചുകൊണ്ടിരുന്നു.",
        "0.13": "\"ജനകിയായ, മാൻമിഴിയുള്ള സീത, ഞങ്ങൾ പലവിധത്തിൽ ചോദിച്ചിട്ടും ആ വാനരനെക്കുറിച്ച് ഞങ്ങളോട് പറയുന്നില്ല.",
        "0.14": "\"അവൻ ഇന്ദ്രന്റെയോ കുബേരന്റെയോ ദൂതനായിരിക്കാം, അല്ലെങ്കിൽ സീതയെ കണ്ടെത്താനുള്ള ആഗ്രഹത്താൽ രാമൻ അയച്ചവനായിരിക്കാം.",
        "0.15": "\"പലതരം മൃഗങ്ങൾ നിറഞ്ഞിരുന്ന നിന്റെ മനോഹരമായ ഉദ്യാനം അത്ഭുതരൂപിയായ ആ ജീവി തകർത്തിരിക്കുന്നു.",
        "0.16": "\"ജനകി ഇരിക്കുന്ന സ്ഥലം ഒഴികെ അതിലെ ഒരു ഭാഗവും അവൻ നശിപ്പിക്കാതെ വിട്ടിട്ടില്ല; അത് അവൻ നശിപ്പിച്ചിട്ടില്ല.",
        "0.17": "\"ജനകിയെ സംരക്ഷിക്കാനാണോ, അതോ ക്ഷീണം കാരണമാണോ എന്ന് ഞങ്ങൾക്ക് പറയാനാവില്ല; പക്ഷേ അവന് എന്ത് ക്ഷീണമുണ്ടാകാൻ? അവൻ സംരക്ഷിച്ചത് അവളെയാണ്.",
        "0.18": "\"സുന്ദരമായ തളിരുകളും ഇലകളും നിറഞ്ഞ ഉയരമുള്ള ശിംശുപവൃക്ഷം, സീത സ്വയം താമസിക്കുന്ന അതിന്റെ കീഴിൽ — അതും അവൻ ഒഴിവാക്കി.",
        "0.19": "\"സീതയോട് സംസാരിക്കുകയും ഉദ്യാനം നശിപ്പിക്കുകയും ചെയ്ത ആ ഭയങ്കര രൂപിക്ക് കഠിനമായ ശിക്ഷ നൽകാൻ നീ കല്പിക്കണം.",
        "0.20": "\"രാക്ഷസസൈന്യങ്ങളുടെ നാഥാ, ജീവിക്കാനുള്ള പ്രതീക്ഷ മുഴുവൻ ഉപേക്ഷിച്ചിട്ടില്ലെങ്കിൽ, നീ മനസ്സുവെച്ചിരിക്കുന്ന സീതയോട് സംസാരിക്കാൻ ആരാണ് ധൈര്യപ്പെടുക?\"",
        "0.21": "രാക്ഷസിമാരുടെ വാക്കുകൾ കേട്ട രാക്ഷസരാജാവായ രാവണൻ, ചിതയിലെ അഗ്നിപോലെ ജ്വലിച്ചു; കോപത്താൽ കണ്ണുകൾ ഉരുട്ടി.",
        "0.22": "കോപിച്ചവന്റെ കണ്ണുകളിൽനിന്ന് ജ്വലിക്കുന്ന രണ്ട് വിളക്കുകളിൽനിന്ന് വീഴുന്ന എണ്ണത്തുള്ളികൾപോലെ കണ്ണീർ വീണു.",
        "0.23": "ശക്തനായ അവൻ, തന്നെപ്പോലെ വീരന്മാരായ കിങ്കരന്മാർ എന്ന രാക്ഷസന്മാരോട് ഹനുമാനെ പിടികൂടാൻ കല്പിച്ചു.",
        "0.24": "ആ കൊട്ടാരത്തിൽനിന്ന് വേഗമേറിയ എൺപതിനായിരം കിങ്കരന്മാർ, കൈകളിൽ ചുറ്റികകളും ഗദകളുമായി പുറത്തുവന്നു.",
        "0.25": "വലിയ വയറും നീണ്ട കൊമ്പുകളുമുള്ള, ഭയങ്കര രൂപവും ബലവുമുള്ള അവരെല്ലാവരും യുദ്ധത്തിന് ഒരുങ്ങിയവരും ഹനുമാനെ പിടികൂടാൻ ആഗ്രഹിച്ചവരുമായിരുന്നു.",
        "0.26": "കവാടത്തിൽ നിലയുറപ്പിച്ചിരുന്ന ആ വാനരന്റെ അടുത്തെത്തി, തീയിലേക്ക് പാറ്റകൾ പായുന്നതുപോലെ അവർ വലിയ വേഗത്തിൽ അവന്റെ നേർക്ക് പാഞ്ഞടുത്തു.",
        "0.27": "അലങ്കരിച്ച ഗദകളും സ്വർണ്ണവളയങ്ങൾ ചുറ്റിയ ഇരുമ്പുദണ്ഡങ്ങളും സൂര്യനെപ്പോലെ തിളങ്ങുന്ന അമ്പുകളും കൊണ്ട് അവർ വാനരശ്രേഷ്ഠനെ ആക്രമിച്ചു.",
        "0.28": "ചുറ്റികകൾ, കുന്തങ്ങൾ, ത്രിശൂലങ്ങൾ, വേലുകൾ, ഈട്ടികൾ എന്നിവ കൈകളിലേന്തി, പെട്ടെന്ന് അവർ ഹനുമാനെ വളഞ്ഞ് മുന്നിൽ നിന്നു.",
        "0.29": "മലപോലെ വലിയ തേജസ്വിയും മഹിമയുള്ളവനുമായ ഹനുമാൻ വാൽ നിലത്തടിച്ച് ഭയങ്കരമായി ഗർജ്ജിച്ചു.",
        "0.30": "വായുപുത്രനായ ഹനുമാൻ വലിയ രൂപം സ്വീകരിച്ച് വാൽ അടിച്ചു; ആ ശബ്ദം കൊണ്ട് ലങ്ക നിറഞ്ഞു.",
        "0.31": "ആ വാൽ അടിയുടെ ഉച്ചത്തിലുള്ള പ്രതിധ്വനികേട്ട് പക്ഷികൾ ആകാശത്തുനിന്ന് വീണു; അപ്പോൾ അദ്ദേഹം ഉറക്കെ പ്രഖ്യാപിച്ചു:",
        "0.32": "\"അതിശക്തനായ രാമന് ജയം! ബലശാലിയായ ലക്ഷ്മണന് ജയം! രാഘവനാൽ സംരക്ഷിക്കപ്പെടുന്ന സുഗ്രീവ രാജാവിന് ജയം!\"",
        "0.33": "\"ഞാൻ കോസലരാജാവായ രാമന്റെ ദാസനാണ്; അനായാസമായി പ്രവൃത്തി ചെയ്യുന്നവൻ. ഞാൻ വായുപുത്രൻ ഹനുമാൻ, ശത്രുസൈന്യങ്ങളെ നശിപ്പിക്കുന്നവൻ.\"",
        "0.34": "\"ആയിരം രാവണന്മാർക്കുപോലും യുദ്ധത്തിൽ എന്നെ നേരിടാനാവില്ല; ആയിരക്കണക്കിന് പാറകൾകൊണ്ടും മരങ്ങൾകൊണ്ടും ഞാൻ പ്രഹരിക്കുന്നതിനാൽ.\"",
        "0.35": "\"ലങ്കാനഗരം നശിപ്പിച്ച്, മൈഥിലിക്ക് വന്ദിച്ച ശേഷം, എന്റെ ലക്ഷ്യം സാധിച്ച് ഞാൻ പോകും; രാക്ഷസന്മാരെല്ലാം നോക്കിനിൽക്കെ.\"",
        "0.36": "അവന്റെ ഗർജ്ജനശബ്ദത്തിൽ അവർ ഭയംകൊണ്ട് പിടിക്കപ്പെട്ടു; സന്ധ്യാമേഘംപോലെ ഉയർന്നുനിൽക്കുന്ന ഹനുമാനെ അവർ കണ്ടു.",
        "0.37": "അപ്പോൾ യജമാനന്റെ കല്പനയാൽ ധൈര്യം കിട്ടിയ ആ രാക്ഷസന്മാർ, വിചിത്രവും ഭയങ്കരവുമായ ആയുധങ്ങളുമായി, എല്ലാ ഭാഗത്തുനിന്നും വാനരന്റെ മേൽ ചാടി വീണു.",
        "0.38": "ആ യോദ്ധാക്കളാൽ എല്ലാ വശങ്ങളിലും ചുറ്റപ്പെട്ട ബലശാലി, ഗോപുരവാതിലിൽ കിടന്നിരുന്ന ഭയങ്കരമായ ഒരു ഇരുമ്പുദണ്ഡ് എടുത്തു.",
        "0.39": "ആ ദണ്ഡെടുത്ത്, പുളയുന്ന സർപ്പത്തെ പിടികൂടുന്ന വിനതാപുത്രൻ ഗരുഡനെപ്പോലെ അദ്ദേഹം രാത്രിസഞ്ചാരികളായ രാക്ഷസന്മാരെ അടിച്ചുവീഴ്ത്തി.",
        "0.40": "അത് ചുഴറ്റി, വീരനായ വായുപുത്രൻ ആകാശത്തിലൂടെ സഞ്ചരിച്ച് അവരെ വധിച്ചു; ആയിരം കണ്ണുള്ള ഇന്ദ്രൻ വജ്രായുധംകൊണ്ട് ദൈത്യന്മാരെ വധിച്ചതുപോലെ.",
        "0.41": "കിങ്കര രാക്ഷസന്മാരെ വധിച്ച ശേഷം, യുദ്ധത്തിന് വീണ്ടും ആഗ്രഹിച്ച വീരനായ വായുപുത്രൻ, ഗോപുരവാതിലിൽ വീണ്ടും നിലയുറപ്പിച്ചു.",
        "0.42": "അപ്പോൾ ആ ഭയത്തിൽനിന്ന് രക്ഷപ്പെട്ട ചില രാക്ഷസന്മാർ, കിങ്കരന്മാരെല്ലാം കൊല്ലപ്പെട്ടു എന്ന് രാവണനെ അറിയിച്ചു.",
        "0.43": "രാക്ഷസസൈന്യം മഹാതേജസ്വികളാൽ നശിപ്പിക്കപ്പെട്ടു എന്ന് കേട്ട രാജാവ്, കോപത്താൽ കണ്ണുകൾ ഉരുട്ടി, താരതമ്യമില്ലാത്ത വീര്യമുള്ളവനും യുദ്ധത്തിൽ കീഴടക്കാൻ പ്രയാസമുള്ളവനുമായ പ്രഹസ്തന്റെ പുത്രനെ പുറപ്പെടാൻ കല്പിച്ചു.",
        "0.44": "ഇങ്ങനെ ആദികാവ്യമായ, ശ്രീമദ് രാമായണത്തിലെ വാല്മീകി രചിച്ച സുന്ദരകാണ്ഡത്തിലെ നാല്പത്തിരണ്ടാം സർഗ്ഗം സമാപിച്ചു."
      },
      "summary": "രാക്ഷസിമാർ നാശവിവരം രാവണനെ അറിയിക്കുന്നു; രാവണൻ കിങ്കരന്മാരെന്ന ഒരു സേനയെ അയയ്ക്കുന്നു. രാമനും സുഗ്രീവനും ജയം പ്രഖ്യാപിച്ച്, ഹനുമാൻ ഇരുമ്പുദണ്ഡംകൊണ്ട് അവരെയെല്ലാം വധിക്കുന്നു."
    },
    "sundarakanda-43": {
      "verses": {
        "0.0": "കിങ്കരന്മാരെ വധിച്ചശേഷം ഹനുമാൻ ചിന്തിച്ചു: \"ഉദ്യാനം ഞാൻ തകർത്തു; പക്ഷേ ഈ ഗോപുരസൗധം ഞാൻ നശിപ്പിച്ചിട്ടില്ല.",
        "0.1": "\"അതിനാൽ ഇന്നുതന്നെ ഈ കൊട്ടാരം ഞാൻ നശിപ്പിക്കും.\" ഇങ്ങനെ ചിന്തിച്ച്, ഉറച്ച തീരുമാനത്താൽ തന്റെ ശക്തി കാണിച്ച്,",
        "0.2": "മേരുവിന്റെ ശിഖരംപോലെ ഉയർന്ന ആ ഗോപുരസൗധത്തിലേക്ക് ചാടിക്കയറി; വായുപുത്രനായ ആ വാനരശ്രേഷ്ഠൻ.",
        "0.3": "പർവതംപോലുള്ള ആ കൊട്ടാരത്തിൽ കയറിയ മഹാതേജസ്വിയായ വാനരനേതാവ്, പുതുതായി ഉദിച്ച രണ്ടാം സൂര്യനെപ്പോലെ തിളങ്ങി.",
        "0.4": "ഉയർന്ന ഗോപുരസൗധം ആക്രമിച്ച അജയ്യനായ ഹനുമാൻ, തേജസ്സിൽ ജ്വലിച്ച്, പാരിയാത്ര പർവതംപോലെ കാണപ്പെട്ടു.",
        "0.5": "വലിയ രൂപം സ്വീകരിച്ച്, ബലശാലിയായ വായുപുത്രൻ ധൈര്യത്തോടെ കൈകൾ അടിച്ചു; ആ ശബ്ദംകൊണ്ട് ലങ്ക നിറഞ്ഞു.",
        "0.6": "ആ ചെവി പിളർക്കുന്ന ശബ്ദം കേട്ട് അവിടെ പക്ഷികൾ വീണു; ഗോപുരകാവൽക്കാർ സ്തബ്ധരായി.",
        "0.7": "\"ആയുധവിദ്യയിൽ നിപുണനായ രാമന് ജയം! ശക്തനായ ലക്ഷ്മണന് ജയം! രാഘവനാൽ സംരക്ഷിക്കപ്പെടുന്ന സുഗ്രീവ രാജാവിന് ജയം!\"",
        "0.8": "\"ഞാൻ കോസലരാജാവായ രാമന്റെ ദാസനാണ്; അനായാസമായി പ്രവൃത്തി ചെയ്യുന്നവൻ. ഞാൻ വായുപുത്രൻ ഹനുമാൻ, ശത്രുസൈന്യങ്ങളെ നശിപ്പിക്കുന്നവൻ.\"",
        "0.9": "\"ആയിരം രാവണന്മാർക്കുപോലും യുദ്ധത്തിൽ എന്നെ നേരിടാനാവില്ല; ആയിരക്കണക്കിന് പാറകൾകൊണ്ടും മരങ്ങൾകൊണ്ടും ഞാൻ പ്രഹരിക്കുന്നതിനാൽ.\"",
        "0.10": "\"ലങ്കാനഗരത്തെ കീഴടക്കി, മൈഥിലിക്ക് വന്ദിച്ച ശേഷം, എന്റെ ലക്ഷ്യം സാധിച്ച് ഞാൻ പോകും; രാക്ഷസന്മാരെല്ലാം നോക്കിനിൽക്കെ.\"",
        "0.11": "ഇങ്ങനെ പറഞ്ഞശേഷം, കൊട്ടാരത്തിന്മേൽ നിന്ന ആ വലിയ വാനരനേതാവ്, രാക്ഷസന്മാരിൽ ഭയം ജനിപ്പിക്കുന്ന ഭയങ്കര ശബ്ദത്തിൽ ഗർജ്ജിച്ചു.",
        "0.12": "ആ മഹാഗർജ്ജനം കേട്ട് നൂറു ഗോപുരകാവൽക്കാർ വിവിധ ആയുധങ്ങളുമായി വന്നു — കുന്തങ്ങളും വാളുകളും മഴുവും.",
        "0.13": "ആ ഭീമാകാരരായ രാക്ഷസന്മാർ അവ എറിഞ്ഞ്, വായുപുത്രനെ വളഞ്ഞു; അലങ്കരിച്ച ഗദകളും സ്വർണ്ണം ചുറ്റിയ ഇരുമ്പുദണ്ഡങ്ങളുമായി,",
        "0.14": "സൂര്യനെപ്പോലെ തിളങ്ങുന്ന അമ്പുകളുമായി അവർ വാനരശ്രേഷ്ഠനെ ആക്രമിച്ചു. ഗംഗയിലെ വെള്ളത്തിലെ വലിയ ചുഴിപോലെ,",
        "0.15": "വാനരശ്രേഷ്ഠനെ വളഞ്ഞ ആ രാക്ഷസസംഘം മനോഹരമായി കാണപ്പെട്ടു. അപ്പോൾ കോപിച്ച വായുപുത്രൻ ഭയങ്കര രൂപം സ്വീകരിച്ചു.",
        "0.16": "വായുപുത്രനായ ഹനുമാൻ, ആ കൊട്ടാരത്തിലെ സ്വർണ്ണാലങ്കൃതമായ ഒരു വലിയ തൂൺ ബലമായി പിഴുതെടുത്തു.",
        "0.17": "ബലശാലി അത് നൂറ് വക്കുകളോടെ ചുഴറ്റി; അതിൽനിന്ന് തീ പടർന്നു, കൊട്ടാരം കത്താൻ തുടങ്ങി.",
        "0.18": "കൊട്ടാരം കത്തുന്നത് കണ്ട വാനരനേതാവ്, ഇന്ദ്രൻ വജ്രംകൊണ്ട് അസുരന്മാരെ വധിക്കുന്നതുപോലെ നൂറ് രാക്ഷസന്മാരെ വധിച്ചു;",
        "0.19": "ആകാശത്ത് നിന്ന ആ തേജസ്വി ഇങ്ങനെ പറഞ്ഞു: \"എന്നെപ്പോലുള്ള മഹാത്മാക്കളായ ആയിരങ്ങൾ അയയ്ക്കപ്പെട്ടിരിക്കുന്നു —",
        "0.20": "\"സുഗ്രീവന് അനുസരണയുള്ള മഹാവാനര നേതാക്കൾ. ഞങ്ങളും മറ്റ് വാനരന്മാരും ഭൂമി മുഴുവൻ അലഞ്ഞുനടക്കുന്നു.\"",
        "0.21": "\"ചിലർക്ക് പത്ത് ആനകളുടെ ബലമുണ്ട്, ചിലർക്ക് അതിലും പത്തിരട്ടി; ചിലർ ആയിരം ആനകൾക്ക് തുല്യമായ വീര്യമുള്ളവർ.\"",
        "0.22": "\"ചിലർക്ക് വെള്ളപ്പാച്ചിലിന്റെ ബലമുണ്ട്, ചിലർ കാറ്റിനു തുല്യമായ ശക്തിയുള്ളവർ; ആ വാനരനേതാക്കളിൽ ചിലർ അളക്കാനാവാത്ത ബലമുള്ളവരാണ്.\"",
        "0.23": "\"പല്ലും നഖവുമുള്ള അത്തരം വാനരന്മാരാൽ ചുറ്റപ്പെട്ട്, നൂറുകണക്കിനും ലക്ഷക്കണക്കിനും പതിനായിരക്കണക്കിനും കോടിക്കണക്കിനുമായി,",
        "0.24": "\"നിങ്ങളെ എല്ലാവരെയും നശിപ്പിക്കുന്ന സുഗ്രീവൻ വരും. ഇക്ഷ്വാകുവംശത്തിലെ മഹാത്മാവായ വീരനോട് ശത്രുത ഉണ്ടാക്കിയതിനാൽ, ഈ ലങ്കാനഗരമോ, നീയോ, രാവണനോ അതിജീവിക്കില്ല.\"",
        "0.25": "ഇങ്ങനെ ആദികാവ്യമായ, ശ്രീമദ് രാമായണത്തിലെ വാല്മീകി രചിച്ച സുന്ദരകാണ്ഡത്തിലെ നാല്പത്തിമൂന്നാം സർഗ്ഗം സമാപിച്ചു."
      },
      "summary": "ഹനുമാൻ ഉയർന്ന ചൈത്യപ്രാസാദത്തിൽ കയറി അത് തകർക്കുന്നു; രാമന്റെ വിജയം വീണ്ടും പ്രഖ്യാപിക്കുന്നു. അതിന്റെ ഒരു തൂണെടുത്ത് തന്നെ ആക്രമിക്കാൻ കുതിച്ചെത്തിയ കാവൽക്കാരെ വധിക്കുന്നു."
    },
    "sundarakanda-44": {
      "verses": {
        "0.0": "രാക്ഷസരാജാവിന്റെ കല്പനപ്രകാരം, പ്രഹസ്തന്റെ വീരപുത്രനായ വലിയ കൊമ്പുകളുള്ള ജംബുമാലി വില്ലേന്തി പുറപ്പെട്ടു.",
        "0.1": "ചുവന്ന മാലയും ചുവന്ന വസ്ത്രവും, കിരീടവും മനോഹരമായ കമ്മലുകളും അണിഞ്ഞിരുന്നു; ഭീമാകാരനും ഉരുണ്ട കണ്ണുകളുള്ളവനും ഭയങ്കരനും യുദ്ധത്തിൽ കീഴടക്കാൻ പ്രയാസമുള്ളവനുമായിരുന്നു.",
        "0.2": "ഇന്ദ്രധനുസ്സുപോലെ തന്റെ വലിയ വില്ല് ബലമായി വലിച്ചു; മനോഹരമായ അമ്പുകളും, വജ്രം പോലുള്ള ശബ്ദവുമുള്ള വില്ല്.",
        "0.3": "ആ വില്ലിന്റെ ഉച്ചത്തിലുള്ള ടങ്കാരം കേട്ട് ദിക്കുകളും ഉപദിക്കുകളും ആകാശവും പെട്ടെന്ന് നിറഞ്ഞു.",
        "0.4": "കഴുതകൾ വലിക്കുന്ന രഥത്തിൽ അവൻ വരുന്നത് കണ്ട്, വേഗമുള്ള ഹനുമാൻ സന്തോഷിച്ച് ഗർജ്ജിച്ചു.",
        "0.5": "ഗോപുരത്തിന്റെ മുകളിൽ ഇരുന്ന ആ മഹാവാനരനെ ബലശാലിയായ ജംബുമാലി മൂർച്ചയുള്ള അമ്പുകളാൽ തുളച്ചു.",
        "0.6": "വാനരനാഥനെ അവൻ മുഖത്ത് അർദ്ധചന്ദ്രാകൃതിയുള്ള അമ്പുകൊണ്ടും, തലയിൽ ചുഴിയുള്ള അമ്പുകൊണ്ടും, കൈകളിൽ പത്ത് ഇരുമ്പു ശരങ്ങൾകൊണ്ടും പ്രഹരിച്ചു.",
        "0.7": "അമ്പേറ്റ് ചെമ്പുനിറമുള്ള അവന്റെ മുഖം, ശരത്കാലത്ത് സൂര്യരശ്മി തുളച്ച പൂർണ്ണവികസിത താമരപോലെ തിളങ്ങി.",
        "0.8": "രക്തത്താൽ കൂടുതൽ ചുവന്ന ആ മുഖം, ചുവന്ന ചന്ദനത്തുള്ളികൾ തളിച്ച ആകാശത്തിലെ വലിയ താമരപോലെ തിളങ്ങി.",
        "0.9": "രാക്ഷസന്റെ അമ്പുകളേറ്റ് മഹാവാനരന് കോപം വർദ്ധിച്ചു; അപ്പോൾ അരികിൽ വലുതും വീതിയുള്ളതുമായ ഒരു പാറ അദ്ദേഹം കണ്ടു.",
        "0.10": "ബലശാലി അത് വേഗത്തിൽ പിഴുതെടുത്ത് ശക്തിയോടെ എറിഞ്ഞു; കോപിച്ച രാക്ഷസൻ പത്ത് അമ്പുകൾകൊണ്ട് അത് തകർത്തു.",
        "0.11": "ആ ശ്രമം വിഫലമായത് കണ്ട്, ഭയങ്കര വീര്യമുള്ള ഹനുമാൻ ഒരു വലിയ സാലവൃക്ഷം പിഴുതെടുത്ത് ചുഴറ്റി.",
        "0.12": "സാലവൃക്ഷം ചുഴറ്റുന്ന ആ മഹാവാനരനെ കണ്ട്, ശക്തനായ ജംബുമാലി ധാരാളം അമ്പുകൾ തൊടുത്തു.",
        "0.13": "നാലെണ്ണംകൊണ്ട് അവൻ സാലവൃക്ഷം മുറിച്ചു; അഞ്ചെണ്ണംകൊണ്ട് വാനരന്റെ കൈയിൽ, ഒന്നുകൊണ്ട് തലയിൽ, പത്തെണ്ണംകൊണ്ട് നെഞ്ചിൽ പ്രഹരിച്ചു.",
        "0.14": "അമ്പുകൾകൊണ്ട് ശരീരം നിറഞ്ഞ്, വലിയ കോപം പിടികൂടിയ അദ്ദേഹം അതേ ഇരുമ്പുദണ്ഡ് പിടിച്ച് വേഗത്തിൽ ചുഴറ്റി.",
        "0.15": "അതിവേഗത്തിൽ ചുഴറ്റി, അതുല്യ ശക്തിയുള്ളവൻ ജംബുമാലിയുടെ വിശാലമായ നെഞ്ചിൽ ദണ്ഡ് വീഴ്ത്തി.",
        "0.16": "അവന് പിന്നെ തലയോ കൈകളോ മുട്ടുകളോ ശേഷിച്ചില്ല; വില്ലോ രഥമോ കുതിരകളോ അമ്പുകളോ അവിടെ കാണാനായില്ല.",
        "0.17": "അവന്റെ ശക്തമായ അടിയേറ്റ്, ബലശാലിയായ ജംബുമാലി നിലത്ത് മരിച്ചുവീണു; അവന്റെ അവയവങ്ങളും ആഭരണങ്ങളും തകർന്നു.",
        "0.18": "ജംബുമാലിയും ശക്തരായ കിങ്കരന്മാരും കൊല്ലപ്പെട്ടു എന്ന് കേട്ട് രാവണൻ കോപത്താൽ പ്രജ്വലിച്ചു; കണ്ണുകൾ ചുവന്നു.",
        "0.19": "പ്രഹസ്തന്റെ വീരപുത്രൻ കൊല്ലപ്പെട്ടപ്പോൾ, രാക്ഷസരുടെ നാഥൻ ചെമ്പുനിറമുള്ള കണ്ണുകൾ ഉരുട്ടി, അതിശക്തരും വീര്യമുള്ളവരുമായ തന്റെ മന്ത്രിമാരുടെ പുത്രന്മാരോട് ഉടൻ കല്പിച്ചു.",
        "0.20": "ഇങ്ങനെ ആദികാവ്യമായ, ശ്രീമദ് രാമായണത്തിലെ വാല്മീകി രചിച്ച സുന്ദരകാണ്ഡത്തിലെ നാല്പത്തിനാലാം സർഗ്ഗം സമാപിച്ചു."
      },
      "summary": "പ്രഹസ്തന്റെ വീരപുത്രനായ ജംബുമാലിയെ രാവണൻ അയയ്ക്കുന്നു; അവൻ അമ്പുകൾകൊണ്ട് ഹനുമാനെ മുറിവേൽപ്പിക്കുന്നു. ഹനുമാൻ ഇരുമ്പുദണ്ഡുകൊണ്ട് അവനെയും അവന്റെ രഥത്തെയും വധിക്കുന്നു."
    },
    "sundarakanda-45": {
      "verses": {
        "0.0": "പിന്നെ രാക്ഷസരാജാവിന്റെ പ്രേരണയാൽ, തീപോലെ തിളങ്ങുന്ന മന്ത്രിമാരുടെ ഏഴു പുത്രന്മാർ ആ കൊട്ടാരത്തിൽനിന്ന് പുറപ്പെട്ടു.",
        "0.1": "വലിയ സൈന്യത്താൽ ചുറ്റപ്പെട്ട്, വില്ലേന്തി, അതിബലശാലികളും ആയുധവിദ്യയിൽ നിപുണരും വിദഗ്ധരിൽ പ്രമുഖരുമായി, ഓരോരുത്തരും വിജയത്തിൽ മറ്റുള്ളവരെ മറികടക്കാൻ ആഗ്രഹിച്ചവർ,",
        "0.2": "കുതിരകൾ പൂട്ടിയ മഹാരഥങ്ങളിൽ, സ്വർണ്ണവലകളും പതാകകളും കൊടികളും തൂങ്ങിക്കിടക്കുന്നവയിൽ, ഇടിമേഘങ്ങൾപോലെ മുഴങ്ങിക്കൊണ്ട് വന്നു;",
        "0.3": "അതിരില്ലാത്ത വീര്യമുള്ള ആ പുരുഷന്മാർ, ആവേശത്തോടെ, മിനുക്കിയ സ്വർണ്ണംകൊണ്ട് പണിത വില്ലുകൾ വലിച്ചു; മിന്നലോടുകൂടിയ മേഘങ്ങൾപോലെ അവർ തിളങ്ങി.",
        "0.4": "കിങ്കരന്മാർ കൊല്ലപ്പെട്ടു എന്നറിഞ്ഞ അവരുടെ അമ്മമാർ, ബന്ധുക്കളോടും സുഹൃത്തുക്കളോടുമൊപ്പം ദുഃഖത്താൽ വ്യാകുലരായി.",
        "0.5": "ഒന്നിനൊന്ന് മത്സരിച്ച്, മിനുക്കിയ സ്വർണ്ണാഭരണങ്ങൾ അണിഞ്ഞ്, അവർ കവാടത്തിൽ നിന്ന ഹനുമാന്റെ നേർക്ക് പാഞ്ഞടുത്തു.",
        "0.6": "അമ്പുകളുടെ മഴ വർഷിച്ച്, ഇടിമുഴക്കംപോലെ രഥങ്ങൾ ഗർജ്ജിച്ച്, ആ രാക്ഷസമേഘങ്ങൾ മഴക്കാലത്തെ മേഘങ്ങൾപോലെ ചുറ്റിനടന്നു.",
        "0.7": "ആ അമ്പുമഴകൊണ്ട് മൂടപ്പെട്ട ഹനുമാന്റെ രൂപം മറഞ്ഞു, മഴയിൽ മുങ്ങിയ പർവതരാജാവുപോലെ.",
        "0.8": "വേഗത്തിൽ സഞ്ചരിച്ച വാനരൻ, ആ അമ്പുകളെയും വീരന്മാരുടെ രഥങ്ങളുടെ പാച്ചിലിനെയും ഒഴിഞ്ഞുമാറി തെളിഞ്ഞ ആകാശത്തിലൂടെ സഞ്ചരിച്ചു.",
        "0.9": "ആകാശത്ത് ആ വില്ലാളികളോടൊപ്പം കളിച്ചുകൊണ്ട്, മഴവില്ലുവഹിക്കുന്ന മേഘങ്ങളോടൊപ്പം ആകാശത്ത് കളിക്കുന്ന മഹാവായുപോലെ ആ വീരൻ തിളങ്ങി.",
        "0.10": "ആ മഹാസൈന്യത്തെ ഭയപ്പെടുത്തുന്ന ഭയങ്കര ഗർജ്ജനം മുഴക്കി, ബലശാലിയായ ഹനുമാൻ ആ രാക്ഷസന്മാർക്കുനേരെ വേഗത്തിൽ പാഞ്ഞു.",
        "0.11": "ശത്രുക്കളെ അമർത്തുന്ന അദ്ദേഹം ചിലരെ കൈപ്പത്തികൊണ്ടും ചിലരെ കാലുകൊണ്ടും പ്രഹരിച്ചു; ചിലരെ മുഷ്ടികൊണ്ട് അടിച്ചു, ചിലരെ നഖംകൊണ്ട് കീറി.",
        "0.12": "ചിലരെ നെഞ്ചുകൊണ്ട് ഞെരിച്ചു, മറ്റു ചിലരെ തുടകൊണ്ട്; ചിലർ അദ്ദേഹത്തിന്റെ ഗർജ്ജനംകേട്ട് അവിടെത്തന്നെ നിലത്തുവീണു.",
        "0.13": "അവർ നിലത്ത് മരിച്ചുവീണപ്പോൾ, ഭയന്നുപോയ അവരുടെ മുഴുവൻ സൈന്യം പത്തു ദിക്കുകളിലേക്കും ഓടിപ്പോയി.",
        "0.14": "ആനകൾ അസ്വാരസ്യമായി ചിന്നം വിളിച്ചു, കുതിരകൾ നിലത്തുവീണു; ഇരിപ്പിടങ്ങളും കൊടികളും കുടകളും തകർന്ന രഥങ്ങൾകൊണ്ട് ഭൂമി നിറഞ്ഞു.",
        "0.15": "വഴിയിലൂടെ രക്തപ്രവാഹം ഒഴുകുന്നത് കണ്ടു; പലതരം നിലവിളികൾകൊണ്ട് ലങ്ക ഭയങ്കരമായി മുഴങ്ങി.",
        "0.16": "അഹങ്കാരികളായ ആ രാക്ഷസന്മാരെ വധിച്ച ശേഷം, മറ്റു രാക്ഷസന്മാരോട് യുദ്ധം ചെയ്യാൻ ആഗ്രഹിച്ച ഭയങ്കര വീര്യമുള്ള മഹാവാനരൻ, അതേ ഗോപുരവാതിലിലേക്ക് തിരിച്ചുപോയി.",
        "0.17": "ഇങ്ങനെ ആദികാവ്യമായ, ശ്രീമദ് രാമായണത്തിലെ വാല്മീകി രചിച്ച സുന്ദരകാണ്ഡത്തിലെ നാല്പത്തഞ്ചാം സർഗ്ഗം സമാപിച്ചു."
      },
      "summary": "രാക്ഷസരാജാവ് മന്ത്രിമാരുടെ ഏഴു പുത്രന്മാരെ സൈന്യങ്ങളോടൊപ്പം അയയ്ക്കുന്നു. ഹനുമാൻ അവരെയെല്ലാം വധിക്കുന്നു; ചിലരെ കൈപ്പത്തികൊണ്ടും മുഷ്ടികൊണ്ടും, ചിലരെ കാലുകൊണ്ടും ഗർജ്ജനംകൊണ്ടും."
    },
    "sundarakanda-46": {
      "verses": {
        "0.0": "മഹാത്മാവായ വാനരൻ മന്ത്രിപുത്രന്മാരെ വധിച്ചു എന്നറിഞ്ഞ രാവണൻ, തന്റെ വികാരങ്ങൾ മറച്ചുവെച്ച് വിവേകപൂർവ്വമായ ഒരു തീരുമാനമെടുത്തു.",
        "0.1": "വിരൂപാക്ഷൻ, യൂപാക്ഷൻ, രാക്ഷസനായ ദുർധരൻ, പ്രഘസൻ, ഭാസകർണൻ — സൈന്യത്തിലെ ഈ അഞ്ചു സേനാനായകന്മാർ,",
        "0.2": "തന്ത്രത്തിൽ വിദഗ്ധരും ഹനുമാനെ പിടികൂടുന്നതിൽ ശാന്തചിത്തരും യുദ്ധത്തിൽ കാറ്റുപോലെ വേഗമുള്ളവരുമായ അവരോട് പത്തുതലയുള്ള രാവണൻ കല്പിച്ചു:",
        "0.3": "\"സേനാനായകന്മാരേ, നിങ്ങൾ എല്ലാവരും വലിയ സൈന്യവുമായി, കുതിരകളോടും രഥങ്ങളോടും ആനകളോടുംകൂടി പോകൂ; ആ വാനരനെ ശിക്ഷിക്കൂ.\"",
        "0.4": "\"ആ വനവാസിയുടെ അടുത്തെത്തുമ്പോൾ നിങ്ങൾ ജാഗ്രത പാലിക്കണം; സ്ഥലത്തിനും സമയത്തിനും യോജിച്ച വിധത്തിൽ പ്രവർത്തിക്കണം.\"",
        "0.5": "\"അവന്റെ പ്രവൃത്തികൾ കണ്ടാൽ, അവൻ ഒരു സാധാരണ വാനരനാണെന്ന് ഞാൻ കരുതുന്നില്ല; എല്ലാ വിധത്തിലും അളവറ്റ ശക്തിയുള്ള ഏതോ മഹാജീവിയാണവൻ.\"",
        "0.6": "\"'ഇതൊരു വാനരനാണ്' എന്ന് ചിന്തിച്ചാൽ എന്റെ മനസ്സിന് സമാധാനമില്ല; സംഭവിച്ചതനുസരിച്ച് അവൻ വാനരനാണെന്ന് ഞാൻ കരുതുന്നില്ല.\"",
        "0.7": "\"ഒരുപക്ഷേ നമ്മെ നേരിടാൻ തപസ്സിന്റെ ശക്തിയാൽ ഇന്ദ്രൻ അവനെ സൃഷ്ടിച്ചതാവാം. നാഗന്മാരും യക്ഷന്മാരും ഗന്ധർവന്മാരും ദേവന്മാരും അസുരന്മാരും മഹർഷിമാരും,",
        "0.8": "\"എന്നോടൊപ്പം അയച്ച നിങ്ങളാൽ എല്ലാവരും കീഴടക്കപ്പെട്ടിട്ടുണ്ട്; തീർച്ചയായും അവർ നമുക്ക് എന്തെങ്കിലും ദോഷം വരുത്താൻ ശ്രമിക്കും.\"",
        "0.9": "\"അതുകൊണ്ട് സംശയമില്ലാതെ, ബലമായി അവനെ പിടികൂടട്ടെ. പോകൂ, നിങ്ങൾ എല്ലാ സേനാനായകന്മാരും വലിയ സൈന്യവുമായി,",
        "0.10": "\"കുതിരകളോടും രഥങ്ങളോടും ആനകളോടുംകൂടി, ആ വാനരനെ ശിക്ഷിക്കൂ. ഉറച്ച വീര്യമുള്ള ആ വാനരനെ ലഘുവായി കാണരുത്.\"",
        "0.11": "\"മുൻപ് മഹാവീര്യമുള്ള വാനരന്മാരെ ഞാൻ കണ്ടിട്ടുണ്ട് — വാലിയെയും സുഗ്രീവനെയും മഹാബലശാലിയായ ജാംബവാനെയും.",
        "0.12": "\"സേനാപതിയായ നീലനെയും, ദ്വിവിദനെപ്പോലുള്ള മറ്റുള്ളവരെയും; എന്നാൽ അവരിൽ ആർക്കും ഇത്രയും ഭയങ്കരമായ വേഗമോ, ഇത്ര തേജസ്സോ, ഇത്ര വീര്യമോ ഇല്ല;",
        "0.13": "\"ഇത്ര ബുദ്ധിയോ, ബലമോ, ഊർജ്ജമോ, ഇത്രയും രൂപമാറ്റ ശക്തിയോ ഇല്ല. ഒരു വാനരരൂപത്തിൽ ഇവിടെ നിൽക്കുന്ന ഏതോ മഹാജീവിയാണിതെന്ന് അറിയുക.\"",
        "0.14": "\"വലിയ പരിശ്രമം ചെയ്ത് അവനെ കീഴടക്കൂ. സത്യമാണ്, ഇന്ദ്രനും ദേവന്മാരും അസുരന്മാരും മനുഷ്യരുമടങ്ങുന്ന മൂന്നു ലോകങ്ങളും,",
        "0.15": "\"യുദ്ധക്കളത്തിൽ നിങ്ങളുടെ മുന്നിൽ നിൽക്കാൻ മതിയാകില്ല; എങ്കിലും തന്ത്രമറിയുന്നവനും യുദ്ധത്തിൽ വിജയം ആഗ്രഹിക്കുന്നവനും,",
        "0.16": "\"യുദ്ധത്തിലെ വിജയം ചഞ്ചലമാകയാൽ, ശ്രദ്ധയോടെ സ്വയം സംരക്ഷിക്കണം.\" യജമാനന്റെ കല്പന സ്വീകരിച്ച ആ വീരന്മാരെല്ലാം,",
        "0.17": "തീപോലെ ജ്വലിച്ച്, രഥങ്ങളോടും മദിച്ച ആനകളോടും വളരെ വേഗമുള്ള കുതിരകളോടുംകൂടി വലിയ വേഗത്തിൽ പുറപ്പെട്ടു.",
        "0.18": "പലതരം മൂർച്ചയുള്ള ആയുധങ്ങളോടും തങ്ങളുടെ മുഴുവൻ സൈന്യത്തോടുംകൂടി. അപ്പോൾ ആ വീരന്മാർ ജ്വലിക്കുന്ന മഹാവാനരനെ കണ്ടു;",
        "0.19": "ഉദിക്കുന്ന സൂര്യനെപ്പോലെ, സ്വന്തം തേജസ്സിന്റെ രശ്മികൾകൊണ്ട് മാലയണിഞ്ഞ്, ഗോപുരവാതിലിൽ നിൽക്കുന്നവനെ — മഹാവേഗമുള്ളവനും മഹാമനസ്കനും മഹാബലശാലിയുമായവനെ.",
        "0.20": "മഹാബുദ്ധിയും മഹാഊർജ്ജവുമുള്ള, വലിയ ശരീരവും ബലമുള്ള ബാഹുക്കളുമുള്ളവനെ. അവനെ കണ്ടപ്പോൾ, എല്ലാ ദിശകളിലും നിലയുറപ്പിച്ച അവരെല്ലാം,",
        "0.21": "പലതരം ഭയങ്കര ആയുധങ്ങളോടെ എല്ലാ ഭാഗത്തുനിന്നും അവന്റെ നേരെ പാഞ്ഞു. ദുർധരൻ താമരദളംപോലെ വെള്ളനിറവും മഞ്ഞ അറ്റവുമുള്ള അഞ്ച് മൂർച്ചയുള്ള ഇരുമ്പുബാണങ്ങൾ അവന്റെ തലയിലേക്ക് എയ്തു.",
        "0.22": "ആ അഞ്ചു ബാണങ്ങളാൽ തലയിൽ തുളയ്ക്കപ്പെട്ട വാനരൻ, ഗർജ്ജിച്ച്, പത്തു ദിക്കുകളും പ്രതിധ്വനിപ്പിച്ച്, ആകാശത്തേക്ക് കുതിച്ചുയർന്നു.",
        "0.23": "അപ്പോൾ വില്ല് വലിച്ചുകെട്ടിയ തന്റെ രഥത്തിൽ, വീരനായ ദുർധരൻ നൂറുകണക്കിന് അമ്പുകൾ വർഷിച്ച് അവന്റെ നേർക്ക് വന്നു.",
        "0.24": "മഴക്കാലത്തിന്റെ അവസാനം മഴമേഘത്തെ കാറ്റ് തടയുന്നതുപോലെ, ആകാശത്ത് അമ്പുമഴ പെയ്യിച്ച ആ വില്ലാളിയെ വാനരൻ തടഞ്ഞു.",
        "0.25": "ദുർധരൻ ഉപദ്രവിച്ചതിനാൽ, വായുപുത്രനായ ആ ബലശാലി വീണ്ടും ഗർജ്ജിച്ച് വലുതായി വളർന്നു.",
        "0.26": "ദൂരെനിന്ന് പെട്ടെന്ന് ചാടി, അതിവേഗമുള്ള വാനരൻ മലയിൽ പതിക്കുന്ന മിന്നൽക്കൂട്ടംപോലെ ദുർധരന്റെ രഥത്തിൽ വന്നുവീണു.",
        "0.27": "അപ്പോൾ എട്ടു കുതിരകൾ ചതഞ്ഞരഞ്ഞ്, രഥത്തിന്റെ അച്ചുതണ്ടും ദണ്ഡും തകർന്ന ദുർധരൻ, രഥം ഉപേക്ഷിച്ച് പ്രാണൻ പോയ നിലയിൽ നിലത്തുവീണു.",
        "0.28": "നിലത്തുവീണ അവനെ കണ്ട്, ശത്രുക്കളെ അടക്കുന്നവരായ വിരൂപാക്ഷനും യൂപാക്ഷനും കോപത്തോടെ ചാടിയെഴുന്നേറ്റു.",
        "0.29": "പെട്ടെന്ന് ഉയർന്നുചാടി, ഇരുവരും തെളിഞ്ഞ ആകാശത്ത് നിന്ന ബലശാലിയായ വാനരന്റെ നെഞ്ചിൽ ഗദകൾകൊണ്ട് അടിച്ചു.",
        "0.30": "ആ രണ്ടു വേഗമേറിയവരുടെ ആക്രമണം തടഞ്ഞ്, ബലശാലി ഗരുഡനെപ്പോലെ വേഗത്തിൽ വീണ്ടും നിലത്തേക്ക് ഇറങ്ങി.",
        "0.31": "ഒരു സാലവൃക്ഷത്തിലെത്തി അത് പിഴുതെടുത്ത്, വായുപുത്രനായ വാനരൻ ആ രണ്ടു വീരരായ രാക്ഷസന്മാരെയും വധിച്ചു.",
        "0.32": "അപ്പോൾ വേഗമുള്ള വാനരൻ ആ മൂന്നുപേരെയും വധിച്ചതറിഞ്ഞ്, മഹാവേഗമുള്ള ശക്തനായ പ്രഘസൻ പരിഹാസത്തോടെ അവന്റെ നേർക്ക് വന്നു.",
        "0.33": "കോപിച്ച മഹാബലശാലിയായ ഭാസകർണനും ഒരു കുന്തമെടുത്തു; വാനരശ്രേഷ്ഠനായ ആ മഹാവീരന് നേരെ അവർ രണ്ടുപേരും ഒരുമിച്ച് നിന്നു.",
        "0.34": "പ്രഘസൻ വാനരശ്രേഷ്ഠനെ മൂർച്ചയുള്ള ഒരു ആയുധമായ കുന്തം-കോടാലികൊണ്ടും, രാക്ഷസനായ ഭാസകർണൻ തന്റെ കുന്തംകൊണ്ടും പ്രഹരിച്ചു.",
        "0.35": "അവരുടെ ആയുധങ്ങളാൽ അവയവങ്ങൾ മുറിവേറ്റ്, മുടി രക്തംകൊണ്ട് പുരണ്ട വാനരൻ കോപിച്ചു; ഉദിച്ചുയരുന്ന സൂര്യനെപ്പോലെ ജ്വലിച്ചു.",
        "0.36": "മൃഗങ്ങളും പാമ്പുകളും മരങ്ങളുമടങ്ങിയ ഒരു പർവതശിഖരം പിഴുതെടുത്ത്, വീരനായ ഹനുമാൻ, വാനരശ്രേഷ്ഠൻ, ആ രണ്ടു രാക്ഷസന്മാരെയും പ്രഹരിച്ചു; ആ ശിഖരത്താൽ ഞെരിഞ്ഞ് അവർ പൊടിപൊടിയായി.",
        "0.37": "ആ അഞ്ചു സേനാനായകന്മാർ നശിച്ചശേഷം, വാനരൻ അവരുടെ സൈന്യത്തിൽ ശേഷിച്ചവരെ നശിപ്പിച്ചു.",
        "0.38": "കുതിരകളെ കുതിരകൾകൊണ്ടും, ആനകളെ ആനകൾകൊണ്ടും, യോദ്ധാക്കളെ യോദ്ധാക്കൾകൊണ്ടും, രഥങ്ങളെ രഥങ്ങൾകൊണ്ടും — ആയിരം കണ്ണുള്ള ഇന്ദ്രൻ അസുരന്മാരെ നശിപ്പിച്ചതുപോലെ വാനരൻ അവയെയെല്ലാം നശിപ്പിച്ചു.",
        "0.39": "കൊല്ലപ്പെട്ട കുതിരകളും ആനകളും ചാട്ടക്കുതിരകളും, അച്ചുതണ്ട് തകർന്ന വലിയ രഥങ്ങളും മരിച്ച രാക്ഷസന്മാരും കൊണ്ട് ചുറ്റുമുള്ള വഴികൾ തടസ്സപ്പെട്ടു.",
        "0.40": "സേനാനായകന്മാരെയും അവരുടെ സൈന്യങ്ങളെയും വാഹനങ്ങളെയും യുദ്ധത്തിൽ വധിച്ച ശേഷം, വീരനായ വാനരൻ ഒരിക്കൽക്കൂടി ഗോപുരവാതിലിൽ സ്ഥാനമുറപ്പിച്ചു; സൃഷ്ടികളുടെ സംഹാരസമയത്തെ കാലംപോലെ തന്റെ അവസരം കാത്തുകൊണ്ട്.",
        "0.41": "ഇങ്ങനെ ആദികാവ്യമായ, ശ്രീമദ് രാമായണത്തിലെ വാല്മീകി രചിച്ച സുന്ദരകാണ്ഡത്തിലെ നാല്പത്താറാം സർഗ്ഗം സമാപിച്ചു."
      },
      "summary": "മഹാത്മാവായ വാനരൻ മന്ത്രിപുത്രന്മാരെ വധിച്ചത് അറിഞ്ഞ രാവണൻ, മനോവികാരം മറച്ചുവെച്ച് ബുദ്ധിപൂർവ്വമായ തീരുമാനമെടുക്കുന്നു. പ്രധാന സേനാപതികളായ അഞ്ചുപേരെ അയയ്ക്കുന്നു; ഇത് സാധാരണ വാനരനല്ലെന്ന് അവരോട് മുന്നറിയിപ്പ് നൽകുന്നു. ഹനുമാൻ അഞ്ചുപേരെയും അവരുടെ സൈന്യങ്ങളെയും വധിക്കുന്നു."
    },
    "sundarakanda-47": {
      "verses": {
        "0.0": "അഞ്ചു സേനാനായകന്മാരും അവരുടെ അനുചരന്മാരോടും വാഹനങ്ങളോടുംകൂടി ഹനുമാനാൽ കൊല്ലപ്പെട്ടു എന്ന് കേട്ട രാജാവ്, യുദ്ധത്തിന് ഉത്സാഹത്തോടെ മുന്നിൽ നിൽക്കുന്ന അക്ഷകുമാരനെ നോക്കി.",
        "0.1": "ആ നോട്ടത്താൽ പ്രേരിതനായ വീരനായ രാജകുമാരൻ, സ്വർണ്ണംകൊണ്ട് പണിത വില്ലുമായി, മുഖ്യബ്രാഹ്മണർ ഹവിസ്സ് അർപ്പിച്ച് ജ്വലിപ്പിച്ച യജ്ഞാഗ്നിപോലെ ഉയർന്നെഴുന്നേറ്റു.",
        "0.2": "പിന്നെ ആ വീരനായ രാക്ഷസശ്രേഷ്ഠൻ, പ്രഭാതസൂര്യനെപ്പോലെ പ്രകാശിക്കുന്ന, മിനുക്കിയ സ്വർണ്ണവലകൊണ്ട് മൂടിയ ഒരു മഹാരഥത്തിൽ കയറി ആ വലിയ വാനരനെതിരെ പോയി.",
        "0.3": "ആ രഥം സഞ്ചിതമായ തപസ്സിന്റെ ഫലമായി നേടിയതായിരുന്നു; മിനുക്കിയ സ്വർണ്ണവലയാൽ അലങ്കരിച്ചതും, പതാകകളും രത്നം പതിച്ച കൊടിമരവുമുള്ളതും, ചിന്തപോലെ വേഗമുള്ള എട്ടു മികച്ച കുതിരകൾ നന്നായി പൂട്ടിയതുമായിരുന്നു.",
        "0.4": "ദേവന്മാർക്കും അസുരന്മാർക്കും തോൽപ്പിക്കാനാകാത്തതും തടസ്സമില്ലാതെ നീങ്ങുന്നതും മിന്നൽപോലെ തിളങ്ങുന്നതും ആകാശത്തിലൂടെ സഞ്ചരിക്കാൻ കഴിയുന്നതും, ആവനാഴികളും, ഘടിപ്പിച്ച എട്ടു വാളുകളും, കുന്തങ്ങളും ഈട്ടികളും അവയുടെ സ്ഥാനങ്ങളിൽ വെച്ചതുമായ,",
        "0.5": "എല്ലാ ഉപകരണങ്ങളോടും പൂർണ്ണമായി തിളങ്ങുന്നതും, സ്വർണ്ണമാലകളാൽ അലങ്കരിച്ചതും, ചന്ദ്രസൂര്യന്മാരെപ്പോലെ ശോഭിക്കുന്നതുമായ ആ സൂര്യതുല്യ രഥത്തിൽ കയറി, അമരന്മാർക്ക് തുല്യമായ വീര്യത്തോടെ അവൻ പുറപ്പെട്ടു.",
        "0.6": "കുതിരകളുടെയും ആനകളുടെയും വലിയ രഥങ്ങളുടെയും ആരവത്താൽ ആകാശവും ഭൂമിയും അവയുടെ പർവതങ്ങളോടെ നിറച്ച്, കൂട്ടിച്ചേർത്ത സൈന്യങ്ങളോടുകൂടി അവൻ ഗോപുരത്തിൽ ഇരിക്കുന്ന കഴിവുള്ള വാനരന്റെ അടുത്തെത്തി.",
        "0.7": "സൃഷ്ടികളെ സംഹരിക്കുന്ന യുഗാന്ത്യകാലാഗ്നിപോലെ നിന്ന ആ വാനരന്റെ അടുത്തെത്തിയ സിംഹനേത്രനായ അക്ഷകുമാരൻ, അതിശയിച്ചും ഇളകിയും അവനെ ആഴമായ ബഹുമാനത്തോടെ നോക്കി.",
        "0.8": "ആ മഹാത്മാവായ വാനരന്റെ വേഗത, ശത്രുക്കളോടുള്ള വീര്യം, സ്വന്തം ശക്തി എന്നിവ തൂക്കിനോക്കി, രാവണന്റെ മഹാബലശാലിയായ പുത്രൻ യുഗാന്ത്യസൂര്യനെപ്പോലെ ശക്തിയിൽ വർദ്ധിച്ചു.",
        "0.9": "യുദ്ധത്തിൽ നേരിടാൻ പ്രയാസമുള്ള ആ വീര്യം കണ്ട് കോപം ഇളകി, ഉറച്ചുനിന്ന്, മനസ്സ് സമാഹരിച്ച്, മൂന്നു മൂർച്ചയുള്ള അമ്പുകൊണ്ട് ഹനുമാനെ യുദ്ധത്തിന് വെല്ലുവിളിച്ചു.",
        "0.10": "പിന്നെ അക്ഷൻ വില്ലും കൈയിൽ അമ്പുകളും തയ്യാറാക്കി ആ വാനരനെ നോക്കി — അഹങ്കാരിയും തളരാത്തവനും ശത്രുക്കളെ തോൽപ്പിച്ചു ശീലിച്ചവനും ഉയർന്ന മനോബലമുള്ളവനുമായ അവനെ.",
        "0.11": "സ്വർണ്ണമാലയും കൈവളകളും മനോഹരമായ കമ്മലുകളും അണിഞ്ഞ്, വേഗമേറിയ വീര്യമുള്ള രാജകുമാരൻ വാനരനെ നേരിട്ടു; അവരുടെ പോര് സമാനതകളില്ലാത്തതും ദേവന്മാർക്കും അസുരന്മാർക്കും പോലും ഭയമുണ്ടാക്കുന്നതുമായിരുന്നു.",
        "0.12": "വാനരനും രാജകുമാരനും തമ്മിലുള്ള വീര്യപോരാട്ടത്തിൽ ഭൂമി നിലവിളിച്ചു, സൂര്യൻ ചൂടു നൽകാതായി, കാറ്റ് വീശിയില്ല, പർവതങ്ങൾ ഇളകി, ആകാശം ഗർജ്ജിച്ചു, സമുദ്രം ഇളകി മറിഞ്ഞു.",
        "0.13": "അപ്പോൾ ലക്ഷ്യംവെക്കലിലും തൊടുക്കലിലും വിട്ടയക്കലിലും നിപുണനായ ആ വീരൻ, വിഷസർപ്പങ്ങളെപ്പോലെ മൂന്നു നല്ല തലകളും സ്വർണ്ണച്ചിറകുമുള്ള അമ്പുകൾ വാനരന്റെ തലയ്ക്കുനേരെ എയ്തു.",
        "0.14": "ആ അമ്പുകൾ തലയിൽ ഒന്നിച്ച് തറച്ചപ്പോൾ, രക്തം ഒഴുകി, കണ്ണുകൾ ഉരുണ്ട് ചോരപുരണ്ടു; അദ്ദേഹം പുതുതായി ഉദിച്ച സൂര്യനെപ്പോലെ തിളങ്ങി — അമ്പുകൾ രശ്മികളായി, രശ്മിമാലയണിഞ്ഞ സൂര്യനെപ്പോലെ.",
        "0.15": "അപ്പോൾ വാനരരാജാവിന്റെ മന്ത്രിമാരിൽ ശ്രേഷ്ഠൻ, മഹാരാജാവിന്റെ പുത്രൻ തന്റെ ഉന്നതവും അത്ഭുതകരവുമായ ആയുധങ്ങളോടും വില്ലോടുംകൂടി യുദ്ധത്തിൽ നിൽക്കുന്നത് കണ്ട്, സന്തോഷിച്ച് പോരിനുള്ള ഉത്സാഹത്താൽ വീർത്തു.",
        "0.16": "മന്ദരപർവതത്തിലെ സൂര്യനെപ്പോലെ, കോപം വർദ്ധിച്ച്, ശക്തിയും വീര്യവും നിറഞ്ഞ്, സേനയോടും വാഹനങ്ങളോടുംകൂടി അക്ഷകുമാരനെ കണ്ണുകളുടെ അഗ്നിരശ്മികളാൽ ദഹിപ്പിക്കുന്നതുപോലെ അവൻ തോന്നി.",
        "0.17": "അപ്പോൾ വില്ല് മഴവില്ലും അമ്പുകൾ മഴയുമായ ആ രാക്ഷസമേഘം, പർവതശ്രേഷ്ഠനിൽ മേഘം മഴ പെയ്യിക്കുന്നതുപോലെ, പർവതസമാനനായ വാനരനാഥന്റെ നേരെ വേഗത്തിൽ അമ്പുമഴ പെയ്യിച്ചു.",
        "0.18": "അപ്പോൾ വാനരൻ, തേജസ്സും ബലവും ശക്തിയും അമ്പുകളും വർദ്ധിച്ച ഉഗ്രവീരനായ അക്ഷകുമാരനെ യുദ്ധത്തിൽ കണ്ട്, ഇടിമുഴക്കംപോലെ ശബ്ദത്തിൽ സന്തോഷത്താൽ ഗർജ്ജിച്ചു.",
        "0.19": "യൗവനത്തിലെ പരാക്രമത്തിൽ അഹങ്കരിച്ച്, കോപം വളർന്ന്, രക്തംപോലെ ചുവന്ന കണ്ണുകളോടെ, പുല്ലുമൂടിയ ഒരു വലിയ കിണറിനടുത്തെത്തുന്ന ആനയെപ്പോലെ, സമാനതയില്ലാത്ത ആ വാനരനെ യുദ്ധത്തിൽ അവൻ നേരിട്ടു.",
        "0.20": "അവൻ ബലമായി എയ്ത അമ്പുകളേറ്റ വാനരൻ ഇടിമുഴക്കംപോലെ ഗർജ്ജിച്ചു; കൈകളും തുടകളും വീശി ഭയങ്കര രൂപത്തിൽ, ആകാശം പിളർത്തിക്കൊണ്ട് വേഗത്തിൽ ചാടിയുയർന്നു.",
        "0.21": "ചാടിയുയർന്നപ്പോൾ, രാക്ഷസരിൽ ഉത്തമനും രഥയോദ്ധാക്കളിൽ ശ്രേഷ്ഠനുമായവൻ പർവതത്തിൽ ആലിപ്പഴം വർഷിക്കുന്ന മേഘംപോലെ അമ്പുകൾ വിതറി, തന്റെ രഥത്തിൽ അവനെ പിന്തുടർന്നു.",
        "0.22": "അവന്റെ അമ്പുകളെ ഒഴിഞ്ഞുമാറി, വീരനായ വാനരൻ കാറ്റിന്റെ വഴിയിലൂടെ നീങ്ങി, കാറ്റുപോലെ അമ്പുകൾക്കിടയിൽ കൂടി ഓടി; ചിന്തപോലെ വേഗവും യുദ്ധത്തിൽ ഭയങ്കരവുമായി.",
        "0.23": "വില്ലേന്തി, യുദ്ധത്തിന് ഉത്സാഹിച്ച്, നല്ല അമ്പുകൾകൊണ്ട് ആകാശം മൂടുന്ന അക്ഷനെ വായുപുത്രൻ ആദരവോടെ നോക്കി, ചിന്തയിലാണ്ടു.",
        "0.24": "അപ്പോൾ ആ മഹാത്മാവായ രാജകുമാരന്റെ അമ്പുകളേറ്റ് നെഞ്ച് തുളഞ്ഞ ബലശാലിയായ വാനരൻ ഗർജ്ജിച്ചു; ദൗത്യത്തിന്റെ പ്രത്യേക ആവശ്യങ്ങൾ നന്നായി അറിഞ്ഞ്, യുദ്ധത്തിൽ എന്ത് വീര്യം കാണിക്കണമെന്ന് ചിന്തിച്ചു:",
        "0.25": "\"ഉദിക്കുന്ന സൂര്യനെപ്പോലെ തിളങ്ങുന്ന ഈ ബലശാലി ബാലനെപ്പോലെയല്ല മഹാകർമ്മങ്ങൾ ചെയ്യുന്നത്; യുദ്ധകലകളിലെല്ലാം പ്രാവീണ്യമുള്ള ഇവനെ കൊല്ലാൻ എനിക്ക് ആഗ്രഹമില്ല.\"",
        "0.26": "\"ഇവൻ മഹാത്മാവും യുദ്ധത്തിൽ മഹാവീരനും ധീരനും വളരെ സഹനശക്തിയുള്ളവനുമാണ്; സംശയമില്ല, അവന്റെ പ്രവൃത്തികളുടെയും ഗുണങ്ങളുടെയും മികവിനാൽ നാഗന്മാരും യക്ഷന്മാരും മഹർഷിമാരും അവനെ ബഹുമാനിക്കുന്നു.\"",
        "0.27": "\"വീര്യവും ഉത്സാഹവും മനസ്സിൽ നിറഞ്ഞ്, എന്റെ നേർക്ക് നേരെ നേരിട്ട് അവൻ നിൽക്കുന്നു; ഈ വേഗമേറിയവന്റെ വീര്യം ദേവന്മാരുടെയും അസുരന്മാരുടെയും ഹൃദയം പോലും വിറപ്പിക്കാം.\"",
        "0.28": "\"അവനെ അവഗണിച്ചാൽ അവൻ എന്നെ തീർച്ചയായും കീഴടക്കും; യുദ്ധത്തിലെ അവന്റെ വീര്യം വളരുകയാണ്. ഇപ്പോൾ അവനെ കൊല്ലുന്നതാണ് ശരിയെന്ന് എനിക്ക് തോന്നുന്നു; പടരുന്ന തീയെ അവഗണിക്കാനാവില്ലല്ലോ.\"",
        "0.29": "ഇങ്ങനെ എതിരാളിയുടെ ശക്തി തൂക്കിനോക്കി, സ്വന്തം പ്രവർത്തനമാർഗ്ഗം തീരുമാനിച്ച ആ ബലശാലി തന്റെ വേഗം കൂട്ടി, അവനെ കൊല്ലാൻ ഉറച്ചു.",
        "0.30": "വായുപുത്രനായ ആ വീരൻ, കാറ്റിന്റെ വഴിയിൽവെച്ച്, ഭാരം വഹിക്കാനും തിരിയാനും കഴിവുള്ള, നന്നായി പരിശീലനം നേടിയ, വലിയ എട്ടു മികച്ച കുതിരകളെ കൈയടിയാൽ കൊന്നു.",
        "0.31": "പിന്നെ കൈയടിയേറ്റ് തകർന്ന ആ വലിയ രഥം, വാനരരാജാവിന്റെ മന്ത്രി അതിനെ തോൽപ്പിച്ചതിനാൽ, ഇരിപ്പിടം തകർന്നും ദണ്ഡ് മറിഞ്ഞും കുതിരകൾ ചത്തും, ആകാശത്തുനിന്ന് നിലത്തു വീണു.",
        "0.32": "രഥം ഉപേക്ഷിച്ച്, വില്ലും വാളുമായി ആ വീരൻ ആകാശത്തേക്ക് ഉയർന്നു; യോഗബലത്താൽ ശരീരം വിട്ട് മരുത്തുകളുടെ ലോകത്തേക്ക് ഉയരുന്ന ഭയങ്കരശക്തിയുള്ള മുനിയെപ്പോലെ.",
        "0.33": "അപ്പോൾ വായുവിന്റെ വേഗവും വീര്യവുമുള്ള വാനരൻ, ഗരുഡനും കാറ്റും സിദ്ധന്മാരും സഞ്ചരിക്കുന്ന ആകാശത്തിൽ അവൻ നീങ്ങുമ്പോൾ അടുത്തെത്തി, പടിപടിയായി അവന്റെ കാലുകളിൽ ഉറപ്പായി പിടിച്ചു.",
        "0.34": "ഗരുഡൻ, പക്ഷിരാജാവ്, ഒരു വലിയ സർപ്പത്തെ പിടിക്കുന്നതുപോലെ ആയിരം തവണ ചുഴറ്റി, പിതാവിന്റെ വീര്യത്തിന് തുല്യനായ വാനരശ്രേഷ്ഠൻ, ആ യുദ്ധത്തിൽ അവനെ ബലമായി നിലത്തടിച്ചു.",
        "0.35": "കൈകളും തുടകളും ഇടുപ്പും നെഞ്ചും തകർന്ന്, രക്തം ഒഴുകി, അസ്ഥികളും കണ്ണുകളും ഞെരിഞ്ഞ്, സന്ധികൾ പൊട്ടി, ഞരമ്പുകൾ ചിതറി, ആ രാക്ഷസൻ വായുപുത്രനാൽ കൊല്ലപ്പെട്ട് നിലത്ത് കിടന്നു.",
        "0.36": "അവനെ നിലത്തിടിച്ച് ആ മഹാവാനരൻ രാക്ഷസരാജാവിന് വലിയ ഭയം ജനിപ്പിച്ചു. രാജകുമാരൻ കൊല്ലപ്പെട്ടപ്പോൾ, ആകാശത്ത് സഞ്ചരിക്കുന്ന മഹർഷിമാരും യക്ഷന്മാരും നാഗന്മാരും അവിടെ കൂടിയിരുന്ന ഇന്ദ്രനോടൊപ്പമുള്ള ദേവന്മാരും ആഴമായ അദ്ഭുതത്തോടെ ആ വാനരനെ നോക്കി.",
        "0.37": "ഇന്ദ്രപുത്രനു തുല്യനും രക്തംപോലെ ചുവന്ന കണ്ണുകളുള്ളവനുമായ അക്ഷകുമാരനെ യുദ്ധത്തിൽ വധിച്ചശേഷം, സൃഷ്ടികളുടെ സംഹാരസമയത്തെ കാലംപോലെ തന്റെ അവസരം കാത്ത്, ആ വീരൻ അതേ ഗോപുരവാതിലിലേക്ക് മടങ്ങി.",
        "0.38": "ഇങ്ങനെ ആദികാവ്യമായ, ശ്രീമദ് രാമായണത്തിലെ വാല്മീകി രചിച്ച സുന്ദരകാണ്ഡത്തിലെ നാല്പത്തേഴാം സർഗ്ഗം സമാപിച്ചു."
      },
      "summary": "രാവണന്റെ യുവപുത്രനായ അക്ഷകുമാരൻ രഥത്തിൽ പുറപ്പെട്ട് ഹനുമാനോട് ഘോരയുദ്ധം ചെയ്യുന്നു. അവന്റെ വീര്യത്തെ അഭിനന്ദിച്ചെങ്കിലും അപകടം മനസ്സിലാക്കിയ ഹനുമാൻ അവന്റെ കാലുകളിൽ പിടിച്ച് നിലത്തടിച്ചു കൊല്ലുന്നു."
    },
    "sundarakanda-48": {
      "verses": {
        "0.0": "അക്ഷകുമാരനെ ഹനുമാൻ വധിച്ചപ്പോൾ, മഹാബലശാലിയായ രാക്ഷസരാജാവ് മനസ്സ് ഉറപ്പിച്ച്, കോപത്തോടെ ദേവതുല്യനായ ഇന്ദ്രജിത്തിനോട് കല്പിച്ചു:",
        "0.1": "\"നീ ദിവ്യായുധങ്ങൾ അറിയുന്നവനും യോദ്ധാക്കളിൽ മുൻനിരക്കാരനുമാണ്; ദേവന്മാർക്കും അസുരന്മാർക്കും പോലും ദുഃഖം വരുത്തുന്നവനാണ്; ഇന്ദ്രനോടൊപ്പമുള്ള ദേവന്മാർക്കിടയിൽ നിന്റെ പ്രവൃത്തികൾ കണ്ടിട്ടുണ്ട്; ബ്രഹ്മാവിനെ ആരാധിച്ച് നീ ആയുധങ്ങൾ നേടിയിട്ടുണ്ട്.\"",
        "0.2": "\"നിന്റെ ആയുധങ്ങളുടെ ശക്തിയെ നേരിട്ടാൽ, ദേവന്മാർക്കും മരുത്തുകൾക്കും, ദേവാധിപന്റെ സംരക്ഷണത്തിൽ നിന്നാൽപ്പോലും യുദ്ധത്തിൽ നിൽക്കാനാവില്ല.\"",
        "0.3": "\"മൂന്നു ലോകത്തും യുദ്ധത്തിൽ നിന്നാൽ നിന്നെക്കൊണ്ട് തളർന്നുപോകാത്തവനായി ആരുമില്ല. നിന്റെ കൈകളുടെ ശക്തിയാൽ കാക്കപ്പെട്ടവനും തപസ്സിനാൽ സംരക്ഷിക്കപ്പെട്ടവനും, സ്ഥലവും സമയവും മനസ്സിലാക്കുന്നവനും, വിവേചനശക്തിയിൽ ഏറ്റവും മികച്ചവനുമാണ് നീ.\"",
        "0.4": "\"യുദ്ധത്തിൽ നിനക്ക് അസാധ്യമായി ഒന്നുമില്ല; നന്നായി ചിന്തിച്ച ആലോചനയിൽ നിനക്ക് അപ്പുറമായി ഒന്നുമില്ല; നിന്റെ ആയുധങ്ങളുടെയും ശക്തിയുടെയും ശക്തി മൂന്നു ലോകത്തും അറിയാത്തവരായി ആരുമില്ല.\"",
        "0.5": "\"നിന്റെ തപോബലവും വീര്യവും യുദ്ധത്തിലെ ആയുധങ്ങളുടെ ശക്തിയും എനിക്ക് യോഗ്യമാണ്. യുദ്ധത്തിരക്കിൽ ഞാൻ നിന്നെ ആശ്രയിക്കുമ്പോൾ, ഫലത്തെക്കുറിച്ച് ഉറപ്പുള്ള, എന്റെ മനസ്സ് ആകുലതയിൽനിന്ന് മുക്തമാകുന്നു.\"",
        "0.6": "\"കിങ്കരന്മാരെല്ലാം കൊല്ലപ്പെട്ടു; രാക്ഷസനായ ജംബുമാലിയും, വീരന്മാരായ മന്ത്രിപുത്രന്മാരും, സേനയുടെ അഞ്ചു സേനാനായകന്മാരും —\"",
        "0.7": "\"കുതിരകളും ആനകളും രഥങ്ങളുമുള്ള സുസജ്ജമായ സൈന്യങ്ങളും; നിന്റെ പ്രിയസഹോദരൻ അക്ഷകുമാരനും കൊല്ലപ്പെട്ടു. എന്നാൽ ശത്രുക്കളെ തകർക്കുന്നവനേ, അവരിൽ എനിക്ക് വിശ്വാസമുണ്ടായിരുന്നില്ല; നിന്നിലുള്ളതുപോലെ അല്ല.\"",
        "0.8": "\"ഈ വലിയ സൈന്യം കൊല്ലപ്പെട്ടതും വാനരന്റെ ശക്തിയും വീര്യവും കണ്ടും, നിന്റെ സ്വന്തം ശക്തി തൂക്കിനോക്കിയും, നിന്റെ ശക്തിക്കൊത്ത വീര്യത്തോടെ പ്രവർത്തിക്കൂ.\"",
        "0.9": "\"സ്വന്തം ശക്തിയും ശത്രുവിന്റെ ശക്തിയും തൂക്കിനോക്കി, ശ്രേഷ്ഠയോദ്ധാവേ, നീ അവനെ നേരിട്ടശേഷം നമ്മുടെ സൈന്യങ്ങളുടെ നാശം നിലയ്ക്കുകയും ശത്രു അടക്കപ്പെടുകയും ചെയ്യുന്ന വിധത്തിൽ ആരംഭിക്കൂ.\"",
        "0.10": "\"വീരാ, കൂട്ടമായി സൈന്യങ്ങളെ അയച്ചിട്ട് കാര്യമില്ല; മഹാവജ്രായുധം ഏന്തിയിട്ടുപോലും കാര്യമില്ല; അവന്റെ വേഗം കാറ്റിന്റേതുപോലെയാണ് — അളക്കാനാവില്ല; അവൻ തീപോലെയാണ്, സാധാരണ മാർഗ്ഗങ്ങളാൽ കൊല്ലാനാവില്ല.\"",
        "0.11": "\"ഈ കാര്യം നന്നായി ആലോചിച്ച്, നിന്റെ ശക്തിക്ക് തുല്യമായ പ്രവൃത്തിക്കായി മനസ്സ് ശാന്തമാക്കി, നിന്റെ വില്ലിന്റെ ദിവ്യശക്തി ഓർത്ത്, പരാജയപ്പെടാത്ത ഒരു പ്രവൃത്തി ആരംഭിക്കൂ.\"",
        "0.12": "\"ജ്ഞാനികളിൽ ശ്രേഷ്ഠാ, നിന്നെ ഇതിലേക്ക് അയയ്ക്കുന്നത് എന്റെ സ്വന്തം ഇഷ്ടമല്ല; എന്നാൽ ഇതാണ് രാജധർമ്മത്തിന്റെയും യോദ്ധാവിന്റെ ചട്ടത്തിന്റെയും അഭിപ്രായമായി കരുതപ്പെടുന്നത്.\"",
        "0.13": "\"ശത്രുക്കളെ അമർത്തുന്നവനേ, യുദ്ധത്തിൽ പലതരം ആയുധങ്ങളിലുള്ള പ്രാവീണ്യം തീർച്ചയായും നേടണം; യുദ്ധത്തിലെ വിജയം ആഗ്രഹിക്കപ്പെടേണ്ടതുമാണ്.\"",
        "0.14": "പിതാവിന്റെ വാക്കുകൾ കേട്ട്, ദക്ഷപുത്രന്മാർക്കു തുല്യനായ വീരൻ, മനസ്സ് യുദ്ധത്തിൽ ഉറപ്പിച്ച്, ബഹുമാനത്തോടെ തന്റെ യജമാനനെ വലംവെച്ച് വേഗത്തിൽ നടന്നു.",
        "0.15": "പിന്നെ പ്രിയ കൂട്ടാളികളാൽ ബഹുമാനിക്കപ്പെട്ട്, യുദ്ധത്തിനുള്ള ഉത്സാഹത്താൽ ജ്വലിച്ച ഇന്ദ്രജിത്ത് പോരാട്ടത്തിനായി പുറപ്പെട്ടു.",
        "0.16": "വലിയ താമരക്കണ്ണുകളും മഹത്തായ തേജസ്സുമുള്ള, രാക്ഷസരാജാവിന്റെ മഹനീയപുത്രൻ, പൗർണ്ണമിയിലെ സമുദ്രംപോലെ പുറപ്പെട്ടു.",
        "0.17": "തടയാനാവാത്ത വേഗമുള്ള ഇന്ദ്രജിത്ത്, ഇന്ദ്രനെപ്പോലെ, പക്ഷിരാജാവിനെപ്പോലെ വേഗമുള്ള, മൂർച്ചയുള്ള പല്ലുകളുള്ള നാലു കടുവകൾ പൂട്ടിയ രഥത്തിൽ കയറി.",
        "0.18": "ആ രഥയോദ്ധാവ്, വില്ലാളികളിൽ ഉത്തമൻ, ആയുധവിദ്യയിൽ നിപുണൻ, ദിവ്യായുധങ്ങൾ അറിയുന്നവരിൽ മുൻനിരക്കാരൻ, ഹനുമാൻ നിന്നിരുന്നിടത്തേക്ക് വേഗത്തിൽ തെളിച്ചു.",
        "0.19": "രഥത്തിന്റെ ഇരമ്പലും വില്ലിന്റെ ടങ്കാരവും കേട്ട വീരനായ വാനരൻ കൂടുതൽ സന്തോഷിച്ചു.",
        "0.20": "വില്ലും മൂർച്ചയുള്ള അമ്പുകളും എടുത്ത്, യുദ്ധത്തിൽ വിദഗ്ധനായ ഇന്ദ്രജിത്ത് ഹനുമാന്റെ നേർക്ക് മുന്നേറി.",
        "0.21": "സന്തോഷത്തോടെ അമ്പുകളുമായി യുദ്ധത്തിന് പുറപ്പെട്ടപ്പോൾ, എല്ലാ ദിശകളും ഇരുണ്ടു; ഭയങ്കര മൃഗങ്ങൾ പലവിധത്തിൽ ഓരിയിട്ടു.",
        "0.22": "നാഗന്മാരും യക്ഷന്മാരും മഹർഷിമാരും ആകാശത്ത് സഞ്ചരിക്കുന്ന സിദ്ധന്മാരും അവിടെ ഒത്തുകൂടി; പക്ഷിക്കൂട്ടങ്ങൾ ആകാശം മറച്ച്, വലിയ ഉത്സാഹത്തോടെ ഉറക്കെ കരഞ്ഞു.",
        "0.23": "ഇന്ദ്രന്റെ കൊടിയുള്ള ആ രഥം വേഗത്തിൽ വരുന്നത് കണ്ട്, വേഗമേറിയ വാനരൻ വലിയ ഗർജ്ജനം മുഴക്കി വലുതായി വളർന്നു.",
        "0.24": "ദിവ്യരഥത്തിലിരുന്ന് അത്ഭുതവില്ലുമായി ഇന്ദ്രജിത്ത് മിന്നലിന്റെ പൊട്ടൽപോലെ ശബ്ദമുണ്ടാക്കി ആ വില്ലിന്റെ ഞാൺ വലിച്ചു.",
        "0.25": "അപ്പോൾ ഇരുവരും കണ്ടുമുട്ടി — ഇരുവരും അതിവേഗമുള്ളവരും ബലശാലികളും യുദ്ധത്തിൽ ഭയമില്ലാത്തവരും; വാനരനും രാക്ഷസരാജപുത്രനും, ശത്രുതയിൽ ഏർപ്പെട്ട ദേവാസുര നാഥന്മാരെപ്പോലെ.",
        "0.26": "വലുതായി വളർന്ന, അളക്കാനാവാത്ത ആ വാനരൻ, ആ വീരനായ മഹാരഥയോദ്ധാവിന്റെ അമ്പുപ്രവാഹം തടഞ്ഞു; ബഹുമാനിതനായ വില്ലാളി തന്റെ പിതാവിന്റെ വഴിയായ ആകാശത്തിലൂടെ സഞ്ചരിച്ചു.",
        "0.27": "പിന്നെ ശത്രുവീരന്മാരെ വധിക്കുന്ന ആ വീരൻ, സ്വർണ്ണപ്പണിയുള്ള ദണ്ഡുകളോടും നീണ്ടതും മൂർച്ചയുള്ളതും നന്നായി തൂവലുള്ളതുമായ അമ്പുകൾ തുടർച്ചയായി, ഇടിവാളുപോലെ വേഗത്തിൽ എയ്തു.",
        "0.28": "ആ രഥത്തിന്റെ ഇരമ്പലും, ചെണ്ട, നഗാര, ഡമരു എന്നിവയുടെ ശബ്ദവും, വില്ല് വലിക്കുന്ന ടങ്കാരവും കേട്ട്, വാനരൻ വീണ്ടും ചാടിയുയർന്നു.",
        "0.29": "മഹാവാനരൻ അമ്പുകൾക്കിടയിലൂടെ വേഗത്തിൽ നീങ്ങി, ആ കൃത്യലക്ഷ്യമുള്ള വില്ലാളിയുടെ ലക്ഷ്യം ഒഴിവാക്കി.",
        "0.30": "വീണ്ടും അമ്പുകളുടെ മുന്നിൽ കയറി; അപ്പോൾ വായുപുത്രനായ ഹനുമാൻ കൈകൾ നീട്ടി പറന്നുയർന്നു.",
        "0.31": "ഇരുവരും വേഗമുള്ളവരും യുദ്ധവിദ്യയിൽ നിപുണരുമായതിനാൽ, സർവ്വജീവികളുടെയും മനസ്സ് പിടിച്ചുനിർത്തുന്ന അതിമനോഹരമായ യുദ്ധം അവർ നടത്തി.",
        "0.32": "ഹനുമാനിൽ രാക്ഷസന് ഒരു പഴുതും കിട്ടിയില്ല; മഹാത്മാവിൽ വായുപുത്രനും കിട്ടിയില്ല; ദേവതുല്യ വീര്യമുള്ള ആ രണ്ടുപേരും ഏറ്റുമുട്ടി, പരസ്പരം അജയ്യരായി.",
        "0.33": "പിന്നെ ലക്ഷ്യം തെറ്റി, അവന്റെ പിഴയ്ക്കാത്ത അമ്പുകൾ വ്യർത്ഥമായി വീണപ്പോൾ, ഏകാഗ്രമായ മനസ്സോടെ ആ മഹാത്മാവ് ആഴമായ ചിന്തയിൽ മുഴുകി.",
        "0.34": "അപ്പോൾ വാനരൻ കൊല്ലപ്പെടില്ലെന്ന് കണ്ട രാക്ഷസരാജപുത്രൻ, വാനരവീരന്മാരുടെ ആ നേതാവിനെ എങ്ങനെ ബന്ധിക്കാമെന്ന് ചിന്തിച്ചു.",
        "0.35": "അപ്പോൾ മഹാപ്രഭാവനും ദിവ്യായുധങ്ങൾ അറിയുന്നവരിൽ മുൻനിരക്കാരനുമായ ആ വീരൻ, ആ വാനരശ്രേഷ്ഠന് നേരെ ബ്രഹ്മാവിന്റെ (പിതാമഹന്റെ) ആയുധം തൊടുത്തു.",
        "0.36": "അവനെ കൊല്ലാനാവില്ലെന്ന് അറിഞ്ഞ്, ആയുധരഹസ്യം അറിയുന്ന ഇന്ദ്രജിത്ത് ആ ആയുധംകൊണ്ട് വായുപുത്രനായ ബലശാലിയെ ബന്ധിച്ചു.",
        "0.37": "രാക്ഷസൻ ആ ആയുധത്താൽ ബന്ധിച്ചപ്പോൾ, വാനരൻ അനങ്ങാതെയായി നിലത്തുവീണു.",
        "0.38": "അപ്പോൾ ആ ആയുധത്താൽ ബന്ധിതനായെന്ന് മനസ്സിലാക്കി, ഭഗവാന്റെ ശക്തിയാൽ തന്റെ വേഗം നഷ്ടപ്പെട്ട ശ്രേഷ്ഠനായ വാനരൻ, പിതാമഹന്റെ തനിക്കുള്ള കൃപയെക്കുറിച്ച് ചിന്തിച്ചു.",
        "0.39": "അപ്പോൾ ഹനുമാൻ സ്വയംഭൂവിന്റെ മന്ത്രങ്ങളാൽ അഭിഷേകം ചെയ്യപ്പെട്ട ബ്രഹ്മാസ്ത്രത്തെയും, പിതാമഹനിൽനിന്ന് ലഭിച്ച വരത്തെയും ഓർത്തു.",
        "0.40": "\"ലോകഗുരുവിന്റെ ശക്തിയാൽ ഈ ബന്ധനത്തിൽനിന്ന് മോചിതനാകാൻ എനിക്ക് കഴിവില്ല. ഈ ആയുധബന്ധം ഇങ്ങനെ വിധിക്കപ്പെട്ടതാകയാൽ, ഞാൻ സ്വയംഭൂവിന് വഴങ്ങണം.\"",
        "0.41": "ആയുധത്തിന്റെ ശക്തിയും പിതാമഹന്റെ തനിക്കുള്ള കൃപയും തൂക്കി, സ്വയം മോചിതനാകാനുള്ള തന്റെ ശക്തിയെക്കുറിച്ച് ചിന്തിച്ച്, വാനരൻ പിതാമഹന്റെ കല്പന അനുസരിച്ചു.",
        "0.42": "\"ആയുധത്താൽ ബന്ധിതനായിരുന്നിട്ടും എനിക്ക് ഭയം തോന്നുന്നില്ല; ബ്രഹ്മാവും മഹേന്ദ്രനും വായുവുമാണ് എന്നെ സംരക്ഷിക്കുന്നത്.\"",
        "0.43": "\"രാക്ഷസന്മാർ എന്നെ പിടികൂടുന്നത് പോലും എനിക്ക് വലിയ നേട്ടമാണ് — രാക്ഷസരാജാവുമായി സംസാരിക്കാനുള്ള അവസരം. അതിനാൽ ശത്രുക്കൾ എന്നെ കൊണ്ടുപോകട്ടെ.\"",
        "0.44": "ലക്ഷ്യം ഉറപ്പിച്ച്, ചിന്തിച്ചു പ്രവർത്തിക്കുന്ന, ശത്രുവീരന്മാരെ വധിക്കുന്നവൻ അനങ്ങാതെ നിന്നു; തന്നെ വളഞ്ഞ ശത്രുക്കൾ പിടികൂടിയപ്പോൾ, അവർ അധിക്ഷേപിക്കവേ അവൻ ഗർജ്ജിച്ചു.",
        "0.45": "അനങ്ങാതെ നിൽക്കുന്ന ശത്രുക്കളെ അടക്കുന്നവനെ കണ്ട്, രാക്ഷസന്മാർ ചണനാരുകൊണ്ടുള്ള കയറുകളാലും മരവുരിയുടെ പിരിച്ച കീറുകളാലും അവനെ ബന്ധിച്ചു.",
        "0.46": "ശത്രുവിനാൽ ബന്ധിക്കപ്പെടുന്നത് അവൻ സ്വീകരിച്ചു; ആ വീരന്മാരുടെ അധിക്ഷേപം കേട്ട്, ഉറച്ച ലക്ഷ്യത്തോടെ: \"ഒരുപക്ഷേ രാക്ഷസരാജാവ് ജിജ്ഞാസയാൽ എന്നെ കാണാൻ തീരുമാനിച്ചേക്കാം.\"",
        "0.47": "ആ മരവുരിയാൽ ബന്ധിക്കപ്പെട്ടതിനാൽ, ബലശാലി ആയുധബന്ധത്തിൽനിന്ന് മോചിതനായി; ദിവ്യായുധത്തിന്റെ ബന്ധം മറ്റൊരു ബന്ധവും സഹിക്കുകയില്ലല്ലോ.",
        "0.48": "അപ്പോൾ മരവുരികൊണ്ട് ബന്ധിതനും ആയുധബന്ധത്തിൽനിന്ന് മോചിതനുമായ ആ വാനരശ്രേഷ്ഠനെ കണ്ട വീരനായ ഇന്ദ്രജിത്ത് ആകുലനായി: \"മറ്റൊന്നിനാൽ ബന്ധിക്കപ്പെട്ട അവൻ ആയുധബന്ധത്തിൽനിന്ന് മോചിതനായി.\"",
        "0.49": "\"അയ്യോ, വലിയ പ്രവൃത്തി വ്യർത്ഥമായിപ്പോയി! മന്ത്രങ്ങളുടെ പ്രവർത്തനം രാക്ഷസന്മാർ ആലോചിച്ചില്ല. ദിവ്യായുധം അഴിഞ്ഞാൽ മറ്റൊന്നും ഫലിക്കില്ല; നമ്മളെല്ലാവരും ഇപ്പോൾ അപകടത്തിലാണ്.\"",
        "0.50": "ആയുധബന്ധത്തിൽനിന്ന് മോചിതനായിട്ടും ഹനുമാൻ അത് വെളിപ്പെടുത്തിയില്ല; ആ ബന്ധനങ്ങളാൽ ഉരസലേറ്റിട്ടും രാക്ഷസന്മാർ വലിച്ചുകൊണ്ടുപോകാൻ അവൻ അനുവദിച്ചു.",
        "0.51": "മരണംപോലെ കഠിനമായ മുഷ്ടികളാൽ ക്രൂരരായ രാക്ഷസന്മാർ അടിച്ചു; ആ വാനരനെ രാക്ഷസരാജാവിന്റെ സന്നിധിയിലേക്ക് വലിച്ചിഴച്ചു.",
        "0.52": "അപ്പോൾ ആയുധബന്ധത്തിൽനിന്ന് മോചിതനായി, മരവുരിയുടെ ചരടുകളാൽ ബന്ധിതനായ ആ മഹാവാനര വീരനെ ഇന്ദ്രജിത്ത് അവിടെ രാജാവിന്റെയും സദസ്സിന്റെയും മുന്നിൽ അവതരിപ്പിച്ചു.",
        "0.53": "മദിച്ച ആനപോലെ ബന്ധിക്കപ്പെട്ട ആ വാനരശ്രേഷ്ഠനെ, രാക്ഷസന്മാർ രാക്ഷസരാജാവായ രാവണനെ അറിയിച്ചു.",
        "0.54": "\"ഇവൻ ആരാണ്? ആരുടേതാണ്? എവിടെനിന്നാണ്? എന്താണ് ഇവന്റെ ഉദ്ദേശ്യം? ആരാണ് ഇവനെ പിന്തുണയ്ക്കുന്നത്?\" — ഇങ്ങനെ അവനെ കണ്ടപ്പോൾ രാക്ഷസവീരന്മാർക്കിടയിൽ ചർച്ചകളുണ്ടായി.",
        "0.55": "\"കൊല്ലൂ!\", \"ചുട്ടുകളയൂ!\", \"തിന്നൂ!\" — അവിടെയുണ്ടായിരുന്ന മറ്റു രാക്ഷസന്മാർ കോപത്തോടെ പരസ്പരം പറഞ്ഞു.",
        "0.56": "വഴി വേഗത്തിൽ കടന്ന്, മഹാത്മാവായ അദ്ദേഹം രാക്ഷസരാജാവിന്റെ പാദത്തിൽ, രാജാവിന്റെ വൃദ്ധരായ പരിചാരകരെയും, അമൂല്യരത്നങ്ങളാൽ അലങ്കരിച്ച സദസ്സും കണ്ടു.",
        "0.57": "മഹാപ്രഭാവനായ രാവണൻ, വികൃതരൂപികളായ രാക്ഷസന്മാർ വാനരശ്രേഷ്ഠനെ ഇങ്ങോട്ടും അങ്ങോട്ടും വലിച്ചിഴയ്ക്കുന്നത് കണ്ടു.",
        "0.58": "വാനരശ്രേഷ്ഠൻ, തേജസ്സും ശക്തിയുമുള്ള, സൂര്യനെപ്പോലെ ജ്വലിക്കുന്ന രാക്ഷസരാജാവിനെ കണ്ടു.",
        "0.59": "പത്തുതലയുള്ള രാവണൻ, ഉരുണ്ട ചെമ്പുനിറമുള്ള കണ്ണുകളോടെ കോപത്താൽ വാനരനെ സൂക്ഷിച്ചുനോക്കി; പിന്നെ അവിടെ ഇരിക്കുന്ന, കുലത്തിലും സ്വഭാവത്തിലും ശ്രേഷ്ഠരായ പ്രധാന മന്ത്രിമാരോട് അവനെ കൈകാര്യം ചെയ്യാൻ കല്പിച്ചു.",
        "0.60": "അവർ ക്രമപ്രകാരം അവന്റെ ഉദ്ദേശ്യവും അതിന്റെ മൂലകാരണവും ചോദിച്ചപ്പോൾ, വാനരൻ പ്രഖ്യാപിച്ചു: \"വാനരരാജാവിന്റെ ദൂതനായാണ് ഞാൻ വന്നത്.\"",
        "0.61": "ഇങ്ങനെ ആദികാവ്യമായ, ശ്രീമദ് രാമായണത്തിലെ വാല്മീകി രചിച്ച സുന്ദരകാണ്ഡത്തിലെ നാല്പത്തെട്ടാം സർഗ്ഗം സമാപിച്ചു."
      },
      "summary": "അക്ഷകുമാരൻ കൊല്ലപ്പെട്ടപ്പോൾ, രാവണൻ ഇന്ദ്രജിത്തിനെ അയയ്ക്കുന്നു; ദീർഘയുദ്ധത്തിനുശേഷം ഇന്ദ്രജിത്ത് ഹനുമാനെ ബ്രഹ്മാസ്ത്രംകൊണ്ട് ബന്ധിക്കുന്നു. ബ്രഹ്മാസ്ത്രത്തെ ബഹുമാനിച്ച് ഹനുമാൻ വഴങ്ങുന്നു; അവനെ രാവണന്റെ മുന്നിലേക്ക് വലിച്ചിഴയ്ക്കുന്നു."
    },
    "sundarakanda-49": {
      "verses": {
        "0.0": "അപ്പോൾ ഭയങ്കര വീര്യമുള്ള ഹനുമാൻ, നടന്നതിൽ അത്ഭുതപ്പെട്ട്, കോപം നിറഞ്ഞ ചുവന്ന കണ്ണുകളോടെ രാക്ഷസരാജാവിനെ നോക്കി.",
        "0.1": "വിലമതിക്കാനാവാത്ത, തിളങ്ങുന്ന സ്വർണ്ണകിരീടം മുത്തുമാലകൾ തൂങ്ങിക്കിടന്ന് അവനെ അലങ്കരിച്ചു; അവൻ വലിയ പ്രഭയോടെ തിളങ്ങി;",
        "0.2": "ചിന്തകൊണ്ടുമാത്രം നിർമ്മിച്ചതുപോലെ വജ്രവും വിലയേറിയ രത്നങ്ങളും പതിച്ച അത്ഭുതസ്വർണ്ണാഭരണങ്ങളോടെ;",
        "0.3": "വിലയേറിയ പട്ടുവസ്ത്രം ധരിച്ച്, ചുവന്ന ചന്ദനം പൂശി, പലതരം അത്ഭുത ചിത്രപ്പണികളാൽ നന്നായി അഭിഷേകം ചെയ്യപ്പെട്ട്;",
        "0.4": "സുന്ദരവും എന്നാൽ ഭയങ്കരവുമായ ചുവന്ന കണ്ണുകളോടെ, മൂർച്ചയുള്ള തിളങ്ങുന്ന വലിയ കോമ്പല്ലുകളോടെയും തൂങ്ങുന്ന ചുണ്ടുകളോടെയും;",
        "0.5": "പലതരം സർപ്പങ്ങൾ ചുറ്റിയ, കൊടുമുടികളുള്ള മന്ദരപർവതംപോലെ പത്തു തലകളാൽ ശോഭിച്ച, മഹാബലശാലിയായ വീരൻ;",
        "0.6": "കണ്ണെഴുത്തിന്റെ കൂമ്പാരംപോലെ കറുത്തവനും, മാറിൽ തിളങ്ങുന്ന മാല അണിഞ്ഞവനും, പൂർണ്ണചന്ദ്രനെപ്പോലെ മുഖമുള്ളവനും, ഉദിക്കുന്ന സൂര്യനോടുകൂടിയ മേഘംപോലെയുള്ളവനും;",
        "0.7": "ഭുജങ്ങളിൽ കൈവളകൾ ചുറ്റി, നല്ല ചന്ദനം പൂശി, വളകൾകൊണ്ട് തിളങ്ങുന്ന, ഭയങ്കരമായ അഞ്ചുതലയുള്ള സർപ്പങ്ങളെപ്പോലെയുള്ള കൈകളോടെ;",
        "0.8": "സ്ഫടികത്തിൽ രത്നങ്ങൾ പതിച്ച, അത്ഭുതകരവും മഹത്തരവുമായ ഒരു സിംഹാസനത്തിൽ, മികച്ച വിരികളാൽ പൊതിഞ്ഞ ഇരിപ്പിടത്തിൽ സുഖമായി ഇരുന്ന്;",
        "0.9": "ചാമരം വീശുന്ന, ആഭരണങ്ങളാൽ മനോഹരമായി അലങ്കരിച്ച യുവതികളാൽ എല്ലാ ഭാഗത്തുനിന്നും അടുത്തുനിന്ന് സേവിക്കപ്പെട്ട്;",
        "0.10": "ദുർധരൻ, പ്രഹസ്തൻ, രാക്ഷസനായ മഹാപാർശ്വൻ, മന്ത്രിയായ നികുംഭൻ എന്നിവരോടൊപ്പം — രാജതന്ത്രത്തിന്റെ സാരം അറിയുന്ന ഉപദേശകർ —",
        "0.11": "സമീപമിരുന്ന ആ നാല് രാക്ഷസന്മാരോടൊപ്പം, തന്റെ ശക്തിയിൽ അഭിമാനിച്ച അവൻ, നാല് സമുദ്രങ്ങളാൽ ചുറ്റപ്പെട്ട ലോകംപോലെ തോന്നി.",
        "0.12": "കാര്യങ്ങളിൽ പ്രവീണരായ മന്ത്രിമാരും മറ്റു ശുഭചിന്തകരായ ഉപദേശകരും അവനെ ആശ്വസിപ്പിച്ചുകൊണ്ടിരുന്നു; ദേവന്മാരുടെ നാഥനെ ദേവന്മാർ ആശ്വസിപ്പിക്കുന്നതുപോലെ.",
        "0.13": "മേരുവിന്റെ കൊടുമുടിയിൽ വിശ്രമിക്കുന്ന മഴമേഘംപോലെ, അതിമഹത്തായ തേജസ്സുള്ള രാക്ഷസരാജാവിനെ ഹനുമാൻ കണ്ടു.",
        "0.14": "ഭയങ്കര ശക്തിയുള്ള ആ രാക്ഷസന്മാരാൽ ഉപദ്രവിക്കപ്പെട്ടിട്ടും, അവൻ രാക്ഷസരാജാവിനെ പൂർണ്ണമായ അത്ഭുതത്തോടെ നോക്കി.",
        "0.15": "തേജസ്സിൽ നിൽക്കുന്ന രാക്ഷസരാജാവിനെ കണ്ട്, അവന്റെ പ്രഭയിൽ മിഴിച്ചുപോയ ഹനുമാൻ മനസ്സിൽ ചിന്തിച്ചു:",
        "0.16": "\"എന്തൊരു സൗന്ദര്യം, എന്തൊരു ധൈര്യം, എന്തൊരു ബലം, എന്തൊരു പ്രഭ! ശുഭലക്ഷണങ്ങളെല്ലാം രാക്ഷസരാജാവിൽ എത്ര പൂർണ്ണമായി നിറഞ്ഞിരിക്കുന്നു!\"",
        "0.17": "\"അധർമ്മം അവനിൽ ഇത്രയധികം ശക്തമായിരുന്നില്ലെങ്കിൽ, ഈ രാക്ഷസരാജാവിന് ഇന്ദ്രനടക്കമുള്ള ദേവലോകത്തിന്റെയും സംരക്ഷകനാകാമായിരുന്നു.\"",
        "0.18": "\"ക്രൂരവും നിർദ്ദയവുമായ പ്രവൃത്തികളാൽ ലോകം അപലപിക്കുന്നതിനാൽ, ദാനവന്മാരോടൊപ്പം എല്ലാ ലോകങ്ങളും അവനെ ഭയപ്പെടുന്നു.\"",
        "0.19": "\"കോപിച്ചാൽ അവന് ലോകത്തെ ഒരൊറ്റ സമുദ്രമാക്കി മാറ്റാനാകും.\" അതിരില്ലാത്ത ശക്തിയുള്ള രാക്ഷസരാജാവിന്റെ ശക്തി കണ്ട്, ജ്ഞാനിയായ വാനരൻ പലവിധത്തിൽ ചിന്തിച്ചു.",
        "0.20": "ഇങ്ങനെ ആദികാവ്യമായ, ശ്രീമദ് രാമായണത്തിലെ വാല്മീകി രചിച്ച സുന്ദരകാണ്ഡത്തിലെ നാല്പത്തൊമ്പതാം സർഗ്ഗം സമാപിച്ചു."
      },
      "summary": "സദസ്സിൽ, സിംഹാസനത്തിൽ തേജസ്സോടെ ജ്വലിച്ചിരിക്കുന്ന രാവണനെ ഹനുമാൻ നോക്കുന്നു. ഇത്ര മഹത്വമുള്ളവന് അധർമ്മമില്ലായിരുന്നെങ്കിൽ ദേവന്മാരുടെയും സംരക്ഷകനാകാമായിരുന്നു എന്ന് അദ്ദേഹം അത്ഭുതപ്പെടുന്നു."
    },
    "sundarakanda-50": {
      "verses": {
        "0.0": "മുന്നിൽ നിൽക്കുന്ന തവിട്ടുനിറമുള്ള കണ്ണുകളുള്ള വാനരനെ നോക്കി, ലോകങ്ങളെ നിലവിളിപ്പിക്കുന്ന മഹാബാഹുവായ രാവണൻ വലിയ കോപം നിറഞ്ഞു.",
        "0.1": "ശങ്കയാൽ മനസ്സ് മുറിവേറ്റ അവൻ, തേജസ്സിൽ പൊതിഞ്ഞ ആ വാനരനാഥനെ നോക്കി അത്ഭുതപ്പെട്ടു: \"ഇത് അനുഗ്രഹീതനായ നന്ദി തന്നെയാണോ, ഇവിടെ നേരിട്ട് വന്നിരിക്കുന്നത്,",
        "0.2": "\"കൈലാസത്തിൽവെച്ച് ഞാൻ അവനെ പരിഹസിച്ചപ്പോൾ പണ്ട് എന്നെ ശപിച്ചവൻ? വാനരരൂപത്തിലുള്ളത് അവൻതന്നെയാണോ, അതോ അസുരനായ ബാണനോ?\"",
        "0.3": "കോപത്താൽ ചുവന്ന കണ്ണുകളോടെ രാജാവ് മന്ത്രിമാരിൽ ശ്രേഷ്ഠനായ പ്രഹസ്തനോട് സമയോചിതവും അർത്ഥഗർഭവുമായ ഈ വാക്കുകൾ പറഞ്ഞു:",
        "0.4": "\"ഈ ദുഷ്ടനോട് എവിടെനിന്നാണെന്നും എന്തിനാണെന്നും ചോദിക്കൂ; ഉദ്യാനം തകർക്കുന്നതിലും രാക്ഷസന്മാരെ ഭീഷണിപ്പെടുത്തുന്നതിലും അവന്റെ ഉദ്ദേശ്യമെന്തായിരുന്നു?\"",
        "0.5": "\"എന്റെ അജയ്യമായ നഗരത്തിൽ വരുന്നതിൽ അവന്റെ ലക്ഷ്യമെന്തായിരുന്നു; യുദ്ധം ചെയ്യുന്നതിൽ അവന്റെ ഉദ്ദേശ്യമെന്തായിരുന്നു? ആ ദുർബുദ്ധിയെ ചോദ്യം ചെയ്യൂ.\"",
        "0.6": "രാവണന്റെ വാക്കുകൾ കേട്ട പ്രഹസ്തൻ പറഞ്ഞു: \"ധൈര്യമായിരിക്കൂ, നിനക്ക് ശുഭമുണ്ടാകട്ടെ; വാനരാ, നിനക്ക് ഭയപ്പെടേണ്ടതില്ല.\"",
        "0.7": "\"ഇന്ദ്രൻ നിന്നെ രാവണന്റെ വാസസ്ഥലത്തേക്ക് അയച്ചതാണെങ്കിൽ സത്യം പറയൂ; വാനരാ, ഭയപ്പെടേണ്ട, നീ മോചിപ്പിക്കപ്പെടും.\"",
        "0.8": "\"അല്ലെങ്കിൽ നീ കുബേരന്റെയോ യമന്റെയോ വരുണന്റെയോ ആളാണെങ്കിൽ, ഈ മനോഹര രൂപത്തിൽ നമ്മുടെ നഗരത്തിൽ പ്രവേശിച്ചതാണെങ്കിൽ,\"",
        "0.9": "\"അല്ലെങ്കിൽ വിജയം ആഗ്രഹിക്കുന്ന വിഷ്ണു അയച്ച ദൂതനാണെങ്കിൽ — നിന്റെ ശക്തി വാനരന്റേതല്ല; രൂപം മാത്രമാണ് വാനരന്റേത്.\"",
        "0.10": "\"ഇപ്പോൾ സത്യം പറയൂ, വാനരാ, നീ മോചിപ്പിക്കപ്പെടും; എന്നാൽ നീ കള്ളം പറഞ്ഞാൽ നിന്റെ ജീവൻ രക്ഷിക്കാൻ പ്രയാസമാകും.\"",
        "0.11": "\"അല്ലെങ്കിൽ, രാവണന്റെ വാസസ്ഥലത്ത് നീ പ്രവേശിച്ചതിന്റെ കാരണം പറയൂ.\" ഇങ്ങനെ ചോദിക്കപ്പെട്ട വാനരശ്രേഷ്ഠൻ രാക്ഷസസൈന്യങ്ങളുടെ നാഥനോട് പറഞ്ഞു:",
        "0.12": "\"ഞാൻ ഇന്ദ്രന്റെയോ യമന്റെയോ വരുണന്റെയോ ആളല്ല; കുബേരനുമായി എനിക്ക് സൗഹൃദമില്ല; വിഷ്ണു എന്നെ അയച്ചതുമല്ല.\"",
        "0.13": "\"ഇതാണ് എന്റെ സ്വഭാവം: ഞാൻ ഒരു വാനരനാണ്, ഇവിടെ വന്നിരിക്കുന്നു. രാക്ഷസരാജാവിനെ കാണുക എനിക്ക് നേടാൻ പ്രയാസമായിരുന്നു;\"",
        "0.14": "\"അതിനാൽ അദ്ദേഹത്തെ കാണാനായി ഞാൻ രാക്ഷസരാജാവിന്റെ ഉദ്യാനം നശിപ്പിച്ചു. പിന്നെ ആ ശക്തരായ രാക്ഷസന്മാർ യുദ്ധത്തിനുള്ള ആവേശത്തോടെ വന്നു,\"",
        "0.15": "\"എന്റെ ശരീരം സംരക്ഷിക്കാൻ ഞാൻ അവരോട് തിരിച്ചടിച്ചു. ദേവന്മാർക്കും അസുരന്മാർക്കും പോലും ഏതൊരു ആയുധത്തിന്റെയും കുരുക്കിൽ എന്നെ ബന്ധിക്കാനാവില്ല;\"",
        "0.16": "\"ഈ വരവും എനിക്ക് പിതാമഹനിൽനിന്ന് ലഭിച്ചതാണ്. രാജാവിനെ കാണാനുള്ള ആഗ്രഹത്താൽ ഞാൻ ആയുധത്തിന് വഴങ്ങി.\"",
        "0.17": "\"ആയുധബന്ധത്തിൽനിന്ന് മോചിതനായെങ്കിലും, രാക്ഷസന്മാർ എന്നെ നിന്റെ മുന്നിൽ കൊണ്ടുവന്നു. രാമന്റെ ഒരു കാര്യത്തിനായാണ് ഞാൻ നിന്റെ അടുത്തെത്തിയത്.\"",
        "0.18": "\"അതിരില്ലാത്ത ശക്തിയുള്ള രാഘവന്റെ ദൂതനാണ് ഞാൻ എന്ന് അറിഞ്ഞ്, നിന്റെ നന്മയ്ക്കുള്ള എന്റെ ഈ വാക്കുകൾ കേൾക്കൂ, പ്രഭോ.\"",
        "0.19": "ഇങ്ങനെ ആദികാവ്യമായ, ശ്രീമദ് രാമായണത്തിലെ വാല്മീകി രചിച്ച സുന്ദരകാണ്ഡത്തിലെ അമ്പതാം സർഗ്ഗം സമാപിച്ചു."
      },
      "summary": "രാവണന്റെ കല്പനപ്രകാരം പ്രഹസ്തൻ ഹനുമാനോട് ആരാണ് അയച്ചതെന്നും എന്തിനാണ് ഉദ്യാനം തകർത്തതെന്നും ചോദിക്കുന്നു. താൻ വാനരനാണെന്നും രാമന്റെ ദൂതനാണെന്നും സ്വരക്ഷയ്ക്കായി മാത്രമാണ് പോരാടിയതെന്നും ഹനുമാൻ മറുപടി നൽകുന്നു."
    },
    "sundarakanda-51": {
      "verses": {
        "0.0": "ആ മഹാശക്തനെ നോക്കി, ധീരനായ വാനരശ്രേഷ്ഠൻ പത്തുതലയുള്ള രാവണനോട് ശാന്തമായി അർത്ഥഗർഭമായ വാക്കുകൾ പറഞ്ഞു:",
        "0.1": "\"സുഗ്രീവന്റെ സന്ദേശവുമായാണ് ഞാൻ ഇവിടെ നിന്റെ അടുത്തെത്തിയത്. രാക്ഷസരാജാവേ, നിന്റെ സഹോദരനായ വാനരരാജാവ് നിന്റെ ക്ഷേമം അന്വേഷിക്കുന്നു.",
        "0.2": "\"മഹാത്മാവായ നിന്റെ സഹോദരൻ സുഗ്രീവന്റെ ഉപദേശം കേൾക്കൂ — ഇഹത്തിലും പരത്തിലും ഗുണകരമായ, ധർമ്മത്തിനും അർത്ഥത്തിനും യോജിച്ച വാക്കുകൾ.",
        "0.3": "\"രഥങ്ങൾ, ആനകൾ, കുതിരകൾ എന്നിവയാൽ സമ്പന്നനായ ദശരഥൻ എന്നൊരു രാജാവുണ്ടായിരുന്നു; പിതാവിനെപ്പോലെ ലോകത്തിന് ബന്ധുവും, ദേവാധിപന്റെ തുല്യതേജസ്സുള്ളവനുമായിരുന്നു.",
        "0.4": "\"ബലമുള്ള ബാഹുക്കളുള്ള, ഏറെ പ്രിയനായ അദ്ദേഹത്തിന്റെ മൂത്തപുത്രൻ, യഥാർത്ഥ പ്രഭു, പിതാവിന്റെ കല്പനപ്രകാരം ഭവനം വിട്ട് ദണ്ഡകാരണ്യത്തിൽ പ്രവേശിച്ചു.",
        "0.5": "\"സഹോദരൻ ലക്ഷ്മണനും ഭാര്യ സീതയുമായി — രാമൻ എന്ന പേരുള്ള, മഹാതേജസ്വി, ധർമ്മപഥം പാലിക്കുന്നവൻ.",
        "0.6": "\"സീത എന്ന പേരിൽ പ്രസിദ്ധയായ അവന്റെ ഭാര്യ, വിദേഹരാജാവായ മഹാത്മാവായ ജനകന്റെ പുത്രി, ജനസ്ഥാനത്തുവെച്ച് നഷ്ടപ്പെട്ടു.",
        "0.7": "\"ആ സ്ത്രീയെ അന്വേഷിച്ച് രാജകുമാരനും അനുജനും ഋശ്യമൂകത്തിൽ എത്തി, സുഗ്രീവനെ കണ്ടുമുട്ടി.",
        "0.8": "\"സീതയെ അന്വേഷിക്കാമെന്ന് സുഗ്രീവൻ വാഗ്ദാനം ചെയ്തു; വാനരരാജ്യം സുഗ്രീവന് നൽകാമെന്ന് രാമനും വാഗ്ദാനം ചെയ്തു.",
        "0.9": "\"പിന്നെ രാജകുമാരൻ യുദ്ധത്തിൽ വാലിയെ വധിച്ച്, സുഗ്രീവനെ വാനരന്മാരുടെയും കരടികളുടെയും സേനയുടെ നാഥനായി സിംഹാസനത്തിൽ ഇരുത്തി.",
        "0.10": "\"വാനരശ്രേഷ്ഠനായ വാലിയെ നിനക്ക് അറിയാമല്ലോ; ഒറ്റ അമ്പുകൊണ്ട് യുദ്ധത്തിൽ അവൻ ആ വാനരനെ വധിച്ചു.",
        "0.11": "\"സീതയെ തിരയാൻ ആഗ്രഹിച്ച്, വാക്കുപാലിക്കുന്ന വാനരരാജാവായ സുഗ്രീവൻ എല്ലാ ദിക്കുകളിലേക്കും വാനരന്മാരെ അയച്ചിരിക്കുന്നു.",
        "0.12": "\"ആയിരക്കണക്കിനും ലക്ഷക്കണക്കിനും കോടിക്കണക്കിനും വാനരന്മാർ എല്ലാ ദിക്കുകളിലും താഴെയും ആകാശത്തിന്റെ മുകളിലും അവളെ തിരയുന്നു.",
        "0.13": "\"ചിലർ ഗരുഡനു തുല്യർ, ചിലർ കാറ്റിനു തുല്യർ — വേഗവും തടസ്സമില്ലാത്ത ചലനവുമുള്ള മഹാബലശാലികളായ വാനരവീരന്മാർ.",
        "0.14": "\"ഹനുമാൻ എന്നാണ് എന്റെ പേര്; വായുദേവന്റെ യഥാർത്ഥ പുത്രനാണ് ഞാൻ. സീതയ്ക്കുവേണ്ടി നൂറു യോജന വീതിയുള്ള സമുദ്രം ഞാൻ വേഗത്തിൽ കടന്നു.",
        "0.15": "\"അത് ചാടിക്കടന്ന്, നിന്നെ കാണാനാഗ്രഹിച്ച് ഞാൻ ഇവിടെയെത്തി. അലഞ്ഞുനടക്കുമ്പോൾ നിന്റെ വീട്ടിൽ ജനകപുത്രിയെ ഞാൻ കണ്ടു.",
        "0.16": "\"നീ ധർമ്മവും അർത്ഥവും അറിയുന്നവനും തപസ്സിനാൽ വലിയ നേട്ടങ്ങൾ നേടിയവനുമാണ്; അതിനാൽ ജ്ഞാനിയേ, മറ്റൊരാളുടെ ഭാര്യയെ നീ കൈവശം വെക്കരുത്.",
        "0.17": "\"നിന്നെപ്പോലുള്ള ജ്ഞാനികൾ ധർമ്മത്തിന് വിരുദ്ധമായ, അപകടം നിറഞ്ഞ, വേരോടെ നാശം വരുത്തുന്ന പ്രവൃത്തികളിൽ മുറുകെ പിടിക്കാറില്ല.",
        "0.18": "\"ദേവന്മാരിലും അസുരന്മാരിലും ആരാണ് ലക്ഷ്മണൻ തൊടുക്കുന്ന അമ്പുകൾക്കും രാമന്റെ കോപം പിന്തുടരുന്ന അമ്പുകൾക്കും മുന്നിൽ നിൽക്കാനാവുക?",
        "0.19": "\"രാജാവേ, മൂന്നു ലോകത്തും രാഘവനോട് തെറ്റ് ചെയ്ത് സന്തോഷത്തോടെ കഴിയാൻ കഴിയുന്ന ആരുമില്ല.",
        "0.20": "\"അതുകൊണ്ട് ഭൂതത്തിനും വർത്തമാനത്തിനും ഭാവിക്കും ഗുണകരവും ധർമ്മത്തിനും ലാഭത്തിനും യോജിച്ചതുമായ ഈ വാക്കുകൾ സ്വീകരിക്കൂ: ജനകിയെ മനുഷ്യരാജാവിന് തിരികെ നൽകൂ.",
        "0.21": "\"ഈ സ്ത്രീയെ ഞാൻ കണ്ടു — ഇവിടെ നേടാൻ പ്രയാസമായിരുന്നത് ഞാൻ നേടി. ശേഷിക്കുന്ന കാര്യം രാഘവൻ നോക്കിക്കൊള്ളും.",
        "0.22": "\"ദുഃഖത്തിൽ മുങ്ങിയ സീതയെ ഞാൻ ഇവിടെ കണ്ടു — നിന്റെ വീട്ടിൽ പാർപ്പിച്ചിരിക്കുന്ന, അഞ്ചുതലയുള്ള പെൺസർപ്പമെന്ന് നീ തിരിച്ചറിയാത്തവൾ.",
        "0.23": "\"വിഷം കലർന്ന ഭക്ഷണം ശക്തികൊണ്ടുപോലും ദഹിക്കാത്തതുപോലെ, അവളെ ദേവന്മാർക്കും അസുരന്മാർക്കും ദഹിപ്പിക്കാനാവില്ല.",
        "0.24": "\"തപസ്സിന്റെ അഗ്നിയിലൂടെ നീ നേടിയ ഈ പുണ്യസഞ്ചയം — നിന്റെ ജീവന്റെതന്നെ സംരക്ഷണം — അത് നശിപ്പിക്കുന്നത് ശരിയല്ല.",
        "0.25": "\"തപസ്സിനാൽ ദേവന്മാരിൽനിന്നും അസുരന്മാരിൽനിന്നും നീ സ്വയം കണ്ട രക്ഷാകവചത്തിലും ഇവിടെ വലിയ ഒരു പിഴവുണ്ട്:",
        "0.26": "\"സുഗ്രീവൻ ദേവനോ യക്ഷനോ രാക്ഷസനോ അല്ല; രാഘവൻ മനുഷ്യനും, സുഗ്രീവൻ വാനരരാജാവുമാണ്. പിന്നെ എങ്ങനെയാണ് രാജാവേ, നീ നിന്റെ ജീവൻ രക്ഷിക്കുക?",
        "0.27": "\"നീ നേടിയ പുണ്യം ദുഷ്കർമ്മത്തിന്റെ ഫലത്തെ റദ്ദാക്കുന്നില്ല; ആ ഫലം തന്റെ ഊഴത്തിൽ വരും; ധർമ്മത്തിന് മാത്രമേ അധർമ്മത്തെ മായ്ക്കാനാവൂ.",
        "0.28": "\"നിന്റെ പുണ്യത്തിന്റെ ഫലം നീ ഇതിനകം അനുഭവിച്ചിട്ടുണ്ട്; ഈ അധർമ്മത്തിന്റെ ഫലവും ഉടൻ നീ അനുഭവിക്കും.",
        "0.29": "\"ജനസ്ഥാനത്തെ കൂട്ടക്കൊല, വാലിയുടെ വധം, രാമന്റെയും സുഗ്രീവന്റെയും സൗഹൃദം എന്നിവ അറിഞ്ഞ്, നിനക്ക് എന്താണ് നന്മ എന്ന് ആലോചിക്കൂ.",
        "0.30": "\"സത്യമായും കുതിരകളും രഥങ്ങളും ആനകളുമടങ്ങിയ ലങ്കയെ ഞാൻ ഒറ്റയ്ക്ക് നശിപ്പിക്കാൻ കഴിയുമായിരുന്നു; പക്ഷേ അത് അവന്റെ തീരുമാനമല്ല.",
        "0.31": "\"വാനരന്മാരുടെയും കരടികളുടെയും സേനകളുടെ സാന്നിധ്യത്തിൽ, സീതയോട് തെറ്റ് ചെയ്ത ശത്രുക്കളെ നശിപ്പിക്കുമെന്ന് രാമൻ പ്രതിജ്ഞ ചെയ്തിരിക്കുന്നു.",
        "0.32": "\"രാമനോട് തെറ്റ് ചെയ്താൽ ഇന്ദ്രൻ തന്നെയും സന്തോഷം കണ്ടെത്തില്ല; നിന്നെപ്പോലുള്ളവന്റെ കാര്യം പറയാനുണ്ടോ?",
        "0.33": "\"നീ സീത എന്ന് അറിയുന്ന, നിന്റെ വീട്ടിൽ നിൽക്കുന്ന അവളെ കാളരാത്രി എന്ന മരണരാത്രിയായി അറിയുക; ലങ്ക മുഴുവൻ നശിപ്പിക്കുന്നവൾ.",
        "0.34": "\"നിന്റെ സ്വന്തം തോളിൽ നീ തൂക്കിയിട്ട, സീതയുടെ രൂപത്തിലുള്ള മൃത്യുവിന്റെ കുരുക്ക് മതി; നിന്റെ സ്വന്തം സുരക്ഷയെക്കുറിച്ച് ചിന്തിക്കൂ.",
        "0.35": "\"ഗോപുരങ്ങളും തെരുവുകളുമുള്ള ഈ നഗരം കാണൂ; സീതയുടെ ശക്തിയാൽ ദഹിപ്പിക്കപ്പെട്ടും രാമന്റെ കോപത്താൽ ജ്വലിപ്പിക്കപ്പെട്ടും, ഇതാ കത്തിക്കൊണ്ടിരിക്കുന്നു!",
        "0.36": "\"നിന്റെ സുഹൃത്തുക്കളെയും മന്ത്രിമാരെയും ബന്ധുക്കളെയും സഹോദരന്മാരെയും പുത്രന്മാരെയും ഹിതൈഷികളെയും സുഖഭോഗങ്ങളെയും ഭാര്യമാരെയും ലങ്കയെത്തന്നെയും നശിപ്പിക്കരുത്.",
        "0.37": "\"രാക്ഷസരാജാക്കന്മാരുടെ രാജാവേ, എന്റെ വാക്കുകൾ കേൾക്കൂ; അവ സത്യമാണ് — ഒരു വാനരന്റെയും ദൂതന്റെയും, എല്ലാറ്റിനുമുപരി രാമന്റെ ദാസന്റെയും വാക്കുകൾ.",
        "0.38": "\"മഹത്തായ കീർത്തിയുള്ള രാമന് ചലിക്കുന്നതും ചലിക്കാത്തതുമായ ജീവികളടങ്ങിയ സകല ലോകങ്ങളെയും നശിപ്പിക്കാനും, പഴയതുപോലെ വീണ്ടും സൃഷ്ടിക്കാനും കഴിയും.",
        "0.39": "\"ദേവന്മാരിലും അസുരന്മാരിലും, മനുഷ്യരാജാക്കന്മാരിലും, യക്ഷന്മാരിലും രാക്ഷസന്മാരിലും, സർപ്പങ്ങളിലും, വിദ്യാധരന്മാരിലും, നാഗന്മാരിലും, ഗന്ധർവന്മാരിലും, മൃഗങ്ങളിലും —",
        "0.40": "\"സിദ്ധന്മാരിലും, കിന്നരനാഥന്മാരിലും, പക്ഷികളിലും — എവിടെയും, സകല ജീവികളിലും, ഏതു സമയത്തും — ആരുമില്ല,",
        "0.41": "\"വിഷ്ണുവിനു തുല്യമായ വീര്യമുള്ള രാമനോട് യുദ്ധം ചെയ്യാൻ കഴിയുന്നവൻ. രാജാക്കന്മാരിൽ സിംഹവും എല്ലാ ലോകങ്ങളുടെയും നാഥനുമായ രാമനോട് ഇങ്ങനെ തെറ്റ് ചെയ്തതിനാൽ നിന്റെ ജീവൻ നിലനിർത്താൻ പ്രയാസമാകും.",
        "0.42": "\"രാത്രിസഞ്ചാരികളുടെ നാഥാ, ദേവന്മാരും ദൈത്യന്മാരും ഗന്ധർവന്മാരും വിദ്യാധരന്മാരും നാഗന്മാരും യക്ഷന്മാരും — ആരും യുദ്ധത്തിൽ രാമന് മുന്നിൽ നിൽക്കാനാവില്ല; ത്രിലോകങ്ങളുടെ നേതാവാണവൻ.",
        "0.43": "\"നാലുമുഖനായ സ്വയംഭൂവായ ബ്രഹ്മാവോ, ത്രിപുരത്തെ നശിപ്പിച്ച മൂന്നുകണ്ണുള്ള രുദ്രനോ, ദേവന്മാരുടെ നേതാവായ മഹേന്ദ്രനോ, യുദ്ധത്തിൽ രാഘവന് മുന്നിൽ നിൽക്കാനാവില്ല.\"",
        "0.44": "വാനരന്റെ ഈ അനിഷ്ടമായ വാക്കുകൾ, നന്നായി പറഞ്ഞതും ഭയമില്ലാത്തതുമായവ, കേട്ട അതുല്യനായ പത്തുതലയുള്ള രാവണൻ കോപത്താൽ കണ്ണുകൾ ഉരുട്ടി, ആ മഹാവാനരനെ വധിക്കാൻ കല്പിച്ചു.",
        "0.45": "ഇങ്ങനെ ആദികാവ്യമായ, ശ്രീമദ് രാമായണത്തിലെ വാല്മീകി രചിച്ച സുന്ദരകാണ്ഡത്തിലെ അമ്പത്തിയൊന്നാം സർഗ്ഗം സമാപിച്ചു."
      },
      "summary": "സുഗ്രീവന്റെ സന്ദേശം ഹനുമാൻ അറിയിക്കുന്നു; സ്വന്തം നന്മയ്ക്കായി സീതയെ രാമന് തിരികെ നൽകാൻ രാവണനോട് ആവശ്യപ്പെടുന്നു. മൂന്നു ലോകത്തിലെയും ഒരു വരമോ ശക്തിയോ രാമന്റെ കോപത്തിൽനിന്ന് രക്ഷിക്കില്ലെന്ന് അദ്ദേഹം മുന്നറിയിപ്പ് നൽകുന്നു."
    },
    "sundarakanda-52": {
      "verses": {
        "0.0": "മഹാത്മാവായ ആ വാനരന്റെ വാക്കുകൾ കേട്ട രാവണൻ കോപത്താൽ സ്വബോധം നഷ്ടപ്പെട്ട്, അവനെ വധിക്കാൻ കല്പിച്ചു.",
        "0.1": "താൻ ദൂതനാണെന്ന് പ്രഖ്യാപിച്ച ഒരാളെ വധിക്കാൻ ദുഷ്ടനായ രാവണൻ കല്പിച്ചപ്പോൾ, വിഭീഷണൻ അതിനെ അംഗീകരിച്ചില്ല.",
        "0.2": "രാക്ഷസരാജാവ് കോപിച്ചിരിക്കുന്നതും ആ പ്രവൃത്തി ആസന്നമായതും അറിഞ്ഞ വിഭീഷണൻ, എന്ത് ചെയ്യണമെന്ന ചിന്തയിൽ ശരിയായ വഴി ആലോചിച്ചു.",
        "0.3": "മനസ്സുറപ്പിച്ച ആ വാഗ്മി, ബഹുമാന്യനായ മൂത്ത സഹോദരനോട്, ശത്രുക്കളെ ജയിക്കുന്നവനോട്, ഏറ്റവും ഗുണകരമായ വാക്കുകൾ മൃദുവായി പറഞ്ഞു:",
        "0.4": "\"ക്ഷമിക്കൂ, കോപം ഉപേക്ഷിക്കൂ, രാക്ഷസരാജാവേ; കൃപ ചെയ്ത് എന്റെ വാക്കുകൾ കേൾക്കൂ. ശരിതെറ്റ് അറിയുന്ന നല്ല രാജാക്കന്മാർ ദൂതനെ വധിക്കാറില്ല.\"",
        "0.5": "\"രാജാവേ, ഈ വാനരനെ കൊല്ലുന്നത് ധർമ്മത്തിന് എതിരാണ്; ലോകനടപ്പുകളാൽ അപലപിക്കപ്പെട്ടതും നിനക്ക് യോഗ്യമല്ലാത്തതുമാണ്, വീരാ.\"",
        "0.6": "\"നീ ധർമ്മം അറിയുന്നവനും കൃതജ്ഞതയുള്ളവനും രാജധർമ്മത്തിൽ വിദഗ്ധനും, ജീവികളുടെ ഉന്നതതാഴ്ചകൾ അറിയുന്നവനും, ഉന്നതമായ സത്യം അറിയുന്നവനുമാണ്.\"",
        "0.7": "\"നിന്നെപ്പോലുള്ള ജ്ഞാനികൾ പോലും കോപത്താൽ വഴിതെറ്റിപ്പോയാൽ, ശാസ്ത്രങ്ങളിലെ പാണ്ഡിത്യം വെറും പാഴ്വേലയല്ലേ.\"",
        "0.8": "\"അതുകൊണ്ട് കൃപയുള്ളവനാകൂ, ശത്രുഘാതകാ, അജയ്യനായ രാക്ഷസനാഥാ; എന്ത് ശരി എന്ത് തെറ്റ് എന്ന് തീരുമാനിക്കൂ, ദൂതന് ശിക്ഷ നിശ്ചയിക്കൂ.\"",
        "0.9": "വിഭീഷണന്റെ വാക്കുകൾ കേട്ട രാക്ഷസനാഥനായ രാവണൻ, മഹാകോപം നിറഞ്ഞ്, മറുപടി പറഞ്ഞു:",
        "0.10": "\"ശത്രുഘാതകാ, പാപികളെ കൊല്ലുന്നതിൽ പാപമില്ല; അതിനാൽ ഈ ദുഷ്ടനായ വാനരനെ ഞാൻ കൊല്ലും.\"",
        "0.11": "അധർമ്മത്തിൽ വേരൂന്നിയതും കുറവുകൾ നിറഞ്ഞതും അധമർക്ക് മാത്രം യോജിച്ചതുമായ വാക്കുകൾ കേട്ട്, ജ്ഞാനികളിൽ ശ്രേഷ്ഠനായ വിഭീഷണൻ ഉന്നതമായ സത്യവാക്കുകൾ പറഞ്ഞു:",
        "0.12": "\"ലങ്കാധിപതിയും രാക്ഷസരാജാവുമായവനേ, കൃപ ചെയ്യൂ; ധർമ്മത്തിന്റെയും അർത്ഥത്തിന്റെയും സാരമടങ്ങിയ വാക്കുകൾ കേൾക്കൂ. ദൂതന്മാരെ ഒരു സാഹചര്യത്തിലും, ഒരിടത്തും കൊല്ലരുതെന്ന് നല്ലവർ പറയുന്നു, രാജാവേ.\"",
        "0.13": "\"ഈ ശത്രു ധിക്കാരിയും നിനക്ക് അളവറ്റ ദോഷം ചെയ്തവനുമാണെന്നതിൽ സംശയമില്ല; എങ്കിലും ദൂതനെ കൊല്ലുന്നത് നല്ലവർ അംഗീകരിക്കുന്നില്ല; ദൂതന് മറ്റു പല ശിക്ഷകളും അറിയപ്പെടുന്നുണ്ട്.",
        "0.14": "\"അംഗഭംഗം വരുത്തുക, അടിക്കുക, തല മുണ്ഡനം ചെയ്യുക, അടയാളമിട്ട് മുദ്ര പതിക്കുക — ഇവയാണ് ദൂതന് വിധിക്കപ്പെട്ട ശിക്ഷകൾ; എന്നാൽ ദൂതനെ കൊല്ലുന്നത് ഞങ്ങൾ ഒരിക്കലും കേട്ടിട്ടില്ല.\"",
        "0.15": "\"ധർമ്മത്തിലും അർത്ഥത്തിലും മനസ്സ് പരിശീലിപ്പിച്ച, ഉന്നതതാഴ്ചകൾ തിരിച്ചറിയുന്ന വിധിയിൽ ഉറച്ച നിന്നെപ്പോലൊരാൾ എങ്ങനെ കോപത്തിന് അധീനനാകും? മനോബലമുള്ളവർ കോപത്തിന് വഴങ്ങാറില്ല.\"",
        "0.16": "\"ധർമ്മോപദേശത്തിലോ, ലോകവ്യവഹാരത്തിലോ, ശാസ്ത്രഗ്രഹണത്തിലോ നിനക്ക് തുല്യനായി ആരുമില്ല, വീരാ; ദേവന്മാരിലും അസുരന്മാരിലും നീ മുൻനിരക്കാരനാണ്.\"",
        "0.17": "\"മഹാവീര്യവും ഉത്സാഹവും മനോബലവുമുള്ള ദേവന്മാർക്കും അസുരന്മാർക്കും അളക്കാനും കീഴടക്കാനും കഴിയാത്തവനായ നീ, യുദ്ധത്തിൽ പലതവണ ദേവസൈന്യങ്ങളെയും മനുഷ്യരാജാക്കന്മാരെയും തോൽപ്പിച്ചിട്ടുണ്ട്.\"",
        "0.18": "\"ദേവന്മാരുടെയും ദൈത്യന്മാരുടെയും ശത്രുവും, ധീരനും, വീരനും, ഒരിക്കലും പരാജയപ്പെടാത്തവനുമായ നിന്നോട് — നിന്നെ മനസ്സുകൊണ്ടുപോലും ദ്രോഹിക്കുന്ന വീരന്മാർ പ്രവർത്തിക്കുന്നതിന് മുൻപേ ജീവൻ നഷ്ടപ്പെടുത്തും.\"",
        "0.19": "\"ഈ വാനരനെ കൊല്ലുന്നതിൽ ഒരു നന്മയും ഞാൻ കാണുന്നില്ല; ഈ ശിക്ഷ അവനെ അയച്ചവരുടെമേൽ പതിക്കട്ടെ.\"",
        "0.20": "\"നല്ലതായാലും ചീത്തയായാലും അവനെ മറ്റാരോ അയച്ചതാണ്; മറ്റൊരാൾക്കുവേണ്ടി, മറ്റൊരാളുടെ കല്പനപ്രകാരം സംസാരിക്കുന്ന ദൂതന് മരണം അർഹിക്കുന്നില്ല.",
        "0.21": "\"കൂടാതെ, രാജാവേ, അവനെ കൊന്നാൽ, മഹാസമുദ്രത്തിന്റെ അക്കരെനിന്ന് ഇവിടെ വീണ്ടും വരാൻ കഴിയുന്ന മറ്റൊരു ആകാശസഞ്ചാരിയെ ഞാൻ കാണുന്നില്ല.",
        "0.22": "\"അതിനാൽ അവനെ കൊല്ലാൻ ഒരു ശ്രമവും വേണ്ട, നഗരങ്ങളെ ജയിക്കുന്നവനേ; നിന്റെ പരിശ്രമം ഇന്ദ്രനോടൊപ്പമുള്ള ദേവന്മാർക്കെതിരെ ആകണം.",
        "0.23": "\"അവൻ നശിച്ചാൽ, യുദ്ധപ്രിയനേ, നിനക്കെതിരെ നിൽക്കുന്ന ആ രണ്ട് ദുർമ്മര്യാദക്കാരായ രാജകുമാരന്മാരെ യുദ്ധത്തിലേക്ക് ഉണർത്താൻ കഴിയുന്ന മറ്റൊരു ജീവിയെയും ഞാൻ കാണുന്നില്ല.",
        "0.24": "\"രാക്ഷസരുടെ സന്തോഷമേ, ദേവന്മാർക്കും അസുരന്മാർക്കും പോലും അജയ്യനായ, മഹാവീര്യവും ഉത്സാഹവുമുള്ള നിനക്ക് ഈ യുദ്ധാവസരം നശിപ്പിക്കുന്നത് യോജിച്ചതല്ല.",
        "0.25": "\"വിശ്വസ്തരും ധീരരും അച്ചടക്കമുള്ളവരും മഹത്തായ പുണ്യമുള്ള ഉന്നതകുലത്തിൽ ജനിച്ചവരും ഉയർന്ന മനോബലമുള്ളവരും യോദ്ധാക്കളിൽ മുൻനിരക്കാരും, കോപത്തിന് പ്രശംസയുള്ളവരും, നന്നായി സജ്ജീകരിക്കപ്പെട്ടവരുമായ യോദ്ധാക്കൾ നിനക്കുണ്ട്.",
        "0.26": "\"അതുകൊണ്ട് അവരിൽ ചിലർ, നിന്റെ സൈന്യത്തിന്റെ ഒരു ഭാഗം, ഇന്ന് നിന്റെ കല്പനപ്രകാരം പുറപ്പെടട്ടെ; ആ രണ്ട് വിഡ്ഢികളായ രാജകുമാരന്മാരെ പിടികൂടി, ശത്രുക്കളുടെ മുന്നിൽ നിന്റെ ശക്തി കാണിക്കട്ടെ.\"",
        "0.27": "രാത്രിസഞ്ചാരികളുടെ നാഥനും, ദേവലോകത്തിന്റെ ശത്രുവും, രാക്ഷസരാജാക്കന്മാരിൽ മഹാനുമായ അവൻ, തന്റെ അനുജൻ വിഭീഷണന്റെ നല്ലതും സ്വീകാര്യവുമായ ഉപദേശം മനസ്സുകൊണ്ട് സ്വീകരിച്ചു.",
        "0.28": "ഇങ്ങനെ ആദികാവ്യമായ, ശ്രീമദ് രാമായണത്തിലെ വാല്മീകി രചിച്ച സുന്ദരകാണ്ഡത്തിലെ അമ്പത്തിരണ്ടാം സർഗ്ഗം സമാപിച്ചു."
      },
      "summary": "കോപാകുലനായ രാവണൻ ഹനുമാനെ വധിക്കാൻ കല്പിക്കുന്നു. ദൂതനെ കൊല്ലാൻ പാടില്ലെന്നും മറ്റൊരു ശിക്ഷ നൽകണമെന്നും വിഭീഷണൻ എതിർക്കുന്നു."
    },
    "sundarakanda-53": {
      "verses": {
        "0.0": "സ്ഥലത്തിനും സമയത്തിനും യോജിച്ച, മഹാത്മാവായ സഹോദരന്റെ ആ വാക്കുകൾ കേട്ട്, പത്തുതലയുള്ള രാവണൻ മറുപടി പറഞ്ഞു:",
        "0.1": "\"നീ ശരിയായി പറഞ്ഞു: ദൂതനെ കൊല്ലുന്നത് നിന്ദ്യമാണ്. എങ്കിലും മരണത്തിൽ കുറഞ്ഞ മറ്റൊരു ശിക്ഷ അവന് നൽകണം തീർച്ചയായും.",
        "0.2": "\"വാനരന്റെ വാൽ അവന്റെ പ്രിയപ്പെട്ട ആഭരണമാണെന്ന് പറയുന്നു. അത് ഉടനെ തീയിടൂ; കരിഞ്ഞ വാലോടെ അവൻ പോകട്ടെ.",
        "0.3": "\"അങ്ങനെ അവന്റെ എല്ലാ സുഹൃത്തുക്കളും ബന്ധുക്കളും ചാർച്ചക്കാരും ഹിതൈഷികളും, അവന്റെ അവയവത്തിന്റെ വികൃതി കണ്ട് ദുഃഖിതനായി കാണട്ടെ.\"",
        "0.4": "രാക്ഷസരാജാവ് കല്പിച്ചു: \"വാൽ എരിയുമ്പോൾ, രാക്ഷസന്മാർ അവനെ നഗരം മുഴുവനും അതിന്റെ തെരുവുകളിലൂടെയും നടത്തിക്കട്ടെ.\"",
        "0.5": "അവന്റെ കല്പന കേട്ട രാക്ഷസന്മാർ, കോപത്താൽ കഠിനരായി, പഴയ പഞ്ഞിത്തുണികൊണ്ട് അവന്റെ വാൽ പൊതിഞ്ഞു.",
        "0.6": "വാൽ പൊതിയുമ്പോൾ, ഉണങ്ങിയ ഇന്ധനം കിട്ടിയ കാട്ടുതീപോലെ ആ മഹാവാനരൻ വലുതായി വളർന്നു.",
        "0.7": "പിന്നെ എണ്ണയിൽ കുതിർത്ത് അവർ തീയിട്ടു; ജ്വലിക്കുന്ന വാലുകൊണ്ട് അദ്ദേഹം ആ രാക്ഷസന്മാരെ പ്രഹരിച്ചു.",
        "0.8": "കോപവും അമർഷവും നിറഞ്ഞ്, ഉദിക്കുന്ന സൂര്യനെപ്പോലെ മുഖം ജ്വലിച്ച വാനരശ്രേഷ്ഠനെ, ഒത്തുകൂടിയ ക്രൂരരായ രാക്ഷസന്മാർ വീണ്ടും പിടികൂടി.",
        "0.9": "രാക്ഷസരാജ്യസന്തതികൾ, അവരുടെ സ്ത്രീകളും കുട്ടികളും വൃദ്ധരുമായി സന്തോഷിച്ചു; ബന്ധിതനായ ആ വീരൻ, സമയത്തിനു യോജിച്ച ഒരു തീരുമാനമെടുത്തു.",
        "0.10": "\"ഇങ്ങനെ ബന്ധിതനെങ്കിലും, ഈ രാക്ഷസന്മാർ എനിക്ക് തീർച്ചയായും എതിരല്ല; ഈ ബന്ധനങ്ങൾ എനിക്ക് പൊട്ടിക്കാം, ചാടിയെഴുന്നേറ്റ് അവരെ വീണ്ടും കൊല്ലാം.\"",
        "0.11": "\"യജമാനന്റെ കല്പനപ്രകാരം അദ്ദേഹത്തിന്റെ കാര്യം ചെയ്തു നടക്കുമ്പോൾ ഈ ദുഷ്ടന്മാർ എന്നെ ബന്ധിക്കുന്നു; എന്നിട്ടും ഞാൻ ചെയ്തതിന് അവർ പ്രതിഫലം തന്നിട്ടില്ല.\"",
        "0.12": "\"യുദ്ധത്തിൽ എല്ലാ രാക്ഷസന്മാർക്കും ഞാൻ തുല്യനാണ്; പക്ഷേ രാമന്റെ കാര്യത്തിനുവേണ്ടി ഞാൻ ഇതും സഹിക്കും.\"",
        "0.13": "\"ലങ്കയെ ഒരിക്കൽക്കൂടി ചുറ്റി സഞ്ചരിക്കണം; രാത്രിയിൽ അതിന്റെ കോട്ടകൾ എങ്ങനെയാണെന്ന് എനിക്ക് ശരിയായി കാണാൻ കഴിഞ്ഞിരുന്നില്ല.\"",
        "0.14": "\"പകൽവെളിച്ചത്തിൽ ലങ്ക ഞാൻ തീർച്ചയായും കാണണം. അവർ വീണ്ടും എന്നെ ബന്ധിക്കട്ടെ; അവർക്കിഷ്ടമുള്ളതുപോലെ എന്റെ വാലിന് തീയിടട്ടെ;",
        "0.15": "\"രാക്ഷസന്മാർ എന്നെ പീഡിപ്പിച്ചാലും, എന്റെ മനസ്സിന് ഒരു ക്ഷീണവും തോന്നുന്നില്ല.\" അപ്പോൾ രാക്ഷസന്മാർ, ഉദ്ദേശ്യം മറച്ചുവെച്ച ആ ബലശാലിയായ മഹാവാനരനെ പിടികൂടി.",
        "0.16": "ശംഖിന്റെയും ചെണ്ടയുടെയും ശബ്ദത്തോടെ അവന്റെ പ്രവൃത്തികൾ വിളിച്ചുപറഞ്ഞുകൊണ്ട്, സന്തോഷത്തോടെ ആ വാനരഗജത്തെ അവർ കൊണ്ടുപോയി.",
        "0.17": "ക്രൂരകർമ്മികളായ രാക്ഷസന്മാർ അവനെ ആ നഗരത്തിലൂടെ നടത്തി; അവരെ പിന്തുടർന്ന്, ശത്രുക്കളെ അടക്കുന്നവൻ സുഖമായി നടന്നു.",
        "0.18": "അങ്ങനെ ഹനുമാൻ രാക്ഷസരുടെ മഹാനഗരം ചുറ്റിനടന്നു; മഹാവാനരൻ അതിന്റെ അത്ഭുതകരമായ മന്ദിരങ്ങൾ കണ്ടു.",
        "0.19": "ചുറ്റുമതിലുള്ള ഉദ്യാനങ്ങളും, നന്നായി ക്രമീകരിച്ച ചതുരങ്ങളും, വീടുകൾ നിറഞ്ഞ തെരുവുകളും, കവലകളും;",
        "0.20": "അതുപോലെ പ്രധാന വീഥികളും ഇടവഴികളും വീടുകൾക്കിടയിലെ സ്ഥലങ്ങളും; ചതുരങ്ങളിലും, കവലകളിലും, രാജവീഥിയിലും —",
        "0.21": "എല്ലാ രാക്ഷസന്മാരും ആ വാനരനെ ചാരൻ എന്ന് വിളിച്ചുപറഞ്ഞു. കൗതുകത്താൽ സ്ത്രീകളും കുട്ടികളും വൃദ്ധരും പലയിടത്തുനിന്നായി പുറത്തുവന്നു,",
        "0.22": "വാൽ കത്തുന്ന ഹനുമാനെ കാണാൻ ആഗ്രഹിച്ച്. ഹനുമാന്റെ വാലിന്റെ അഗ്രം ജ്വലിക്കുമ്പോൾ,",
        "0.23": "വികൃതമായ കണ്ണുകളുള്ള രാക്ഷസിമാർ ദേവിയോട് അനിഷ്ടവാർത്ത അറിയിച്ചു: \"സീതേ, നീ സംസാരിച്ച ചുവന്ന മുഖമുള്ള വാനരൻ,\"",
        "0.24": "\"വാൽ തീപിടിച്ച നിലയിൽ നഗരത്തിലൂടെ നടത്തപ്പെടുന്നു.\" ആ ക്രൂരവാക്കുകൾ കേട്ട്, അത് അവളുടെതന്നെ അപഹരണംപോലെ തോന്നി,",
        "0.25": "ദുഃഖത്താൽ പീഡിതയായ വൈദേഹി അഗ്നിയിലേക്ക് തിരിഞ്ഞു; അപ്പോൾ അവൾ മഹാവാനരന്റെ ക്ഷേമത്തിൽ മനസ്സ് വെച്ചിരുന്നു.",
        "0.26": "ശുദ്ധമനസ്സുള്ള വിശാലനേത്രയായ ആ സ്ത്രീ, ഹവിസ്സ് വഹിക്കുന്ന അഗ്നിയോട് പ്രാർത്ഥിച്ചു: \"ഞാൻ ഭർത്താവിനെ സേവിച്ചിട്ടുണ്ടെങ്കിൽ, തപസ്സ് ചെയ്തിട്ടുണ്ടെങ്കിൽ, ഒരു ഭർത്താവിനോട് മാത്രം വിശ്വസ്തയായിരുന്നെങ്കിൽ, ഹനുമാന് തണുപ്പായിരിക്കണേ.\"",
        "0.27": "\"ആ ജ്ഞാനിക്ക് എന്നോട് വല്ല കരുണയുമുണ്ടെങ്കിൽ, അല്ലെങ്കിൽ എന്റെ ഭാഗ്യത്തിൽ വല്ലതും ശേഷിക്കുന്നുണ്ടെങ്കിൽ, ഹനുമാന് തണുപ്പായിരിക്കണേ.\"",
        "0.28": "\"ആ ധർമ്മിഷ്ഠൻ എന്റെ നല്ല നടപ്പും അവനുമായി വീണ്ടും ചേരാനുള്ള ആഗ്രഹവും അറിയുന്നുണ്ടെങ്കിൽ, ഹനുമാന് തണുപ്പായിരിക്കണേ.\"",
        "0.29": "\"വാക്കുപാലിക്കുന്ന മഹാനായ സുഗ്രീവൻ എന്നെ ഈ ദുഃഖപ്രവാഹത്തിൽനിന്ന് രക്ഷിക്കേണ്ടതുണ്ടെങ്കിൽ, ഹനുമാന് തണുപ്പായിരിക്കണേ.\"",
        "0.30": "അപ്പോൾ മൂർച്ചയുള്ളതും എന്നാൽ ശാന്തവുമായ ജ്വാലകളോടെ തീ, വാനരന്റെ ക്ഷേമം മാൻകണ്ണിയായ സ്ത്രീയെ അറിയിക്കുന്നതുപോലെ വലത്തോട്ട് തിരിഞ്ഞ ശിഖയോടെ ജ്വലിച്ചു.",
        "0.31": "ഹനുമാന്റെ പിതാവായ വായുദേവൻ, വാലിലെ തീ വഹിച്ചുകൊണ്ട്, ദേവിക്ക് ആശ്വാസം നൽകി, മഞ്ഞുപോലെ തണുത്ത കാറ്റായി വീശി.",
        "0.32": "വാൽ കത്തുമ്പോൾ വാനരൻ ചിന്തിച്ചു: \"ഈ ജ്വലിക്കുന്ന തീ എന്നെ ഒരിടത്തും പൊള്ളിക്കാത്തത് എന്തുകൊണ്ട്?\"",
        "0.33": "\"വലിയ ജ്വാലകൾ കാണുന്നു, എങ്കിലും എനിക്ക് വേദന ഉണ്ടാക്കുന്നില്ല; വാലിന്റെ അറ്റത്ത് മഞ്ഞുവീഴ്ച വീണിരിക്കുന്നതുപോലെ.\"",
        "0.34": "\"അല്ലെങ്കിൽ, വ്യക്തമാണ് — ചാടുമ്പോൾ ഞാൻ കണ്ടതുപോലെ, സമുദ്രത്തിൽ ഒരു പർവതം ഉയർന്നു; രാമന്റെ ശക്തിയാൽ ഒരു അത്ഭുതം.\"",
        "0.35": "\"രാമന്റെ കാര്യത്തിനായി സമുദ്രവും ജ്ഞാനിയായ മൈനാകവും ഇത്രയും ഉത്സാഹം കാണിച്ചെങ്കിൽ, അഗ്നി എന്ത് ചെയ്യാതിരിക്കും?\"",
        "0.36": "\"സീതയുടെ കരുണയാലും, രാഘവന്റെ ശക്തിയാലും, എന്റെ പിതാവിന്റെ സൗഹൃദത്താലും തീ എന്നെ പൊള്ളിക്കുന്നില്ല.\"",
        "0.37": "വീണ്ടും ഒരു നിമിഷം ആ ആനപ്പുറത്തെ വാനരൻ ചിന്തിച്ചു: \"എന്നെപ്പോലുള്ളവനെ ഇവിടെ ഈ നീചരായ രാക്ഷസന്മാർ ബന്ധിക്കുന്നത് എങ്ങനെ?\"",
        "0.38": "\"എനിക്ക് ശക്തിയുള്ളതിനാൽ പകരം വീട്ടുന്നത് ശരിയാണ്.\" അപ്പോൾ ആ ബന്ധനങ്ങൾ പൊട്ടിച്ച്, വേഗമേറിയ മഹാവാനരൻ",
        "0.39": "ശക്തിയോടെ ചാടി ഗർജ്ജിച്ചു. പിന്നെ മഹാവീരനായ വായുപുത്രൻ, പർവതശിഖരംപോലെ ഉയർന്ന നഗരകവാടത്തിലെത്തി.",
        "0.40": "രാക്ഷസക്കൂട്ടം മാറിനിന്ന അവിടെ, ആത്മനിയന്ത്രണമുള്ളവൻ ഒരു നിമിഷംകൊണ്ട് പർവതംപോലെ വലുതായ ശേഷം,",
        "0.41": "അത്യന്തം ചെറുതായി, ബന്ധനങ്ങൾ കുടഞ്ഞുകളഞ്ഞു; മോചിതനായ ആ തേജസ്വി വീണ്ടും പർവതസമാനനായി.",
        "0.42": "ചുറ്റും നോക്കി, ഗോപുരവാതിലിൽ ചാരി നിൽക്കുന്ന ഒരു ഇരുമ്പുദണ്ഡ് കണ്ടു; ഇരുമ്പുകെട്ടിയ ആ ദണ്ഡ് പിടിച്ച്, ബലശാലിയായ വായുപുത്രൻ ആ കാവൽക്കാരെയെല്ലാം വീണ്ടും വധിച്ചു.",
        "0.43": "അവരെ വധിച്ച ശേഷം, യുദ്ധത്തിൽ ഭയങ്കര വീര്യമുള്ളവൻ, സൂര്യനെ രശ്മികൾകൊണ്ട് അലങ്കരിച്ചതുപോലെ, തന്റെ ജ്വലിക്കുന്ന വാലിന്റെ ജ്വാലകളാൽ അലങ്കരിക്കപ്പെട്ട്, ലങ്കയെ ഒരിക്കൽക്കൂടി നോക്കി.",
        "0.44": "ഇങ്ങനെ ആദികാവ്യമായ, ശ്രീമദ് രാമായണത്തിലെ വാല്മീകി രചിച്ച സുന്ദരകാണ്ഡത്തിലെ അമ്പത്തിമൂന്നാം സർഗ്ഗം സമാപിച്ചു."
      },
      "summary": "രാവണൻ ഹനുമാന്റെ വാൽ തീകൊളുത്താൻ കല്പിക്കുന്നു; രാക്ഷസന്മാർ അവനെ നഗരത്തിലൂടെ നടത്തിക്കുന്നു. ഇത് കേട്ട സീത അഗ്നിദേവനോട് ഹനുമാനോട് കനിവുണ്ടാകാൻ പ്രാർത്ഥിക്കുന്നു; തീ അവനെ പൊള്ളിക്കുന്നില്ല."
    },
    "sundarakanda-54": {
      "verses": {
        "0.0": "പിന്നെ ലങ്കയെ നോക്കി, തന്റെ ആഗ്രഹം സാധിച്ച്, ഉത്സാഹം വർദ്ധിച്ച വാനരൻ, ഇനി ചെയ്യാനുള്ളതെന്തെന്ന് ആലോചിച്ചു.",
        "0.1": "\"ഈ രാക്ഷസന്മാർക്ക് കൂടുതൽ പീഡ നൽകാൻ ഇവിടെ എനിക്ക് ഇനി എന്താണ് ചെയ്യാനുള്ളത്?\"",
        "0.2": "\"ഉദ്യാനം തകർന്നു, പ്രധാന രാക്ഷസന്മാർ കൊല്ലപ്പെട്ടു, സൈന്യത്തിന്റെ ഒരു ഭാഗം നശിച്ചു; ഇനി കോട്ട നശിപ്പിക്കുക മാത്രമേ ശേഷിക്കുന്നുള്ളൂ.\"",
        "0.3": "\"കോട്ട നശിച്ചാൽ വരാനുള്ള പ്രവൃത്തി എളുപ്പമാകും; ഇവിടെ ഇനി അല്പം പരിശ്രമം കൂടിയാൽ എന്റെ അധ്വാനം പൂർണ്ണഫലം നൽകും.\"",
        "0.4": "\"എന്റെ വാലിൽ ജ്വലിക്കുന്ന ഈ തീ — ഈ മനോഹര ഭവനങ്ങൾകൊണ്ട് അതിനെ തൃപ്തിപ്പെടുത്തുന്നത് ശരിയാണ്.\"",
        "0.5": "അപ്പോൾ മിന്നലുള്ള മേഘംപോലെ, വാലിൽ തീ ജ്വലിച്ച്, മഹാവാനരൻ ലങ്കയുടെ മേൽക്കൂരകളിലൂടെ സഞ്ചരിച്ചു.",
        "0.6": "രാക്ഷസന്മാരുടെ ഓരോ വീട്ടിൽനിന്നും വീട്ടിലേക്ക്, അവരുടെ ഉദ്യാനങ്ങളിലൂടെയും കൊട്ടാരങ്ങളിലൂടെയും, ചുറ്റും നോക്കി, ഒട്ടും ഭയമില്ലാതെ വാനരൻ നീങ്ങി.",
        "0.7": "പ്രഹസ്തന്റെ മന്ദിരത്തിലേക്ക് അതിവേഗത്തിൽ താഴേക്ക് ചാടി, വായുവിനു തുല്യനായ ബലശാലി അതിന് തീയിട്ടു;",
        "0.8": "പിന്നെ മഹാബലശാലിയായ ഹനുമാൻ മറ്റൊന്നിലേക്ക് — മഹാപാർശ്വന്റെ ഭവനത്തിലേക്ക് — ചാടി, അവിടെ പ്രളയകാലാഗ്നിയുടെ ജ്വാലപോലെ തീ അഴിച്ചുവിട്ടു.",
        "0.9": "അതുപോലെ മഹാതേജസ്വിയായ വാനരൻ വജ്രദംഷ്ട്രന്റെയും ശുകന്റെയും ജ്ഞാനിയായ സാരണന്റെയും ഭവനങ്ങളിലേക്ക് ചാടി.",
        "0.10": "പിന്നെ വാനരനേതാവ് ഇന്ദ്രജിത്തിന്റെ ഭവനം കത്തിച്ചു; അതിനുശേഷം ജംബുമാലിയുടെയും സുമാലിയുടെയും ഭവനങ്ങൾ —",
        "0.11": "രശ്മികേതുവിന്റെയും സൂര്യശത്രുവിന്റെയും, ഹ്രസ്വകർണ്ണന്റെയും ദംഷ്ട്രന്റെയും, രാക്ഷസനായ രോമശന്റെയും ഭവനങ്ങൾ —",
        "0.12": "യുദ്ധോന്മത്തന്റെയും മത്തന്റെയും, രാക്ഷസനായ ധ്വജഗ്രീവന്റെയും, ഭയങ്കരനായ വിദ്യുജ്ജിഹ്വന്റെയും ഹസ്തിമുഖന്റെയും ഭവനങ്ങൾ —",
        "0.13": "കരാളന്റെയും വിശാലന്റെയും ശോണിതാക്ഷന്റെയും, കുംഭകർണ്ണന്റെയും മകരാക്ഷന്റെയും ഭവനങ്ങൾ —",
        "0.14": "നരാന്തകന്റെയും കുംഭന്റെയും ദുഷ്ടനായ നികുംഭന്റെയും, യജ്ഞശത്രുവിന്റെയും അതുപോലെ ബ്രഹ്മശത്രുവിന്റെയും ഭവനങ്ങൾ —",
        "0.15": "വിഭീഷണന്റെ ഭവനം മാത്രം ഒഴിവാക്കി; ഏറ്റവും തിളക്കമുള്ള വാനരശ്രേഷ്ഠൻ ക്രമമായി മുന്നോട്ടുപോയി, ഓരോന്നായി എല്ലാം കത്തിച്ചു.",
        "0.16": "വിലയേറിയ ആ മന്ദിരങ്ങളിൽ, വാനരഗജമായ പ്രസിദ്ധൻ വലിയവരുടെ സമ്പത്ത് ദഹിപ്പിച്ചു.",
        "0.17": "അവരെയെല്ലാം കടന്ന്, മഹാബലശാലിയും തേജസ്വിയുമായവൻ പിന്നെ രാക്ഷസരാജാവായ രാവണന്റെ കൊട്ടാരത്തിലെത്തി.",
        "0.18": "അപ്പോൾ അനേകം രത്നങ്ങളാൽ അലങ്കരിച്ച, മേരുവോ മന്ദരമോ പോലെ, അനേകം ശുഭവസ്തുക്കളാൽ തിളങ്ങുന്ന ആ പ്രധാന മന്ദിരത്തിൽ,",
        "0.19": "വീരനായ ഹനുമാൻ തന്റെ വാലിന്റെ അറ്റത്ത് നിന്നിരുന്ന ജ്വലിക്കുന്ന തീ അഴിച്ചുവിട്ടു; യുഗാന്ത്യമേഘംപോലെ ഗർജ്ജിച്ചു.",
        "0.20": "കാറ്റിനോടൊപ്പം ചേർന്ന്, അതിവേഗവും ബലവുമുള്ള ആ തീ കാലാഗ്നിപോലെ ജ്വലിച്ച് പടർന്നു.",
        "0.21": "കാറ്റ് ജ്വലിക്കുന്ന തീയെ ആ വീടുകളിലൂടെ പടർത്തി; സ്വർണ്ണവലകളും മുത്തുകളും രത്നങ്ങളും ഉള്ള ആ മന്ദിരങ്ങൾ,",
        "0.22": "വലുതും രത്നസമൃദ്ധവുമായവ, തകർന്നു; ഗോപുരങ്ങൾ ഒടിഞ്ഞ് അവ നിലത്തുവീണു,",
        "0.23": "ആകാശത്തുനിന്ന് സിദ്ധന്മാരുടെ പുണ്യം തീരുമ്പോൾ വീഴുന്ന മന്ദിരങ്ങൾപോലെ. ഓടിനടക്കുന്ന രാക്ഷസന്മാരിൽ നിന്ന് ഒരു ബഹളം ഉയർന്നു;",
        "0.24": "അവർ ധൈര്യം നഷ്ടപ്പെട്ടും തേജസ്സ് മങ്ങിയും സ്വന്തം വീടുകൾ രക്ഷിക്കാൻ ശ്രമിച്ചു: \"അയ്യോ, ഇത് വാനരരൂപത്തിൽ വന്ന അഗ്നിദേവൻ തന്നെയാണ്!\"",
        "0.25": "മുലകുടിക്കുന്ന കുഞ്ഞുങ്ങളുമായുള്ള സ്ത്രീകൾ പെട്ടെന്ന് നിലവിളിച്ചുവീണു; ചിലർ, അവയവങ്ങളിൽ തീ പടർന്നും മുടി അഴിഞ്ഞും, മന്ദിരങ്ങളിൽനിന്ന് വീണു.",
        "0.26": "വീണുകൊണ്ട്, ആകാശത്തിലെ മേഘങ്ങളിൽനിന്ന് വീഴുന്ന മിന്നൽപ്പിണരുകൾപോലെ അവർ തിളങ്ങി. ഉരുകിയ ലോഹങ്ങളുടെ പ്രവാഹം — വജ്രം, പവിഴം, വൈഡൂര്യം, മുത്ത്, വെള്ളി എന്നിവ കലർന്നത് — അവൻ കണ്ടു;",
        "0.27": "മന്ദിരങ്ങളിൽനിന്ന് ഒഴുകുന്ന അത്ഭുതകരമായ പ്രവാഹം. മരവും പുല്ലും കൊണ്ട് അഗ്നി ഒരിക്കലും തൃപ്തിപ്പെടാത്തതുപോലെ,",
        "0.28": "രാക്ഷസപ്രമുഖരെ വധിക്കുന്നതിൽ ഹനുമാനും ഒരിക്കലും തൃപ്തനായില്ല; അദ്ദേഹം കൊന്ന രാക്ഷസന്മാരെക്കൊണ്ട് ഭൂമിയും തൃപ്തയായില്ല.",
        "0.29": "വേഗമേറിയതും മഹാത്മാവുമായ വാനരൻ ഹനുമാനാൽ ലങ്കാനഗരം ദഹിപ്പിക്കപ്പെട്ടു — ത്രിപുരം രുദ്രനാൽ ദഹിപ്പിക്കപ്പെട്ടതുപോലെ.",
        "0.30": "പിന്നെ ലങ്കാനഗരത്തിന്റെ പർവതശിഖരത്തിൽ, വേഗമേറിയ ഹനുമാൻ കൊളുത്തിയ തീ, ശക്തിയിൽ ഭയങ്കരമായി, ശിഖയുടെ ജ്വാലവലയം പടർത്തിക്കൊണ്ട് ഉയർന്നു.",
        "0.31": "യുഗാന്ത്യകാലത്തെ കാലാഗ്നിപോലെ, കാറ്റേറ്റ് ജ്വലിച്ച തീ ആകാശം തൊടുംവരെ വളർന്നു; പുകയില്ലാത്ത രശ്മികളോടെ വീടുകളിൽ പറ്റിപ്പിടിച്ച്, രാക്ഷസരുടെ ശരീരങ്ങൾ നെയ്യ് എന്നപോലെ അതിന് ഇന്ധനമായി.",
        "0.32": "കോടി സൂര്യന്മാരെപ്പോലെ ശോഭിച്ച മഹാഅഗ്നി ലങ്ക മുഴുവൻ ചുറ്റി നിന്നു; പൊട്ടിത്തെറിക്കുന്ന ഇടിമിന്നലുകൾ പോലെ പല ശബ്ദങ്ങളോടെ അത് പ്രപഞ്ചാണ്ഡത്തെ പിളർക്കുന്നതുപോലെ തോന്നി.",
        "0.33": "അഗ്നി വലുതായി വളർന്ന്, കഠിനമായ വെളിച്ചത്തോടെ ആകാശംവരെ ഉയർന്നു; അതിന്റെ ശിഖ പലാശപ്പൂവുപോലെ; ഒടുങ്ങുന്ന ജ്വാലകളുടെ പുകപടലങ്ങളാൽ വരയിട്ട മേഘങ്ങൾ നീലത്താമരപോലെ തിളങ്ങി.",
        "0.34": "\"ഇത് വജ്രായുധം ഏന്തിയ, ദേവന്മാരുടെ നാഥനായ മഹേന്ദ്രനോ? അതോ യമൻതന്നെയോ? വരുണനോ വായുവോ? രുദ്രന്റെ അഗ്നിയോ, സൂര്യനോ, കുബേരനോ, ചന്ദ്രനോ? ഇത് വാനരനല്ല — കാലം തന്നെയാണ്!\"",
        "0.35": "\"അതോ സർവ്വപിതാമഹനും ലോകസ്രഷ്ടാവുമായ നാലുമുഖനായ ബ്രഹ്മാവിന്റെ കോപം രാക്ഷസന്മാരുടെ അന്ത്യം വരുത്താൻ വാനരരൂപത്തിൽ ഇവിടെ വന്നതാണോ?\"",
        "0.36": "\"അതോ, അചിന്ത്യവും അവ്യക്തവും അനന്തവും ഏകവുമായ വിഷ്ണുവിന്റെ പരമ തേജസ്സ്, തന്റെ സ്വന്തം മായാശക്തിയാൽ രാക്ഷസന്മാരെ നശിപ്പിക്കാൻ വാനരരൂപത്തിൽ ഇപ്പോൾ വന്നതാണോ?\"",
        "0.37": "പെട്ടെന്ന് കത്തിയെരിഞ്ഞ ആ നഗരം, ജീവികളുടെ കൂട്ടങ്ങളും വീടുകളും മരങ്ങളുമായി, കണ്ട അവിടെ ഒത്തുകൂടിയ പ്രമുഖ രാക്ഷസന്മാർ പലതും പറഞ്ഞു.",
        "0.38": "പിന്നെ, രാക്ഷസന്മാർ, കുതിരകൾ, രഥങ്ങൾ, ആനകൾ എന്നിവയോടൊപ്പം പെട്ടെന്ന് കത്തിയ ലങ്ക, പക്ഷിക്കൂട്ടങ്ങൾ, മൃഗങ്ങൾ, മരങ്ങൾ എന്നിവയോടുകൂടി, ബഹളത്തോടെ ദയനീയമായി കരഞ്ഞു.",
        "0.39": "\"അയ്യോ അച്ഛാ! അയ്യോ മകനേ! പ്രിയനേ! സുഹൃത്തേ! അയ്യോ എന്റെ ജീവനാഥാ — നമ്മുടെ പുണ്യമെല്ലാം നഷ്ടപ്പെട്ടു!\" — ഇങ്ങനെ രാക്ഷസന്മാർ പലവിധത്തിൽ വിലപിച്ചു, ഭയങ്കരമായ ഒച്ച ഉയർത്തി.",
        "0.40": "അഗ്നിയിൽ പൊതിഞ്ഞ്, പ്രധാന വീരന്മാർ കൊല്ലപ്പെട്ടും യോദ്ധാക്കൾ ചിതറിയോടിയും, ഹനുമാന്റെ കോപത്തിന്റെ ശക്തിയാൽ പീഡിതയായ ലങ്ക, ശാപമേറ്റ നഗരംപോലെയായി.",
        "0.41": "മഹാമനസ്കനായ ഹനുമാൻ, പരിഭ്രാന്തരും ഭയന്നവരും നിരാശരുമായ രാക്ഷസന്മാരുള്ള ലങ്കയെ കണ്ടു; ഉഗ്രമായി ജ്വലിക്കുന്ന തീയാൽ അടയാളപ്പെട്ട ആ നഗരം, സ്വയംഭൂവിന്റെ കോപമേറ്റ ഭൂമിപോലെ.",
        "0.42": "വിലയേറിയ മരങ്ങൾ നിറഞ്ഞ ഉദ്യാനം തകർത്ത്, യുദ്ധത്തിൽ ശക്തരായ രാക്ഷസന്മാരെ വധിച്ച്, രത്നസമാനമായ മന്ദിരങ്ങളാൽ അലങ്കരിക്കപ്പെട്ട ആ നഗരം ചുട്ടെരിച്ച്, വായുപുത്രനായ വാനരൻ ഹനുമാൻ നിശ്ചലനായി നിന്നു.",
        "0.43": "ആ അനേകം രാക്ഷസന്മാരെ വധിച്ച്, അനേകം വൃക്ഷങ്ങളുള്ള ഉദ്യാനം നശിപ്പിച്ച്, രാക്ഷസന്മാരുടെ വീടുകൾക്ക് തീയിട്ട ശേഷം, മഹാത്മാവ് രാമനെക്കുറിച്ച് ചിന്തയിലാണ്ടു.",
        "0.44": "അപ്പോൾ എല്ലാ ദേവസംഘങ്ങളും ആ വാനരവീരന്മാരിൽ ശ്രേഷ്ഠനെ സ്തുതിച്ചു — ശക്തനും കാറ്റിനു തുല്യവേഗമുള്ളവനും മഹാബുദ്ധിയുള്ളവനുമായ വായുപുത്രനെ.",
        "0.45": "സർവ്വദേവന്മാരും, മുനിശ്രേഷ്ഠന്മാരും, ഗന്ധർവന്മാരും, വിദ്യാധരന്മാരും, നാഗന്മാരും, അവിടെയുണ്ടായിരുന്ന എല്ലാ മഹാജീവികളും ഏറ്റവും ഉയർന്ന, അതുല്യമായ ആനന്ദം അനുഭവിച്ചു.",
        "0.46": "ഉദ്യാനം തകർത്ത്, യുദ്ധത്തിൽ രാക്ഷസന്മാരെ വധിച്ച്, ഭയങ്കരമായ ലങ്കാനഗരം ചുട്ടെരിച്ച്, തേജസ്വിയായ മഹാവാനരൻ പ്രകാശിച്ചു.",
        "0.47": "ഒരു മഹത്തായ മന്ദിരത്തിന്റെ ശിഖരമുകളിൽ നിന്ന്, ജ്വലിക്കുന്ന വാലിന്റെ ജ്വാലകളാൽ അലങ്കരിക്കപ്പെട്ട ആ വാനരരാജസിംഹം, രശ്മികളാൽ അലങ്കരിച്ച സൂര്യനെപ്പോലെ തിളങ്ങി.",
        "0.48": "ലങ്കയെ മുഴുവൻ ഉഴുതുമറിച്ച ശേഷം, വാനരശ്രേഷ്ഠനായ മഹാവാനരൻ തന്റെ വാലിലെ തീ സമുദ്രത്തിൽ കെടുത്തി.",
        "0.49": "പിന്നെ ലങ്ക കത്തുന്നത് കണ്ട, ഗന്ധർവന്മാരോടൊപ്പമുള്ള ദേവന്മാരും സിദ്ധന്മാരും പരമമുനിമാരും ഏറ്റവും വലിയ അത്ഭുതത്താൽ നിറഞ്ഞു.",
        "0.50": "വാനരശ്രേഷ്ഠനായ മഹാവാനര ഹനുമാനെ കണ്ടപ്പോൾ സകല ജീവികളും വിറച്ചു; അവനെ കാലാഗ്നിയായി കരുതി.",
        "0.51": "ഇങ്ങനെ ആദികാവ്യമായ, ശ്രീമദ് രാമായണത്തിലെ വാല്മീകി രചിച്ച സുന്ദരകാണ്ഡത്തിലെ അമ്പത്തിനാലാം സർഗ്ഗം സമാപിച്ചു."
      },
      "summary": "ബന്ധനത്തിൽനിന്ന് മോചിതനായ ഹനുമാൻ, ജ്വലിക്കുന്ന വാലോടെ മേൽക്കൂരകളിൽനിന്ന് മേൽക്കൂരകളിലേക്ക് ചാടി ലങ്കയിലെ മന്ദിരങ്ങൾക്ക് തീയിടുന്നു. രാക്ഷസന്മാരുടെ നിലവിളികൾക്കിടയിൽ നഗരം കത്തിയെരിയുന്നു."
    },
    "sundarakanda-55": {
      "verses": {
        "0.0": "കത്തിയെരിഞ്ഞ് കലങ്ങിമറിഞ്ഞ ലങ്കാനഗരത്തെയും ഭയന്നുവിറച്ച രാക്ഷസ സൈന്യങ്ങളെയും നോക്കി, വാനരനായ ഹനുമാൻ ചിന്തിക്കാൻ തുടങ്ങി.",
        "0.1": "വലിയ ഭയം അദ്ദേഹത്തെ ബാധിച്ചു; ഉള്ളിൽ സ്വയം നിന്ദ ഉയർന്നു: \"ലങ്ക കത്തിച്ചതിലൂടെ ഞാൻ എന്താണ് ചെയ്തത്?\"",
        "0.2": "\"ഉണർന്നുവന്ന കോപത്തെ, കത്തുന്ന തീയെ വെള്ളംകൊണ്ട് കെടുത്തുന്നതുപോലെ, വിവേകത്താൽ തടയുന്ന മഹാത്മാക്കൾ ധന്യരാണ്.\"",
        "0.3": "\"കോപിച്ചവൻ ഏത് പാപമാണ് ചെയ്യാത്തത്? കോപത്തിൽ ഒരാൾ മുതിർന്നവരെപ്പോലും കൊന്നേക്കാം; കോപത്തിൽ ഒരാൾ നല്ലവരെ കടുത്ത വാക്കുകൾകൊണ്ട് അപമാനിച്ചേക്കാം.\"",
        "0.4": "\"കോപത്തിലുള്ളവൻ എന്ത് പറയണം, എന്ത് പറയരുത് എന്ന് ഒരിക്കലും അറിയുന്നില്ല; കോപിച്ചവന് ചെയ്യാൻ പാടില്ലാത്തതായി ഒന്നുമില്ല, പറയാൻ പാടില്ലാത്തതായും ഒന്നുമില്ല.\"",
        "0.5": "\"ഉയർന്നുവരുമ്പോഴേ കോപം ഉപേക്ഷിച്ച്, സഹനത്താൽ മാത്രം, പാമ്പ് പഴയ തൊലി ഉരിയുന്നതുപോലെ അത് ഉപേക്ഷിക്കുന്നവനെയാണ് യഥാർത്ഥത്തിൽ മനുഷ്യൻ എന്ന് വിളിക്കുന്നത്.\"",
        "0.6": "\"എനിക്ക് ലജ്ജ! പൂർണ്ണ വിഡ്ഢിയായ, നാണമില്ലാത്ത, പാപികളിൽ ഏറ്റവും മോശമായ ഞാൻ, സീതയെക്കുറിച്ച് ചിന്തിക്കാതെ തീയിട്ട് യജമാനനെ വഞ്ചിച്ചു!\"",
        "0.7": "\"നഗരം മുഴുവൻ കത്തിയെങ്കിൽ, കുലീനയായ ജാനകിയും തീർച്ചയായും കത്തിയിട്ടുണ്ടാകും; അറിയാതെ ഞാൻ യജമാനന്റെ കാര്യം നശിപ്പിച്ചു.\"",
        "0.8": "\"ഈ മുഴുവൻ ദൗത്യം ആരംഭിച്ച ലക്ഷ്യംതന്നെ ഞാൻ നശിപ്പിച്ചു; ലങ്ക ചുട്ടെരിച്ചപ്പോൾ സീതയെ ഞാൻ സംരക്ഷിച്ചില്ലല്ലോ.\"",
        "0.9": "\"ഈ ദൗത്യം ഏതാണ്ട് പൂർത്തിയായിരുന്നു എന്നതിൽ സംശയമില്ല; എങ്കിലും കോപത്താൽ കീഴടക്കപ്പെട്ട്, അതിന്റെ മൂലംതന്നെ ഞാൻ നശിപ്പിച്ചു.\"",
        "0.10": "\"ലങ്കയുടെ ഒരു ഭാഗവും കത്താതെ കാണുന്നില്ല; നഗരം മുഴുവൻ ചാരമാക്കപ്പെട്ടു; അതിനാൽ ജാനകി മരിച്ചുപോയെന്ന് വ്യക്തമാണ്.\"",
        "0.11": "\"എന്റെ വിവേകക്കുറവിനാൽ ആ ദൗത്യം നശിച്ചെങ്കിൽ, ഇന്ന് ഇവിടെത്തന്നെ ജീവൻ ഉപേക്ഷിക്കുന്നതാണ് ഭേദം.\"",
        "0.12": "\"ഇന്ന് ഞാൻ തീയിൽ ചാടണോ, അതോ സമുദ്രത്തിനടിയിലെ അഗ്നിയിൽ ചാടണോ, അതോ സമുദ്രത്തിൽ ജീവിക്കുന്ന ജീവികൾക്ക് ശരീരം നൽകണോ?\"",
        "0.13": "\"ദൗത്യം മുഴുവൻ നശിപ്പിച്ച ഞാൻ, ജീവനോടിരിക്കെ വാനരരാജാവിനെയോ ആ രണ്ടു മനുഷ്യസിംഹങ്ങളെയോ എങ്ങനെ നേരിടും?\"",
        "0.14": "\"കോപത്തിന്റെ തെറ്റിനാൽ, മൂന്നു ലോകത്തും വാനരസ്വഭാവം അറിയപ്പെടുന്ന ആ ചാഞ്ചല്യം ഞാൻ പ്രകടിപ്പിച്ചു.\"",
        "0.15": "\"നിയന്ത്രണമില്ലാത്ത, സ്ഥിരതയില്ലാത്ത ഈ രജോഗുണകോപത്തിന് ലജ്ജ! കഴിവുണ്ടായിട്ടും, ഈ വികാരത്തിൽ ഞാൻ സീതയെ സംരക്ഷിച്ചില്ല.\"",
        "0.16": "\"സീത മരിച്ചെങ്കിൽ, ആ രണ്ടുപേരും മരിക്കും; അവർ മരിച്ചാൽ സുഗ്രീവനും അദ്ദേഹത്തിന്റെ ബന്ധുക്കളും മരിക്കും.\"",
        "0.17": "\"ഈ വാർത്ത കേട്ടാൽ, സഹോദരനെ സ്നേഹിക്കുന്ന, ധർമ്മിഷ്ഠനായ ഭരതനും അവനോടൊപ്പമുള്ള ശത്രുഘ്നനും എങ്ങനെ ജീവിക്കാൻ കഴിയും?\"",
        "0.18": "\"ധർമ്മിഷ്ഠമായ ഇക്ഷ്വാകുവംശം നശിച്ചാൽ, എല്ലാ ജനങ്ങളും സംശയമില്ലാതെ ദുഃഖത്താലും വേദനയാലും പീഡിതരാകും.\"",
        "0.19": "\"അതിനാൽ, ഭാഗ്യദോഷിയായ ഞാൻ, ധർമ്മവും അർത്ഥവും നഷ്ടപ്പെടുത്തി, കോപത്തിന്റെ തകരാറിൽ മനസ്സ് ബാധിച്ച് ലോകനാശകനായിത്തീർന്നു.\"",
        "0.20": "ഇങ്ങനെ ചിന്തിക്കുമ്പോൾ, മുൻപ് ശ്രദ്ധിച്ചിരുന്ന ശകുനങ്ങൾ വീണ്ടും പ്രത്യക്ഷപ്പെട്ടു; അവയെക്കുറിച്ച് അദ്ദേഹം നേരിട്ട് വീണ്ടും ചിന്തിച്ചു.",
        "0.21": "\"അല്ലെങ്കിൽ, മനോഹരാംഗിയായ, ശുഭയായ സ്ത്രീ തന്റെ സ്വന്തം ശക്തിയാൽ സംരക്ഷിക്കപ്പെട്ട്, നശിക്കില്ലായിരിക്കാം; തീ തീയിൽ പ്രവർത്തിക്കുന്നില്ലല്ലോ.\"",
        "0.22": "\"ധർമ്മിഷ്ഠനായ, അതിരില്ലാത്ത തേജസ്സുള്ളവന്റെ ഭാര്യയെ അവളുടെതന്നെ സദ്ഗുണത്താൽ സംരക്ഷിക്കപ്പെട്ടവളെ തീക്ക് തൊടാനാവില്ല.\"",
        "0.23": "\"രാമന്റെ ശക്തിയാലും വൈദേഹിയുടെ പുണ്യത്താലുമാണ് ദഹിപ്പിക്കുക എന്ന ജോലിയുള്ള ഈ തീ എന്നെ പൊള്ളിക്കാതിരുന്നത്.\"",
        "0.24": "\"ഭരതനെ മൂത്തവനാക്കിയ മൂന്നു സഹോദരന്മാർക്കും ദേവതയായവളും, രാമന്റെ ഹൃദയത്തിന് ആനന്ദവുമായവൾ എങ്ങനെ നശിക്കും?\"",
        "0.25": "\"എല്ലായിടത്തും ജ്വലിപ്പിക്കുന്ന ഈ നശിക്കാത്ത അഗ്നി എന്റെ വാലിനെ ദഹിപ്പിക്കുന്നില്ലെങ്കിൽ, കുലീനയായ സ്ത്രീയെ അത് എങ്ങനെ ദഹിപ്പിക്കും?\"",
        "0.26": "അപ്പോൾ ഹനുമാൻ അത്ഭുതപ്പെട്ടു; സമുദ്രമധ്യത്തിൽ സ്വർണ്ണശിഖരമുള്ള പർവതം പ്രത്യക്ഷപ്പെട്ടത് അദ്ദേഹം വീണ്ടും ഓർത്തു.",
        "0.27": "\"തപസ്സിനാലും സത്യവാക്കിനാലും ഭർത്താവിനോടുള്ള ഏകാഗ്രഭക്തിയാലും അവൾക്ക് അഗ്നിയെത്തന്നെ ദഹിപ്പിക്കാം; അഗ്നി അവളെ ദഹിപ്പിക്കില്ല.\"",
        "0.28": "ദേവിയുടെ ധർമ്മത്തിലുള്ള ഉറച്ച പിടിത്തത്തെക്കുറിച്ച് ഹനുമാൻ ഇങ്ങനെ ചിന്തിക്കുമ്പോൾ, അവിടെവെച്ച് മഹാത്മാക്കളായ ചാരണന്മാരുടെ വാക്കുകൾ അദ്ദേഹം കേട്ടു:",
        "0.29": "\"ഹാ, എന്തൊരു കർമ്മം! ഗ്രഹിക്കാൻ പ്രയാസമായത് ഹനുമാൻ ചെയ്തിരിക്കുന്നു; രാക്ഷസന്മാരുടെ വാസസ്ഥലത്ത് ഈ ഭയങ്കര കഠിന അഗ്നി അഴിച്ചുവിട്ടുകൊണ്ട്!\"",
        "0.30": "\"ഓടിപ്പോകുന്ന രാക്ഷസസ്ത്രീകളും കുട്ടികളും വൃദ്ധരും നിറഞ്ഞ്, ജനക്കൂട്ടത്തിന്റെ ബഹളം കൊണ്ട് നിറഞ്ഞ ഈ നഗരം അതിന്റെ പർവതഗുഹകളിലൂടെ വിലപിക്കുന്നതുപോലെ തോന്നുന്നു.\"",
        "0.31": "\"ഗോപുരങ്ങളും കോട്ടമതിലുകളും പ്രവേശനകവാടങ്ങളുമടങ്ങിയ ഈ ലങ്കാനഗരം കത്തിയിരിക്കുന്നു; എന്നിട്ടും ജാനകി കത്തിയിട്ടില്ല — സത്യമായും ഞങ്ങൾക്ക് അത്ഭുതകരമായ ഒരു അദ്ഭുതം!\"",
        "0.32": "അമൃതുപോലെ മധുരമായ ആ വാക്കുകൾ ഹനുമാൻ കേട്ടു; അദ്ദേഹത്തിന്റെ മനസ്സിൽ ആ സന്ദർഭത്തിനു യോജിച്ച സന്തോഷം ഉയർന്നു.",
        "0.33": "താൻ കണ്ട ശകുനങ്ങളുടെ അർത്ഥത്താലും വലിയ യുക്തികളാലും ഋഷിവാക്യങ്ങളാലും ഹനുമാന്റെ മനസ്സ് സന്തോഷിച്ചു.",
        "0.34": "പിന്നെ, ഹൃദയാഭിലാഷം സാധിച്ച്, രാജകുമാരി സുരക്ഷിതയാണെന്നറിഞ്ഞ വാനരൻ, അവളെ ഒരിക്കൽക്കൂടി നേരിൽ കാണാൻ തീരുമാനിച്ച്, മടക്കയാത്രക്ക് പുറപ്പെട്ടു.",
        "0.35": "ഇങ്ങനെ ആദികാവ്യമായ, ശ്രീമദ് രാമായണത്തിലെ വാല്മീകി രചിച്ച സുന്ദരകാണ്ഡത്തിലെ അമ്പത്തിയഞ്ചാം സർഗ്ഗം സമാപിച്ചു."
      },
      "summary": "നഗരം കത്തുന്നത് കണ്ട ഹനുമാന്, സീതയും മരിച്ചിരിക്കാമെന്ന ഭയം തോന്നുന്നു; തന്റെ അവിവേകത്തെ അദ്ദേഹം സ്വയം ശപിക്കുന്നു. ചാരണന്മാർ സീത സുരക്ഷിതയാണെന്ന് പറയുന്നത് കേട്ട് അദ്ദേഹത്തിന് ആശ്വാസം ലഭിക്കുന്നു."
    },
    "sundarakanda-56": {
      "verses": {
        "0.0": "പിന്നെ, ശിംശുപവൃക്ഷച്ചുവട്ടിലിരുന്ന ജാനകിയെ വണങ്ങി, അദ്ദേഹം പറഞ്ഞു: \"ഭാഗ്യവശാൽ നീ ഇവിടെ സുരക്ഷിതയായി ഇരിക്കുന്നത് ഞാൻ കാണുന്നു.\"",
        "0.1": "പോകാനൊരുങ്ങിയ ഹനുമാനെ വീണ്ടുംവീണ്ടും നോക്കി, ഭർത്താവിനോടുള്ള സ്നേഹം നിറഞ്ഞ സീത അദ്ദേഹത്തോട് സംസാരിച്ചു:",
        "0.2": "\"നിനക്ക് ശരിയെന്ന് തോന്നുന്നെങ്കിൽ, കുറ്റമറ്റവനേ, ഒരു ദിവസം ഇവിടെ താമസിക്കൂ; ഏതെങ്കിലും നന്നായി മറഞ്ഞ സ്ഥലത്ത് വിശ്രമിച്ച്, നാളെ പോകൂ.\"",
        "0.3": "\"വാനരാ, നിന്റെ സാമീപ്യത്താൽ, ഭാഗ്യദോഷിയായ എനിക്ക് അതിരില്ലാത്ത ദുഃഖം ഒരു നിമിഷത്തേക്കെങ്കിലും ലഘുവായേക്കാം.",
        "0.4": "\"വാനരശ്രേഷ്ഠാ, നീ പോയാൽ, നീ മടങ്ങിവരുന്നതുവരെ എന്റെ ജീവനെക്കുറിച്ചുപോലും എനിക്ക് ഉറപ്പില്ല.\"",
        "0.5": "\"വീരാ, നിന്നെ വീണ്ടും കാണാത്തത് എന്റെ ഹൃദയം തകർക്കും — ദുഃഖത്തിൽനിന്ന് ആഴമേറിയ ദുഃഖത്തിലേക്ക് പോയ, ദുഃഖവും വേദനയും കൊണ്ട് ക്ഷീണിച്ച ഞാൻ.\"",
        "0.6": "\"വീരാ, ഈ സംശയം എന്റെ മുന്നിൽ നിൽക്കുന്നതുപോലെയാണ്: വാനരരും കരടികളുമായ തന്റെ മഹാസഹായികളോടൊപ്പം ശക്തനായ സുഗ്രീവൻ —\"",
        "0.7": "\"കടക്കാനാവാത്ത സമുദ്രം എങ്ങനെ കടക്കും — ആ വാനരസൈന്യങ്ങളോ, അല്ലെങ്കിൽ ഉത്തമപുരുഷന്റെ ആ രണ്ടു പുത്രന്മാരോ എങ്ങനെ?\"",
        "0.8": "\"സമുദ്രം ചാടിക്കടക്കാൻ മൂന്നു ജീവികൾക്ക് മാത്രമേ ശക്തിയുള്ളൂ — വിനതയുടെ പുത്രനായ ഗരുഡൻ, നീ, പിന്നെ വായുദേവൻ.\"",
        "0.9": "\"അതിനാൽ, ഈ പ്രയാസകരമായ പ്രശ്നത്തിനു മുന്നിൽ, നീ എന്ത് പരിഹാരമാണ് കാണുന്നത്? കാര്യങ്ങൾ സാധിക്കുന്നതിൽ നീ വിദഗ്ധനല്ലോ.\"",
        "0.10": "\"സത്യമാണ്, ശത്രുവീരന്മാരെ വധിക്കുന്നവനേ, ഈ ദൗത്യം നിർവ്വഹിക്കാൻ നീ മാത്രം മതി; അതിന്റെ ഫലം നിനക്ക് കീർത്തി നൽകും.\"",
        "0.11": "\"എന്നാൽ ശത്രുസൈന്യങ്ങളെ തകർക്കുന്ന കാകുത്സ്ഥൻ തന്റെ സേനകൊണ്ട് ലങ്ക നിറച്ചിട്ട് എന്നെ കൊണ്ടുപോയാൽ അതാണ് അവന് യോജിച്ചത്.\"",
        "0.12": "\"ആ മഹാത്മാവായ വീരന്റെ യുദ്ധവീര്യത്തിന് യോജിക്കുന്ന വിധത്തിൽ പ്രവൃത്തി ചെയ്യിക്കൂ.\"",
        "0.13": "ഈ വാക്കുകൾ കേട്ട്, അർത്ഥഗർഭവും വിനീതവും നന്നായി യുക്തിയുള്ളതുമായ വാക്കുകളാൽ, വീരനായ ഹനുമാൻ മറുപടി പറഞ്ഞു:",
        "0.14": "\"ദേവീ, വാനരകരടിസൈന്യങ്ങളുടെ നാഥനും, ചാട്ടക്കാരിൽ ഉത്തമനും, ശക്തിനിറഞ്ഞവനുമായ സുഗ്രീവൻ നിനക്കുവേണ്ടി മനസ്സുറപ്പിച്ചിരിക്കുന്നു.\"",
        "0.15": "\"കോടികളുടെ പതിനായിരക്കണക്കിന് വാനരന്മാരാൽ ചുറ്റപ്പെട്ട് വാനരനാഥനായ സുഗ്രീവൻ ഉടൻ വരും, വൈദേഹീ.\"",
        "0.16": "\"ആ രണ്ടു വീരന്മാർ, മനുഷ്യശ്രേഷ്ഠന്മാരായ രാമനും ലക്ഷ്മണനും ഒരുമിച്ച് ലങ്കാനഗരത്തിൽ എത്തി, തങ്ങളുടെ അമ്പുകൾകൊണ്ട് അതിനെ തകർക്കും.\"",
        "0.17": "\"രാക്ഷസനെ സൈന്യത്തോടൊപ്പം വധിച്ച്, രഘുവംശത്തിന്റെ ആനന്ദമായവൻ താമസിയാതെ നിന്നെ, സുന്ദരീ, കൂട്ടിക്കൊണ്ട് സ്വന്തം നഗരത്തിലേക്ക് മടങ്ങും.\"",
        "0.18": "\"ധൈര്യമായിരിക്കൂ, നിനക്ക് ശുഭമുണ്ടാകട്ടെ; ശരിയായ സമയത്തിനായി കാത്തിരിക്കൂ. താമസിയാതെ യുദ്ധത്തിൽ രാമനാൽ വധിക്കപ്പെട്ട രാവണനെ നീ കാണും.\"",
        "0.19": "\"രാക്ഷസരാജാവ് പുത്രന്മാരോടും മന്ത്രിമാരോടും ബന്ധുക്കളോടുമൊപ്പം വധിക്കപ്പെടുമ്പോൾ, ചന്ദ്രനോടൊപ്പം രോഹിണിയെപ്പോലെ നീ രാമനോട് ഒന്നുചേരും.\"",
        "0.20": "\"കാകുത്സ്ഥൻ വാനരശ്രേഷ്ഠന്മാരും കരടികളുമായി താമസിയാതെ വരും; യുദ്ധത്തിൽ ശത്രുക്കളെ കീഴടക്കി അവൻ നിന്റെ ദുഃഖം അകറ്റും.\"",
        "0.21": "ഇങ്ങനെ വൈദേഹിയെ ആശ്വസിപ്പിച്ച്, വായുപുത്രനായ ഹനുമാൻ പോകാൻ തീരുമാനിച്ച്, വൈദേഹിയെ വണങ്ങി.",
        "0.22": "ശ്രേഷ്ഠരായ രാക്ഷസന്മാരെ വധിച്ച്, തന്റെ പേര് പ്രഖ്യാപിച്ച്, വൈദേഹിയെ ആശ്വസിപ്പിച്ച്, തന്റെ പരമശക്തി പ്രകടിപ്പിച്ച്,",
        "0.23": "നഗരത്തെ കോലാഹലത്തിലാക്കി, രാവണനെ തന്ത്രത്തിൽ തോൽപ്പിച്ച്, തന്റെ ഭയങ്കര പരാക്രമം കാണിച്ച്, വൈദേഹിയെ വണങ്ങി —",
        "0.24": "സമുദ്രത്തിന്റെ മധ്യത്തിലൂടെ വീണ്ടും മടങ്ങാൻ അദ്ദേഹം തീരുമാനിച്ചു. പിന്നെ ആ വാനരശ്രേഷ്ഠൻ, തന്റെ യജമാനനെ കാണാനുള്ള ആഗ്രഹത്താൽ,",
        "0.25": "ശത്രുഘാതകനായി, ഉയരമുള്ള പത്മകവൃക്ഷങ്ങൾ നിറഞ്ഞ ഇരുണ്ട വനനിരകളോടുകൂടിയ, പർവതശ്രേഷ്ഠനായ അരിഷ്ടത്തിൽ കയറി.",
        "0.26": "അതിന്റെ കൊടുമുടികൾക്കിടയിൽ തൂങ്ങിക്കിടക്കുന്ന മേഘങ്ങളുടെ മേൽവസ്ത്രം അണിഞ്ഞതുപോലെയും, സൂര്യന്റെ തിളങ്ങുന്ന രശ്മികളാൽ സ്നേഹപൂർവ്വം ഉണർത്തപ്പെട്ടതുപോലെയും അത് തോന്നി.",
        "0.27": "തിളങ്ങുന്ന ധാതുസമ്പത്തിന്റെ വരകളാൽ കണ്ണുകൾ തുറക്കുന്നതുപോലെയും, അരുവികളുടെ ഗംഭീര ശബ്ദത്താൽ ഉറക്കെ പാരായണം ചെയ്യുന്നതുപോലെയും അത് തോന്നി.",
        "0.28": "അനേകം ഉറവുകളുടെ ശബ്ദങ്ങളാൽ വ്യക്തമായി പാടുന്നതുപോലെയും, ഉയർന്ന ദേവദാരുക്കളിൽ കൈകൾ ഉയർത്തി നിൽക്കുന്നതുപോലെയും അത് തോന്നി.",
        "0.29": "വെള്ളച്ചാട്ടങ്ങളുടെ ഇരമ്പലാൽ എല്ലാ ഭാഗത്തും നിലവിളിക്കുന്നതുപോലെയും, ആടിയുലയുന്ന ഇരുണ്ട ശരത്കാല വനങ്ങളാൽ വിറയ്ക്കുന്നതുപോലെയും അത് തോന്നി.",
        "0.30": "കാറ്റിൽ ഇളകുന്ന പൊള്ളയായ മുളകളിലൂടെ ചൂളമടിക്കുന്നതുപോലെയും, ഭയങ്കര വലിയ സർപ്പങ്ങളാൽ കോപത്തോടെ ചീറുന്നതുപോലെയും അത് തോന്നി.",
        "0.31": "ആഴമേറിയ മഞ്ഞുനിറഞ്ഞ ഗുഹകളിൽ ധ്യാനിക്കുന്നതുപോലെയും, മേഘസമാനമായ താഴ്വരകളോടെ എല്ലാ ഭാഗത്തേക്കും നടക്കുന്നതുപോലെയും അത് തോന്നി.",
        "0.32": "മേഘം പുതച്ച കൊടുമുടികളോടെ ആകാശത്ത് കോട്ടുവായിടുന്നതുപോലെയും, അനേകം ശിഖരങ്ങൾ നിറഞ്ഞും അനേകം ഗുഹകളാൽ അലങ്കരിക്കപ്പെട്ടും ഉള്ള ആ മലയിൽ —",
        "0.33": "സാലവൃക്ഷങ്ങൾ, പനകൾ, കർണികാരവൃക്ഷങ്ങൾ, മുളകൾ എന്നിവ നിറഞ്ഞും, പൂക്കളുള്ള വള്ളിപ്പടർപ്പുകളുടെ വ്യാപിച്ച മേൽക്കൂരകളാൽ അലങ്കരിക്കപ്പെട്ടും;",
        "0.34": "പലതരം മൃഗങ്ങൾ നിറഞ്ഞും, ഒഴുകുന്ന ധാതുക്കളാൽ അലങ്കരിക്കപ്പെട്ടും, ഉറവുകൾ നിറഞ്ഞും, പാറക്കൂട്ടങ്ങളാൽ തിങ്ങിനിറഞ്ഞും;",
        "0.35": "മഹർഷിമാർ, യക്ഷന്മാർ, ഗന്ധർവന്മാർ, കിന്നരന്മാർ, സർപ്പങ്ങൾ എന്നിവർ സഞ്ചരിക്കുന്നതും, വള്ളിപ്പടർപ്പുകളും മരങ്ങളും ഇടതൂർന്നതും, ഗുഹകളിൽ സിംഹങ്ങൾ വസിക്കുന്നതുമായ;",
        "0.36": "കടുവകളും മറ്റ് മൃഗങ്ങളും നിറഞ്ഞതും, മധുരമുള്ള വേരുകളും കായ്കനികളും നൽകുന്ന മരങ്ങളുള്ളതുമായ ആ പർവതത്തിൽ വായുപുത്രനായ വാനരശ്രേഷ്ഠൻ കയറി,",
        "0.37": "രാമനെ കാണാനുള്ള സന്തോഷത്താലും തിടുക്കത്താലും പ്രേരിതനായി. മനോഹരമായ മലഞ്ചെരിവുകളിൽ അദ്ദേഹത്തിന്റെ പാദങ്ങളാൽ ചവിട്ടപ്പെട്ട്,",
        "0.38": "പാറകൾ പൊട്ടിച്ചിതറി പൊടിയായി. ആ പർവതരാജാവിൽ കയറിയ മഹാവാനരൻ വലുതായി വളർന്നു,",
        "0.39": "തെക്കുനിന്ന് ഉപ്പുവെള്ള സമുദ്രത്തിന്റെ വടക്കേ തീരത്തെത്താൻ ആഗ്രഹിച്ച്. പിന്നെ, പർവതത്തിൽ കയറിയ വീരനായ വായുപുത്രൻ,",
        "0.40": "ഭയങ്കര സർപ്പങ്ങൾ വസിക്കുന്ന ഭയാനകമായ സമുദ്രം കണ്ടു. കാറ്റുപോലെ, കാറ്റിന്റെ സ്വന്തം പുത്രൻ ആകാശത്തേക്ക് കുതിച്ചു;",
        "0.41": "വാനരശ്രേഷ്ഠൻ തെക്കുനിന്ന് വടക്കോട്ട് പുറപ്പെട്ടു. ആ വാനരന്റെ അമർത്തലിൽ പർവതശ്രേഷ്ഠൻ,",
        "0.42": "അനേകം ജീവികളോടെ നിലവിളിച്ചു, കൊടുമുടികൾ വിറച്ചും മരങ്ങൾ വീണും, ഭൂമിയിലേക്ക് താഴ്ന്നുപോയി.",
        "0.43": "തുടകളുടെ ബലത്താൽ ഇളക്കപ്പെട്ട്, പൂവിട്ട മരങ്ങൾ ഇന്ദ്രായുധമേറ്റതുപോലെ ഒടിഞ്ഞ് നിലത്തുവീണു.",
        "0.44": "ഗുഹകളുടെ ആഴങ്ങളിൽ വസിക്കുന്ന മഹാസിംഹങ്ങളുടെ ഭയങ്കര ഗർജ്ജനം, തകർക്കപ്പെട്ട്, ആകാശം പിളരുന്നതുപോലെ കേട്ടു.",
        "0.45": "ഭയന്നുപോയ വിദ്യാധര സ്ത്രീകൾ, വസ്ത്രങ്ങൾ അലസമായും ആഭരണങ്ങൾ ക്രമംതെറ്റിയും, പെട്ടെന്ന് ആ മലയിൽനിന്ന് പറന്നുയർന്നു.",
        "0.46": "ഇളകുന്ന നാക്കുകളും മാരകവിഷവുമുള്ള വലിയ ശക്തരായ സർപ്പങ്ങൾ, തലകളും കഴുത്തുകളും തകർന്ന്, പുളഞ്ഞുകൊണ്ടിരുന്നു.",
        "0.47": "കിന്നരന്മാർ, സർപ്പങ്ങൾ, ഗന്ധർവന്മാർ, യക്ഷന്മാർ, വിദ്യാധരന്മാർ — തകർന്ന ആ മലവിട്ട് അവർ ആകാശത്തേക്ക് പറന്നു.",
        "0.48": "ശക്തനായവൻ അമർത്തിയ, മഹിമയുള്ള ആ പർവതം അതിന്റെ മരങ്ങളും ഉയർന്ന ശിഖരങ്ങളുമായി പാതാളത്തിലേക്ക് താഴ്ന്നുപോയി.",
        "0.49": "പത്തു യോജന വീതിയും മുപ്പതു യോജന ഉയരവുമുള്ള ആ പർവതം ഭൂമിയോട് സമമാക്കപ്പെട്ടു.",
        "0.50": "തിരമാലകൾ അടിക്കുന്ന തീരമുള്ള, ഭയങ്കരമായ ഉപ്പുവെള്ള സമുദ്രം സുഖമായി ചാടിക്കടക്കാൻ ആഗ്രഹിച്ച്, വാനരൻ ആകാശത്തേക്ക് കുതിച്ചുയർന്നു.",
        "0.51": "ഇങ്ങനെ ആദികാവ്യമായ, ശ്രീമദ് രാമായണത്തിലെ വാല്മീകി രചിച്ച സുന്ദരകാണ്ഡത്തിലെ അമ്പത്തിയാറാം സർഗ്ഗം സമാപിച്ചു."
      },
      "summary": "ശിംശുപവൃക്ഷച്ചുവട്ടിൽ ഒരിക്കൽക്കൂടി സീതയെ കണ്ട്, അവളെ ആശ്വസിപ്പിച്ച് ഹനുമാൻ യാത്രപറയുന്നു. അരിഷ്ടപർവതത്തിൽ കയറി, മടക്കയാത്രയ്ക്കായി ആകാശത്തേക്ക് കുതിക്കുന്നു."
    },
    "sundarakanda-57": {
      "verses": {
        "0.0": "ചിറകുള്ള പർവതംപോലെ വലിയ വേഗത്തിൽ ഉയർന്നുചാടി, ഹനുമാൻ ആകാശമാകുന്ന സമുദ്രം കടന്നു; അതിൽ സർപ്പങ്ങളും യക്ഷന്മാരും ഗന്ധർവന്മാരും വിരിഞ്ഞ താമരകളും ആമ്പലുകളും പോലെയായിരുന്നു;",
        "0.1": "അതിലെ മനോഹര വെള്ള ആമ്പലായി ചന്ദ്രനും, കാരണ്ഡവം താറാവായി സൂര്യനും, അരയന്നങ്ങളായി തിഷ്യ, ശ്രവണം നക്ഷത്രങ്ങളും, പായലും പുല്ലും മേഘങ്ങളുമായിരുന്നു;",
        "0.2": "വലിയ മത്സ്യമായി പുനർവസുവും, വലിയ മുതലയായി ചൊവ്വയും, വലിയ ദ്വീപായി ഐരാവതവും, അരയന്നമായി സ്വാതിയാൽ അലങ്കരിക്കപ്പെട്ട സമുദ്രം;",
        "0.3": "തിരമാലകൾ വായുവിന്റെ കൂട്ടങ്ങളും തണുത്ത വെള്ളം ചന്ദ്രരശ്മികളുമായ ആ ആകാശസമുദ്രം ഹനുമാൻ ക്ഷീണിക്കാതെ കടന്നു.",
        "0.4": "ആകാശം വിഴുങ്ങുന്നതുപോലെയും, ചന്ദ്രനെ മേയുന്നതുപോലെയും, നക്ഷത്രങ്ങളോടും സൂര്യബിംബത്തോടുംകൂടിയ സ്വർഗ്ഗങ്ങളെ കൊണ്ടുപോകുന്നതുപോലെയും അദ്ദേഹം പോയി.",
        "0.5": "ക്ഷീണമില്ലാതെ, ഹനുമാൻ ആ അതിരില്ലാത്ത ആകാശസമുദ്രത്തിലൂടെ ആഴ്ന്നിറങ്ങി; മേഘക്കൂട്ടങ്ങളെ തന്നോടൊപ്പം വലിച്ചുകൊണ്ടുപോകുന്നതുപോലെ സഞ്ചരിച്ചു.",
        "0.6": "വെളുപ്പും ചുവപ്പും നീലയും മഞ്ഞച്ചായയും പച്ചയും ചെമ്പുനിറവുമുള്ള വലിയ മേഘങ്ങൾ അവിടെ തിളങ്ങി.",
        "0.7": "മേഘക്കൂട്ടങ്ങളിൽ പലതവണ കടന്നും പുറത്തുവന്നും, ചിലപ്പോൾ കാണപ്പെട്ടും ചിലപ്പോൾ മറഞ്ഞും ചന്ദ്രനെപ്പോലെ അദ്ദേഹം തോന്നി.",
        "0.8": "പലതരം മേഘങ്ങളിലൂടെ കടന്ന്, വെള്ള വസ്ത്രമണിഞ്ഞ ആ വീരൻ, ശരീരം ചിലപ്പോൾ ദൃശ്യമായും ചിലപ്പോൾ അദൃശ്യമായും, ആകാശത്ത് ചന്ദ്രനെപ്പോലെ പ്രത്യക്ഷപ്പെട്ടു.",
        "0.9": "ആകാശത്ത് ഗരുഡനെപ്പോലെ, വായുപുത്രൻ മേഘപാളികൾ കീറിമുറിച്ച് പലതവണ അവയിൽനിന്ന് പുറത്തുചാടി തിളങ്ങി.",
        "0.10": "ഇടിമുഴക്കംപോലെ ശക്തമായ ഗർജ്ജനം മുഴക്കി, പ്രധാന രാക്ഷസന്മാരെ വധിച്ച്ശേഷം സ്വന്തം പേര് പ്രഖ്യാപിച്ച അദ്ദേഹം,",
        "0.11": "നഗരത്തെ കോലാഹലത്തിലാക്കി, രാവണനെ അലട്ടി, മഹാവീരന്മാരെ തകർത്ത്, സീതയെ വണങ്ങിയ ശേഷം,",
        "0.12": "ഇപ്പോൾ ആ മഹാതേജസ്വി സമുദ്രത്തിന്റെ മധ്യത്തിലൂടെ തിരിച്ചുവന്നു; വഴിയിൽ പർവതരാജാവായ സുനാഭനെ തൊട്ടുകൊണ്ട്.",
        "0.13": "വില്ലിന്റെ ഞാണിൽനിന്ന് തൊടുത്ത അമ്പുപോലെ അദ്ദേഹം വേഗത്തിൽ മുന്നോട്ടുപോയി; കുറച്ചുകൂടി അടുത്തെത്തിയപ്പോൾ ആ മഹാപർവതം അദ്ദേഹത്തിന്റെ കണ്ണിൽപ്പെട്ടു.",
        "0.14": "മേഘസമാനമായ മഹേന്ദ്രപർവതം കണ്ട മഹാവാനരൻ ഗർജ്ജിച്ചു; പത്തു ദിക്കുകളെയും എല്ലാ വശങ്ങളിലും നിറച്ചുകൊണ്ട്.",
        "0.15": "ഇടിമുഴക്കംപോലെ ശക്തമായ ഗർജ്ജനത്തോടെ അദ്ദേഹം ആ പ്രദേശത്തെത്തി; സുഹൃത്തുക്കളെ കാണാനുള്ള ആഗ്രഹത്താൽ.",
        "0.16": "അദ്ദേഹം മഹാഗർജ്ജനം മുഴക്കി വാൽ അടിച്ചു; ഗരുഡൻ സഞ്ചരിച്ച വഴിയിൽ അദ്ദേഹം വീണ്ടും വീണ്ടും ഗർജ്ജിക്കുമ്പോൾ,",
        "0.17": "ആ ശബ്ദം കേട്ട്, സൂര്യബിംബത്തോടൊപ്പമുള്ള ആകാശം പിളരുന്നതുപോലെ തോന്നി. അപ്പോൾ സമുദ്രത്തിന്റെ വടക്കേ തീരത്ത് കാത്തിരുന്ന മഹാവീരന്മാർ,",
        "0.18": "മുമ്പും അവിടെ ഇരുന്ന്, വായുപുത്രനെ കാണാനുള്ള ആഗ്രഹത്താൽ, കാറ്റാൽ നയിക്കപ്പെടുന്ന വലിയ മേഘത്തിന്റെ ഇടിമുഴക്കംപോലെ ഹനുമാന്റെ കുതിക്കുന്ന തുടകളുടെ ഗർജ്ജനം കേട്ടു.",
        "0.19": "ദുഃഖിതരായിരുന്ന എല്ലാ വനവാസികളും, ആ വാനരനാഥന്റെ ഗർജ്ജനം മഴമേഘത്തിന്റെ മുഴക്കംപോലെ കേട്ടു.",
        "0.20": "ആ ഗർജ്ജനം കേട്ട്, ചുറ്റുമുള്ള വാനരന്മാർ ആവേശഭരിതരായി, തങ്ങളുടെ സുഹൃത്തിനെ കാണാൻ ആഗ്രഹിച്ചു.",
        "0.21": "വാനരശ്രേഷ്ഠനായ ജാംബവാൻ, ഹൃദയം സന്തോഷത്താൽ പുളകിതമായി, എല്ലാ വാനരന്മാരെയും വിളിച്ചുകൂട്ടി ഈ വാക്കുകൾ പറഞ്ഞു:",
        "0.22": "\"ഹനുമാൻ തന്റെ ദൗത്യം തീർച്ചയായും നിറവേറ്റിയിരിക്കുന്നു, അതിൽ സംശയമില്ല; പരാജയപ്പെട്ടിരുന്നെങ്കിൽ അവന്റെ ഗർജ്ജനം ഇങ്ങനെയാകുമായിരുന്നില്ല.\"",
        "0.23": "ആ മഹാവാനരന്റെ കൈകളുടെയും തുടകളുടെയും കുതിപ്പും ഗർജ്ജനവും കേട്ട്, വാനരന്മാർ സന്തോഷത്തോടെ ഇവിടെയും അവിടെയും ചാടിയുയർന്നു.",
        "0.24": "ഹനുമാനെ കാണാനുള്ള ആഗ്രഹത്താൽ, അവർ ആനന്ദത്തോടെ മരക്കൊമ്പിൽനിന്ന് മരക്കൊമ്പിലേക്കും, കൊടുമുടിയിൽനിന്ന് കൊടുമുടിയിലേക്കും ചാടി.",
        "0.25": "സന്തോഷിച്ച വാനരന്മാർ മരച്ചില്ലകൾ പിടിച്ച് മരത്തലപ്പുകളിൽ ഇരുന്ന്, തിളക്കമുള്ള വസ്ത്രങ്ങൾ വീശി.",
        "0.26": "പർവതഗുഹയിൽ കാറ്റ് കുടുങ്ങുമ്പോൾ ഗർജ്ജിക്കുന്നതുപോലെ, വായുപുത്രനായ മഹാബലശാലി ഹനുമാൻ ഗർജ്ജിച്ചു.",
        "0.27": "വലിയ മേഘംപോലെ താഴേക്ക് പറന്നിറങ്ങുന്ന മഹാവാനരനെ കണ്ട്, എല്ലാ വാനരന്മാരും കൈകൂപ്പി നിന്നു.",
        "0.28": "പിന്നെ വേഗമുള്ള വീരനും പർവതസമാനനുമായ വാനരൻ, ആ പർവതത്തിന്റെ മരങ്ങൾ നിറഞ്ഞ കൊടുമുടിയിൽ ഇറങ്ങി.",
        "0.29": "സന്തോഷത്താൽ നിറഞ്ഞ്, ചിറകറ്റ് ആകാശത്തുനിന്ന് വീഴുന്ന പർവതംപോലെ, മനോഹരമായ ഒരു പർവതനദിയുടെ അരികിൽ അദ്ദേഹം ഇറങ്ങി.",
        "0.30": "പിന്നെ ഹൃദയം സന്തോഷിച്ച എല്ലാ ശ്രേഷ്ഠ വാനരന്മാരും മഹാത്മാവായ ഹനുമാനെ ചുറ്റിക്കൂടി.",
        "0.31": "എല്ലാവരും ആനന്ദത്തോടെയും പുഞ്ചിരിയോടെയും അദ്ദേഹത്തെ വളഞ്ഞ്, മടങ്ങിവന്നവനോട് അടുത്തുചേർന്നു.",
        "0.32": "വേരുകളും കായ്കനികളും സമ്മാനമായി കൊണ്ടുവന്ന്, വാനരന്മാർ വാനരശ്രേഷ്ഠനും വായുപുത്രനുമായ ഹനുമാനെ ആദരിച്ചു.",
        "0.33": "ചിലർ ആഹ്ലാദത്താൽ ആർത്തുവിളിച്ചു, ചിലർ \"കില-കില\" എന്ന് ശബ്ദിച്ചു; സന്തോഷിച്ച വാനരന്മാർ അദ്ദേഹത്തിന് ഇലച്ചില്ലകൾ കൊണ്ടുവന്നു.",
        "0.34": "പിന്നെ മഹാവാനരനായ ഹനുമാൻ ജാംബവാനും മറ്റ് മുതിർന്നവർക്കും, അങ്ങനെതന്നെ അംഗദ രാജകുമാരനും വന്ദനം ചെയ്തു.",
        "0.35": "ആ രണ്ടുപേരുടെയും ആദരവ് ലഭിച്ചും വാനരന്മാരുടെ ഊഷ്മളമായ സ്വീകരണത്താൽ ആദരിക്കപ്പെട്ടും, ബഹുമാനത്തിന് അർഹനായ ആ വീരൻ അവരോട് ചുരുക്കമായി പറഞ്ഞു: \"ഞാൻ രാജ്ഞിയെ കണ്ടു.\"",
        "0.36": "വാലിയുടെ പുത്രനെ കൈപിടിച്ച്, അദ്ദേഹം മഹേന്ദ്രപർവതത്തിലെ മനോഹരമായ ഒരു വനപ്രദേശത്ത് ഇരുന്നു.",
        "0.37": "ചോദിച്ചപ്പോൾ, ഹനുമാൻ ആ പ്രധാന വാനരന്മാരോട് പറഞ്ഞു: \"അശോകവനത്തിൽ താമസിക്കുന്ന ജനകപുത്രിയെ ഞാൻ കണ്ടു,",
        "0.38": "ഭയങ്കര രാക്ഷസിമാരാൽ കാക്കപ്പെട്ട, ഒരു ജടമാത്രം കെട്ടിയ, രാമനെ കാണാൻ ആഗ്രഹിക്കുന്ന, കുറ്റമറ്റ യുവതിയെ.",
        "0.39": "ഉപവാസംകൊണ്ട് ക്ഷീണിച്ച്, കുളിക്കാതെ, മുടി കെട്ടുപിണഞ്ഞ്, മെലിഞ്ഞ്.\" പിന്നെ വായുപുത്രനിൽനിന്ന് \"അവളെ കണ്ടു\" എന്ന മഹത്തായ, അമൃതുപോലുള്ള വാക്കുകൾ കേട്ട്,",
        "0.40": "എല്ലാ വാനരന്മാരും സന്തോഷിച്ചു; ചില മഹാബലശാലികൾ ആർപ്പുവിളിച്ചു, മറ്റു ചിലർ ആക്രോശിച്ചു, വേറെ ചിലർ ഗർജ്ജിച്ചു;",
        "0.41": "ചിലർ \"കില-കില\" എന്ന് ശബ്ദിച്ചു, മറ്റു ചിലർ മറുപടിയായി ഗർജ്ജിച്ചു; ആനകൾപോലുള്ള ചില വാനരന്മാർ, ആവേശത്തോടെ വാലുകൾ ഉയർത്തി,",
        "0.42": "നീണ്ടതും വളഞ്ഞതും നീട്ടിപ്പിടിച്ചതുമായ വാലുകൾ ചുഴറ്റി; മറ്റു ചിലർ സന്തോഷത്തോടെ,",
        "0.43": "മഹാവാനരനായ ഹനുമാനെ തൊടാൻ പർവതശിഖരങ്ങളിൽനിന്ന് താഴേക്ക് ചാടി. പിന്നെ റിപ്പോർട്ട് പൂർത്തിയാക്കിയ ഹനുമാനോട് അംഗദൻ സംസാരിച്ചു:",
        "0.44": "എല്ലാ വാനരവീരന്മാരുടെയും മധ്യത്തിൽ, ഈ ഉത്തമവാക്കുകൾ: \"ഓ വാനരാ, ശക്തിയിലും വീര്യത്തിലും നിനക്ക് തുല്യനായി ആരുമില്ല,",
        "0.45": "കാരണം നീ വിശാലമായ സമുദ്രം ചാടിക്കടന്ന് വീണ്ടും മടങ്ങിയെത്തി. വാനരശ്രേഷ്ഠാ, ഞങ്ങളുടെ ജീവൻ നൽകുന്നവൻ നീ മാത്രമാണ്.",
        "0.46": "നിന്റെ കൃപയാൽ ഞങ്ങൾ ലക്ഷ്യം നേടി രാഘവനെ കാണും. യജമാനനോടുള്ള എന്തൊരു ഭക്തി, എന്തൊരു വീര്യം, എന്തൊരു ധൈര്യം!",
        "0.47": "സന്തോഷത്തോടെ നീ പ്രസിദ്ധയായ രാജ്ഞിയെ, രാമന്റെ ഭാര്യയെ കണ്ടു; സന്തോഷത്തോടെ കാകുത്സ്ഥൻ ഇപ്പോൾ സീതയിൽനിന്നുള്ള വേർപാടിന്റെ ദുഃഖം ഉപേക്ഷിക്കും.\"",
        "0.48": "പിന്നെ സന്തോഷിച്ച വാനരന്മാർ അംഗദനെയും ഹനുമാനെയും ജാംബവാനെയും ചുറ്റിക്കൂടി, വിശാലമായ പാറകളിൽ ഇരുന്നു.",
        "0.49": "ആ പർവതത്തിലെ വിശാലമായ പാറകളിൽ ഇരുന്ന്, മാന്യരായ വാനരന്മാർ സമുദ്രം ചാടിക്കടന്നതിനെക്കുറിച്ച് കേൾക്കാൻ ആഗ്രഹിച്ചു,",
        "0.50": "ലങ്കയെയും സീതയെയും രാവണനെയും അവൻ കണ്ടതിനെക്കുറിച്ചും; അവരെല്ലാം കൈകൂപ്പി, മുഖങ്ങൾ ഹനുമാനു നേരെ തിരിച്ച് ഇരുന്നു.",
        "0.51": "ദേവന്മാരാൽ ചുറ്റപ്പെട്ട സ്വർഗ്ഗത്തിലെ ദേവാധിപനെപ്പോലെ, അനേകം വാനരന്മാരാൽ ചുറ്റപ്പെട്ട് തേജസ്വിയായ അംഗദൻ അവിടെ ഇരുന്നു.",
        "0.52": "പ്രസിദ്ധനും തേജസ്വിയുമായ ഹനുമാനോടും, തോൾവളകളണിഞ്ഞ അംഗദനോടും ചേർന്ന് സന്തോഷത്തോടെ അവിടെ ഇരുന്നപ്പോൾ, ആ മഹാ ഉന്നതമായ പർവതശിഖരം തേജസ്സിൽ ജ്വലിച്ചു.",
        "0.53": "ഇങ്ങനെ ആദികാവ്യമായ, ശ്രീമദ് രാമായണത്തിലെ വാല്മീകി രചിച്ച സുന്ദരകാണ്ഡത്തിലെ അമ്പത്തേഴാം സർഗ്ഗം, വാല്മീകിയുടെ ആദികാവ്യം, സമാപിച്ചു."
      },
      "summary": "ഹനുമാൻ ആകാശമാകുന്ന സമുദ്രത്തിലൂടെ പറക്കുന്നു; മഹേന്ദ്രപർവതത്തിനടുത്തെത്തുമ്പോൾ ഗർജ്ജിക്കുന്നു. കാത്തിരുന്ന വാനരന്മാർ സന്തോഷത്തോടെ അദ്ദേഹത്തെ സ്വാഗതം ചെയ്യുന്നു; സീതയെ കണ്ടെന്ന് അദ്ദേഹം ഒറ്റവാക്കിൽ അവരോട് പറയുന്നു."
    }
  },
};
